window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_044"]={"n":"谢榛","dyn":"明","poems":[{"t":"古意 其二","f":"五言绝句","c":["青山无大小，总隔郎行路。","远近生寒云，愁根不知数。"]},{"t":"秋闺 其一","f":"五言绝句","c":["目极江天远，秋霜下白蘋。","可怜南去雁，不为倚楼人。"]},{"t":"塞下曲","f":"五言绝句","c":["暝色满西山，将军猎骑还。","隔河见烽火，骄虏夜临关。"]},{"t":"儿元炜从游沁阳途中值雪有感兼示元煇","f":"五言古诗","c":["邺台衡漳湄，太行何间之。","东西共雨雪，当春复凄其。","纷然皓盈目，宁不兴汝思。","北堂汝亲老，况汝两娇儿。","重轻俱在心，应念寒与饥。","汝父尚行迈，驱马远相随。","野水亦有波，独树亦有枝。","慎勿虚盛年，人生须有为。","广云自广阴，片雨惟片滋。","绿发稍变白，临镜悔已迟。","此言告汝兄，使汝弟兄知。","谁能箕裘业，慰我桑榆时。"]},{"t":"杂感寄都门旧知","f":"五言古诗","c":["瞻彼终南山，松萝幽且邃。","中有一真人，超然远朝市。","手握神龙珠，照夜光自秘。","石苔积古色，斗室廓天地。","涧泉为谁清，蕙花为谁媚。","西望徒遐思，书札何由寄。","嗟哉处流俗，冥心可无醉。","鸱鸮为家祥，凤鸾非世瑞。","奈何君子交，中道两弃置。","不见针与石，相合似同类。","文字生瑕疵，邓林叶纷坠。","有家早归欤，独歌以卒岁。","岁寒元气塞，偃仰待春事。"]},{"t":"自拙叹","f":"五言古诗","c":["出门何所营，萧条掩柴荆。","中除不洒扫，积雨莓苔生。","感时倚孤杖，屋角鸠正鸣。","千拙养气根，一巧丧心萌。","巢由亦偶尔，焉知身后名。","不尽太古色，天末青山横。"]},{"t":"雨中宿榆林店有感","f":"五言古诗","c":["凉雨何冥冥，黑云复浩浩。","山行夜不休，崄巇犹蜀道。","我非王程迫，胡为役衰老。","数口远相将，未必常温饱。","投彼敝屋间，芜秽不及扫。","园荒无主人，马散齧秋草。","席地即吾庐，馀生聊自保。","隔林乞火回，酌酒慰怀抱。","愚者昧所适，哲人见机早。","反为细君嗤，宁如在家好。"]},{"t":"哀哉行 其一","f":"古风","c":["燕京老人鬓若丝，生长富贵无人欺。","少年慷慨结豪侠，弯弓气压幽并儿。","自嗟迩来筋力衰，动须僮仆相扶持。","忽惊杂虏到门巷，黄金如山难解危。","馀息独存剑锋下，子孙散尽生何为。","厩马北驱嘶故主，劲风吹断枯桑枝。","哀哉行，天何知。"]},{"t":"哀哉行 其四","f":"古风","c":["燕京女儿何盈盈，隔花娇语如春莺。","邻姬盛装失光彩，颜色信是倾人城。","许嫁城中羽林将，千金奁具犹言轻。","门前一朝胡马鸣，晓眠未足心魂惊。","颠倒衣裳科鬒发，驱之北去悲吞声。","独恨跣足走荆棘，不与爷娘同死生。","哀哉行，难为情。"]},{"t":"送许参军还都下兼寄严冢宰敏卿","f":"古风","c":["天上使星临雁塞，满城风雪荡旌旆。","犒赏连营倍战心，健儿已遁龙荒外。","君不见岢岚州，云连雉堞生边愁。","寒天惨淡日易落，偏令鸟雀群啁啾。","郁潾结冰高于岸，逝水暗咽翻西流。","防秋复防秋，不虞岁暮烽火稠，黠虏交攻孤垒破，马牛去尽犬独留。","犬蹲屋角吠山月，鬼打钟声登戍楼。","三关父老且挥涕，当代应多卫霍俦。","今人白首待勋业，古人壮志图封侯。","都护时能练士卒，还念严冬穷到骨。","穷愁有骨可聊生，犹胜无功此身没。","胡骑又从西北来，停鞭几为苍生哀。"]},{"t":"西园春暮","f":"七言律诗","c":["西北风来何太剧，落花满园春可惜。","黄鹂叫春蝴蝶愁，四野无人日将夕。","惟有一枝留晚春，当砌徘徊不忍摘。","且将樽酒对残花，春去悲歌复何益。"]},{"t":"客居篇呈孔丈","f":"七言古诗","c":["客居寥落天积阴，其奈二毛愁复侵。","东篱有花白衣至，菊花恨不栽成林。","糟床雨声夜彻耳，醅瓮春色时关心。","昨梦长江变绿酒，茫茫不知几许深。","倒吞明月荡豪兴，下有蛟龙那敢吟。","屈原李白莫相笑，肯与尔辈俱浮沈。","醒者醉者怀不同，我狂独在醒醉中。","百年形骸匪金石，讵可一日无春风。","燕台梁园旧游处，好客迩来惟孔融。","太行山头共俯仰，人间谁识真英雄。","几醉良宵感秋别，大火自西人自东。"]},{"t":"武皇巡幸歌 其一","f":"五言律诗","c":["神武驱兵日，南征气赫然。","射蛟江水上，立马石城边。","羽檄飞三楚，霓旌拂九天。","功成凯歌夜，月色送楼船。"]},{"t":"武皇巡幸歌 其二","f":"五言律诗","c":["齐鲁巡游地，苍生见紫微。","晴云随鹢舫，春水照龙衣。","柳畔千官拥，沙边七校围。","观鱼移白日，鼓吹月中归。"]},{"t":"武皇巡幸歌 其三","f":"五言律诗","c":["玉辇冲寒色，萧萧八骏鸣。","兔河冰上过，狐岭雪中行。","抚剑群胡遁，弯弓百兽惊。","当年赤帝子，空到白登城。"]},{"t":"武皇巡幸歌 其四","f":"五言律诗","c":["年少羽林郎，严冬较猎忙。","旌旗开御道，剑戟拥长杨。","飞去五花马，射来双白狼。","中官传赐酒，甲胄拜君王。"]},{"t":"有感","f":"五言律诗","c":["薄伐元中策，论兵自古难。","汉唐频拓地，将帅几登坛。","绝漠兼天尽，交河荡日寒。","不知大宛马，曾复到长安。"]},{"t":"春夜即事","f":"五言律诗","c":["春草非吾土，春宵还自悲。","庭虚风稍静，帘捲月何迟。","久病儿知药，长吟妻解诗。","他年学耕稼，肯负鹿门期。"]},{"t":"春宫词","f":"五言律诗","c":["盈盈上阳女，愁思起中宵。","月白璚窗静，花深玉辇遥。","晓霞憎国色，春柳妒宫腰。","不见长门赋，伤心有阿娇。"]},{"t":"春园","f":"五言律诗","c":["水村人寂寂，迟日敞柴关。","菜甲春初细，园丁雨后閒。","沙边来白鸟，柳外出青山。","此地多幽意，行歌薄暮还。"]},{"t":"送杜太仆谪荆州","f":"五言律诗","c":["谪宦三千里，谁怜贾傅才。","汉江秋月上，楚岫夜猿哀。","心事登楼赋，年光落帽台。","知君最愁绝，湘雁逐春来。"]},{"t":"榆河晓发","f":"五言律诗","c":["朝晖开众山，遥见居庸关。","云出三边外，风生万马间。","征尘何日静，古戍几人间。","忽忆弃繻者，空惭旅鬓斑。"]},{"t":"夏夜独坐披襟当风颇有秋意赋此寄怀","f":"五言律诗","c":["散发南楼夜，翛然披素襟。","蛩声依草际，萤火落墙阴。","老破当年梦，秋生久客心。","遥思苔石上，坐听美人琴。"]},{"t":"杨以时复游都下","f":"五言律诗","c":["乱后相逢日，论交半已非。","谋生双鬓改，感旧十年归。","帆落烟中浦，琴鸣竹里扉。","重来傍燕市，霜露满秋衣。"]},{"t":"送樊侍御之金陵","f":"五言律诗","c":["地入维扬路，天分牛斗墟。","秋帆二水外，春草六朝余。","冰雪生官舍，风尘走谏书。","从来经国者，宁不念樵渔。"]},{"t":"除夕示儿元炳兼忆元煇诸儿","f":"五言律诗","c":["对汝还成叹，寒更坐转深。","异乡垂老计，春草隔年心。","蜡炬明残夜，天风破积阴。","遥怜几稚子，酒罢一长吟。"]},{"t":"晓起","f":"五言律诗","c":["晓起正科头，时闻花外鸠。","出门疏雨歇，倚杖断云流。","绿草偏依水，青山半入楼。","况逢春酒熟，不负嗣宗游。"]},{"t":"晚过西湖","f":"五言律诗","c":["怅望西山路，曾经胡马过。","重来把杨柳，独立向烟波。","日影峰头尽，春寒湖上多。","渔樵一相见，犹为话兵戈。"]},{"t":"除夕徐子与宅得年字","f":"五言律诗","c":["客里岁时迁，还来醉此筵。","吴歌怜《子夜》，潘鬓感丁年。","列炬明深院，繁星动远天。","宫梅殊有意，更向早春妍。"]},{"t":"寒食旅怀","f":"五言律诗","c":["蓟北惊寒食，淹留几自嗟。","春风来燕子，落日在桃花。","丘陇行边泪，江湖梦里家。","不知疏懒客，何物是生涯。"]},{"t":"晚眺","f":"五言律诗","c":["寒日下西陵，漳河晚渡冰。","孤城归猎骑，双树隐禅灯。","野眺心何远，岩栖老未能。","翻怜戎马日，愁思坐相仍。"]},{"t":"伏枕","f":"五言律诗","c":["伏枕无穷事，虚堂秋夜深。","松低半窗月，山静数家砧。","老鹤同幽意，寒螀伴苦吟。","百年儿女计，谁识尚平心。"]},{"t":"重过张氏园林二首 其二","f":"五言律诗","c":["随处携鸠杖，狂时倒鹖冠。","晚山当座出，风竹满楼寒。","独酌世情远，长歌春事残。","不知桃李发，白首几回看。"]},{"t":"居庸关二首 其二","f":"五言律诗","c":["控海幽燕地，弯弓豪侠儿。","秋山牧马处，朔塞用兵时。","岭断云飞迥，关长鸟度迟。","当朝有魏尚，复此驻旌旗。"]},{"t":"杨白花","f":"五言律诗","c":["年少宫中树，偏怜杨白花。","长风吹日暮，春雪落天涯。","荡子空相忆，芳年谩自嗟。","月明愁不见，啼杀禁城鸦。"]},{"t":"架边","f":"五言律诗","c":["闲庭秋一色，满架豆花垂。","薄俗存吾计，衰年习土宜。","烟中晚雀定，露下候虫知。","何限幽人意，临风独立时。"]},{"t":"东园秋夜柬知己","f":"五言律诗","c":["悲歌残烛下，秋思转纷纷。","落叶多惊雨，明河半隔云。","萤光时复见，虫响夜多闻。","谁是论心侣，清樽可共君。"]},{"t":"岁暮卢次楩过邺有感","f":"五言律诗","c":["燕霜终古愤，梁狱昔年书。","世事疏狂里，交情患难余。","相看年欲老，多感岁将除。","醉拟应刘赋，春风起敝庐。"]},{"t":"南伐","f":"五言律诗","c":["南伐驱千骑，遥闻几战场。","青年多侠气，白骨半他乡。","塞雁悲秋老，闺人哭夜长。","招魂渺何处，天外月茫茫。"]},{"t":"秋庭","f":"五言律诗","c":["东园闲白日，庭户绝经过。","落叶听无尽，秋风来更多。","忽闻诛寇盗，莫厌事兵戈。","卖剑今谁是，愁云渺大河。"]},{"t":"暮秋夜柬宗上人","f":"五言律诗","c":["山城摇落夜，感慨几人同。","旧馆残孤烛，秋原老百虫。","才疏漂泊际，心定寂寥中。","亦有逃禅意，明朝过远公。"]},{"t":"次张祜金山寺之韵","f":"五言律诗","c":["孤绝寒逾迥，苍茫夜不分。","僧归依岛月，龙定缩江云。","天汉窗前合，风涛枕上闻。","好沽瓜步酒，诗思在微醺。"]},{"t":"北望二首 其一","f":"五言律诗","c":["戎马何时定，愁云直北看。","朝廷殊见远，将相各知难。","风乱边声急，霜连兵气寒。","中天问明月，曾照汉家坛。"]},{"t":"北望二首 其二","f":"五言律诗","c":["十月嘶胡马，南来饮潞河。","论功自有定，报国岂无多。","雾拥宫门隔，星飞羽檄过。","中兴见神武，不许郅支和。"]},{"t":"季冬夜西池君见过","f":"五言律诗","c":["昔枉信陵车，侯生一敝庐。","自甘昭代隐，拟著老农书。","山冥登楼外，庭寒扫雪余。","相知在古道，宁复曳长裾。"]},{"t":"郊送张肖甫","f":"五言律诗","c":["平子愁能赋，予愁更几何。","泪中心事尽，客里世情多。","青眼交仍好，黄花节又过。","离亭独怅望，车马渡汾河。"]},{"t":"春闺","f":"五言律诗","c":["深院飞花急，临风秪自哀。","又看春色老，坐使玉颜摧。","落月窥琴室，流尘上镜台。","窗前有梅树，岁暮待君开。"]},{"t":"除夕有怀","f":"五言律诗","c":["除夕归期过，孤帏嗟未休。","翻疑虏消息，转使客淹留。","积雪寒连塞，明星晓近楼。","遥知不寐处，并得两年愁。"]},{"t":"寄东平刘成卿","f":"五言律诗","c":["有才官遽罢，知尔国忧深。","涕泪看春草，艰难返故林。","余生恩到骨，独卧梦惊心。","龙剑多灵异，还疑风雨吟。"]},{"t":"雁门","f":"五言律诗","c":["昔年雁门路，霜气逼征鞍。","野望天何惨，徒行老更难。","人烟隔水静，鬼火照沙寒。","战伐空悲感，风凄戍角残。"]},{"t":"读江宁王悼内诗","f":"五言律诗","c":["凄凉不易写，楚调复清新。","字字心间泪，时时梦里人。","风悲西苑树，月惨后宫春。","令与陈王并，无惭赋《洛神》。"]},{"t":"寄怀许伯诚","f":"五言律诗","c":["发轫辽阳雪，还家韦杜春。","客疏门自掩，官罢酒相亲。","白首歌今代，青山梦古人。","行藏不可问，独鹤下西秦。"]},{"t":"夏夜集冯员外汝言举子汝强宅赋得花字","f":"五言律诗","c":["淹留数高会，伯仲复名家。","白发几年客，红蕖三度花。","风从西苑至，月傍帝城斜。","徙倚发孤咏，隔林啼曙鸦。"]},{"t":"秋雨宿权店驿有感","f":"五言律诗","c":["驿灯分暝色，野馆滞秋阴。","已倦衰年事，偏驰故国心。","夜凉槐雨滴，月暗草虫吟。","归梦不知路，千山云更深。"]},{"t":"忆都门酒家王四","f":"五言律诗","c":["尚忆高楼饮，青帘出绿杨。","频赊宁沮兴，浩唱不嗔狂。","谢客惟深醉，胡姬自盛妆。","几回青梦里，听雨滴糟床。"]},{"t":"九日寄怀田梦鹤兵宪","f":"五言律诗","c":["别后几重阳，停云渺帝乡。","登高同节序，垂老各行藏。","夕鸟安庭树，秋光照野塘。","何时问幽寂，岁杪正冰霜。"]},{"t":"漳河有感","f":"五言律诗","c":["行经百度水，秪是一漳河。","不畏奔腾急，其如转折多。","出山通远脉，兼雨作洪波。","偏入曹刘赋，东流邺下过。"]},{"t":"九日集徐郎中汝思宅得杯字","f":"五言律诗","c":["连床留昨夜，九日复筵开。","白发愁中赋，黄花乱后杯。","霜兼宫树变，雁自塞门来。","赖是同心者，深知庾信哀。"]},{"t":"野兴","f":"五言律诗","c":["白日霜凝地，飞飞雁度河。","孤峰依汉迥，老树得秋多。","月晓山精伏，时清野父歌。","短筇随我意，一径入烟萝。"]},{"t":"大梁冬夜","f":"五言律诗","c":["坐啸南楼夜，孤灯客思长。","人吹五更笛，月照万家霜。","归计身多病，生涯鬓易苍。","征鸿向何许，春意遍湖湘。"]},{"t":"春野","f":"五言律诗","c":["去郭苍茫色，鸦飞欲暮天。","青天一筇外，白发万花前。","春事浑相恼，人情好自怜。","踏歌时遣意，平楚漫风烟。"]},{"t":"冬夜黄给事用章宅同张肖甫赋得中字","f":"五言律诗","c":["初逢青琐彦，下榻一宵同。","月落棋声里，春回烛影中。","放歌还楚调，扶醉有巴童。","上苑遥相问，梅花定几丛。"]},{"t":"春日柬李之茂","f":"五言律诗","c":["君逢初度日，闭户正思亲。","绿酒谁开瓮，班衣自积尘。","断云愁里色，独树泪边春。","今夕应无寐，啼乌莫傍人。"]},{"t":"寄赵宪副万举","f":"五言律诗","c":["旧卧淮阳阁，今屯邺下兵。","经时求壮士，忧国听边声。","马踏长楸道，旗翻细柳营。","黄须少年子，仗剑迟功成。"]},{"t":"秋夜乌给事宅言别","f":"五言律诗","c":["故人同此夜，离思且衔杯。","古树当庭合，惊墙到席回。","烛花留我醉，谏草识君才。","异日关河隔，秋鸿几北来。"]},{"t":"边警","f":"七言律诗","c":["太白秋高烽火惊，羽书飞下晋阳城。","沙场风急来胡马，亭障云深出汉旌。","战守何人能仗策，朝廷今日始言兵。","悬知驾驭还多术，早晚亲临细柳营。"]},{"t":"送王侍御按河南","f":"七言律诗","c":["塞上初归复此行，燕南极目送飞旌。","天连嵩岳寒云尽，马度黄河春草生。","簪笔常思未央殿，封章时发大梁城。","知君最爱应刘赋，更向西园一寄声。"]},{"t":"早发坡泉薄暮至太行山下","f":"七言律诗","c":["地分三晋此山川，形胜迢遥在马前。","乱石斜通青草路，太行横断夕阳天。","漫垂云气孤村雨，时聒乡心几树蝉。","不及阮宣随处醉，兴来即解杖头钱。"]},{"t":"春柳","f":"七言律诗","c":["黄鹂时复唤春游，陌上杨花漫不休。","几向离筵摇落日，莫教长笛动清秋。","轻烟直接都门外，细雨低临灞水头。","谩系王孙金络马，萋萋绿草有人愁。"]},{"t":"春宫词","f":"七言律诗","c":["长信宫中芳草生，晚风独立正含情。","时颦柳叶听龙驾，谁隔桃花吸凤笙。","金屋半开春寂寞，珠帘不动月分明。","烧残蜡炬虚长夜，遮莫同心结未成。"]},{"t":"寄酬淮阴夏子吴门邹子","f":"七言律诗","c":["江鱼海雁空相报，楚调吴歌久不闻。","无那旅怀常抱病，更堪风物正离群。","马融笛里三秋月，王粲楼前万里云。","犹忆当时共樽洒，一灯寒雨坐宵分。"]},{"t":"病怀","f":"七言律诗","c":["鬓发萧萧昼不冠，他乡风物若为看。","花庭晒药日将午，茅屋烹茶春尚寒。","久别亲朋谁问病，深怜儿女自加餐。","是非高枕浮云过，遥忆西河旧钓竿。"]},{"t":"秋日怀弟","f":"七言律诗","c":["生涯怜汝自樵苏，时序惊心尚道途。","别后几年儿女大，望中千里弟兄孤。","秋天落木愁多少，夜雨残灯梦有无。","遥想故园挥涕泪，况闻寒雁下江湖。"]},{"t":"冬夜尹明府遇夫宴集因忆何少卿治象梁宪副公济","f":"七言律诗","c":["天寒地主见情亲，雉堞参云雁塞邻。","十载别怀今夜酒，数茎短发旧游人。","雪庭照席输明月，冻树垂花像早春。","遥忆二君寻白社，方知岁暮有松筠。"]},{"t":"久客志感","f":"七言律诗","c":["寄迹天涯久未归，孤城霜日惨无辉。","苦吟易老计何拙，浊酒驱愁功亦微。","兵气横关催走檄，仙云绕阙护垂衣。","自从河套停边议，将相于今远是非。"]},{"t":"暮秋郊行偶述","f":"七言律诗","c":["太行迢递起苍烟，凄断鸣鸿倚杖前。","南阻黄巾愁落日，东游皂帽感当年。","山城秋老行边树，河甸寒生战后天。","独有王孙多侠气，千金骏马猎荒田。"]},{"t":"送李给事元树奉使云中诸镇","f":"七言律诗","c":["琐闱朝下促飞旌，岁暮看君塞上行。","戍角动人多苦调，戎衣走马半新兵。","关开涿鹿云连树，路出蜚狐雪满城。","计日楚才封事上，君王深见九边情。"]},{"t":"送客游洞庭湖","f":"七言律诗","c":["相逢楚客问巴州，此去扬帆湖上游。","天汉长连洞庭水，云霞半入岳阳楼。","低空白雁投寒渚，隔浦丹枫照暮秋。","莫向湘君听鼓瑟，黄陵月冷不胜愁。"]},{"t":"夜话李孺长书屋因忆乃翁左纳言","f":"七言律诗","c":["忘年尔我重交情，论事相同见老成。","月到广除寒有色，鸦归疏柳夜无声。","三农更苦江南税，百战方休海上兵。","岁暮银台应感叹，几人封事为苍生？"]},{"t":"闻汉中兵宪王斯进讨贼有功赋此寄赠","f":"七言律诗","c":["星子山头杀气生，可怜蜀盗废春耕。","皇天何意干戈扰，人日多寒军旅行。","檄出汉中鸦作阵，角吹岭上马嘶声。","谁知缓急兵家术，八月铙歌返旆旌。"]},{"t":"寄怀西谷主人","f":"七言律诗","c":["上党归来独忆君，野亭幽事每宵分。","荷池烛影游鱼荡，花院棋声宿鸟闻。","漳水远通千里脉，洛城高压万山云。","于今南北殊脩阻，回首长吟又落曛。"]},{"t":"除夕吴子充周一之文德承李时明方信之王希舜集旅寓有感","f":"七言律诗","c":["一年忧喜今宵过，两鬓风霜明日新。","书剑自怜多病客，江湖同是放歌人。","宫中烛映西山雪，笛里梅传上国春。","他日听莺怀旧侣，不知谁共醉芳晨。"]},{"t":"初春夜同沈子文梁公实薛思素进士宗子相比部赋得声字","f":"七言律诗","c":["雪尽长风吹禁城，梅花零落此时情。","关河月暗迷鸿影，宫殿春寒涩漏声。","乱后骚人同百感，年来壮士苦长征。","樽前莫话边庭事，弹剑悲歌气未平。"]},{"t":"送杨侍御按真定","f":"七言律诗","c":["君从淮海动威声，燕赵乘春复此行。","世事忧深持白简，天骄乱后惜苍生。","马经滹水鱼龙避，霜下恒山道路清。","遥夜乌啼何限思，坐看孤月度严城。"]},{"t":"春日即事","f":"七言律诗","c":["和戎共拟静边声，抗疏谁当悉虏情。","燕地去秋曾几战，汉家今日更多兵。","春城雨后寒逾重，曙角风前怨未平。","直北烟尘时极目，乌鸢飞入亚夫营。"]},{"t":"塞下三首 其二","f":"五言古诗","c":["青山行不断，独马去迟迟。","宿雾开军垒，寒城见酒旗。","沙连天尽处，霜重日高时。","惨淡兵戈气，萧条榆柳枝。","乾坤疲战伐，将相系安危。","寄语筹边者，功名当自知。"]},{"t":"塞下三首 其三","f":"五言古诗","c":["路出古云州，风沙吹不休。","乌鸢下空碛，驼马渡寒流。","地旷边声动，天高朔气浮。","霜连穷海夕，月照大荒秋。","击鼓番王醉，吹笳汉女愁。","龙城若复取，侠士几封侯。"]},{"t":"庚戌八月二十二日恭闻奉天殿视朝","f":"五言古诗","c":["上苑凉飔起，西山瑞霭浓。","玉珂天汉路，金阙午时钟。","剑佩炉香近，旌旗日影重。","宫墙落杨柳，水槛出芙蓉。","万舞趋丹凤，千官识衮龙。","遥传北伐诏，光耀紫泥封。"]},{"t":"送汪郎中伯阳出守北地","f":"五言古诗","c":["五马冲寒色，冰霜满去程。","君王忧北地，父老望前旌。","典郡才方振，防年计不轻。","河山分陕服，形势辅咸京。","树隐青蛇庙，天空白豹城。","人家尽周俗，羌笛半秦声。","夜月登楼啸，春风露冕行。","试看《循吏传》，终古定垂名。"]},{"t":"送赵太守还任淮安","f":"五言古诗","c":["相思隔楚树，相聚复燕州。","五马翻成别，孤樽不可留。","江河自襟带，南北此咽喉。","昭代今多事，苍生日隐忧。","几时堪卧治，何处薄征求。","海上寒涛息，天边春气流。","花明射阳水，月满镇淮楼。","地胜多名士，何人托乘游。"]},{"t":"初春夜集王元美宅饯别吴峻伯徐汝思袁履善三比部出使得杯字","f":"五言古诗","c":["共饯江南客，芳筵候月来。","漏催诗草就，春报烛花开。","把袂终千里，论心更一杯。","风人今夜聚，星使几时回。","官舍遥闻笛，宫庭暗落梅。","相看倍惆怅，残雪照燕台。"]},{"t":"寄孔方伯汝锡","f":"五言古诗","c":["每忆汾阳约，何为代北游。","神交太行迥，调合建安流。","高步云随杖，穷边雪照楼。","虏骄轻出入，吾老重淹留。","厚禄惟思报，严兵只御秋。","材官几人在，国士百年忧。","上古元无战，中丞自有谋。","冰清闲鹤渚，潭冷闭龙湫。","旧社独来去，春醪那唱酬。","相逢话时事，感慨望神州。"]},{"t":"送高伯宗梁公实二比部祭陵庙","f":"五言古诗","c":["祀典千年重，严趋二妙同。","马嘶川日堕，路转石林通。","旌旆晴光外，山陵王气中。","云深罗俎豆，霜下肃臣工。","明月帝灵在，高秋天宇空。","瞻依增百感，松槚正悲风。"]},{"t":"赠董职方德甫擢光禄卿","f":"五言古诗","c":["三秋心力尽，经略见才雄。","董策今谁在，班铭志已同。","才收卫律叛，更赏霍家功。","神武惟龙准，凭陵自犬戎。","兵张群议后，官转百忧中。","侯火惊燕甸，宵衣想汉宫。","将星寒动塞，卿月夜临空。","尚忆长征子，持戈向北风。"]},{"t":"寄塞上王侍御子梁","f":"五言古诗","c":["君王重简命，尔志在澄清。","节钺分西顾，风云护北征。","羽旗荒外合，骢马雪中行。","直渡桑乾水，还临骠骑营。","九关多猛士，百战有长城。","夜半仍传檄，天寒未解兵。","黑山横宝剑，青海动金钲。","独仗防边策，兼收抗疏名。","虚心当国事，高议见儒生。","壮岁思铭鼎，空言陋请缨。","乘秋摧虏气，计日答皇情。","应遣龙庭使，驰书到玉京。"]},{"t":"江南曲","f":"五言绝句","c":["夹岸多垂杨，妾家临野塘。","手拈青杏子，不忍打鸳鸯。"]},{"t":"江南曲二首 其二","f":"五言绝句","c":["夹岸多杨柳，妾家近塘口。","中有断肠花，郎君不回首。"]},{"t":"怀邹子序","f":"五言绝句","c":["渺渺太湖水，湖中多鲤鱼。","故人时把钓，应有北来书。"]},{"t":"都下别张志虞","f":"五言绝句","c":["十年今一见，话旧却成悲。","共醉新丰酒，天涯又别离。"]},{"t":"行路难","f":"五言绝句","c":["荀卿将入楚，范叔未归秦。","花鸟非乡国，悠悠行路人。"]},{"t":"游天坛山 其三","f":"五言绝句","c":["偶逢双玉童，相引蹑云去。","犬吠洞门开，三花最深处。"]},{"t":"初春夜同漫山方伯琼泉将军酌樗庵书斋","f":"五言绝句","c":["客子灯前酒，梅花雪后天。","不须横玉笛，春意满山川。"]},{"t":"春柳","f":"五言绝句","c":["嫩色含轻雨，柔丝弄早春。","昏鸦栖欲定，肠断未归人。"]},{"t":"春兴","f":"五言绝句","c":["夜月悬银烛，春江湛绿醅。","美人歌古调，烂醉百花台。"]},{"t":"塞下曲二首 其一","f":"五言绝句","c":["飘蓬燕赵间，行李风霜下。","芦管送边声，空林一驻马。"]},{"t":"塞下曲二首 其二","f":"五言绝句","c":["塞上黄须儿，饮马黑山涧。","弯弧向朔云，莫射南飞雁。"]},{"t":"潞阳晓访冯员外汝言 其一","f":"五言绝句","c":["海日上孤帆，山云交杂树。","美人方晓眠，更在林深处。"]},{"t":"潞阳晓访冯员外汝言 其二","f":"五言绝句","c":["野阔早霜明，林空凉吹动。","一犬吠人来，松窗破秋梦。"]},{"t":"咏蝉","f":"五言绝句","c":["弱翅凌晨动，繁声向夕流。","不知风露里，还得几何秋。"]},{"t":"雪后同王希元登代州城楼 其二","f":"五言绝句","c":["睥睨胡天近，登临边树迷。","汉兵不到处，寒鸟向谁啼。"]},{"t":"雪后登代州城楼时虏犯岢岚三首 其二","f":"五言绝句","c":["霁色分诸垒，寒空下一雕。","幕南白草尽，胡马亦何骄。"]},{"t":"雪后登代州城楼时虏犯岢岚三首 其三","f":"五言绝句","c":["都门飞羽书，冰雪走胡骑。","只见塞云愁，那知塞垣事。"]},{"t":"春雪登楼有感","f":"五言绝句","c":["天垂楼外云，雪变城中树。","何处不春寒，鸦啼又飞去。"]},{"t":"东园秋怀二首 其一","f":"五言绝句","c":["花竹可消愁，愁来独上楼。","自古天涯客，谁禁老去秋。"]},{"t":"东园秋怀 其二","f":"五言绝句","c":["天寒闻落木，叶叶是乡愁。","敲窗作风雨，不减去年秋。"]},{"t":"登辉县城见卫水思归","f":"七言绝句","c":["城外河流白练长，城中万户共秋光。","秋来偏作还家梦，河水东流到故乡。"]},{"t":"塞上曲 其二","f":"七言绝句","c":["旌旗荡野塞云开，金鼓连天朔雁回。","落日半山追黠虏，弯弓直过李陵台。"]},{"t":"塞上曲 其三","f":"七言绝句","c":["飞将龙沙逐虏还，夜驱驼马入燕关。","城头残月谁横笛，吹落梅花雪满山。"]},{"t":"塞上曲 其四","f":"七言绝句","c":["暮云黯澹压边楼，雪满黄河冻不流。","野烧连山胡马绝，何人月下唱《凉州》。"]},{"t":"冬夜闻笛","f":"七言绝句","c":["雪后寒云散御堤，笛声何处重凄凄。","北风吹折边城柳，人倚层楼月正西。"]},{"t":"送周秀才归钱塘","f":"七言绝句","c":["燕京陌上送周郎，归到西湖春草长。","清夜开樽多旧侣，满船歌管月如霜。"]},{"t":"留别张德隆","f":"七言绝句","c":["来时积雨没平原，去路鸣虫秋正繁。","桂树花开如有兴，紫骝嘶过孝王园。"]},{"t":"雨后柬王体仁","f":"七言绝句","c":["雪夜还能棹剡溪，雨余何事怯冲泥。","自怜穷巷多秋草，不见青骢向北嘶。"]},{"t":"道院秋夕","f":"七言绝句","c":["秋河一带月光团，露坐空除夜欲阑。","却讶西楼降仙子，玉笙吹彻万家寒。"]},{"t":"别调曲 其一","f":"七言绝句","c":["家住邺城门向西，青楼上与邺城齐。","郎行好记门前柳，春梦南来路不迷。"]},{"t":"别调曲代赠所知三首 其二","f":"七言绝句","c":["离筵易醉夜将分，赵舞灯前犹向君。","从此腰肢瘦无力，床头闲杀藕丝裙。"]},{"t":"别调曲 其二","f":"七言绝句","c":["木落天寒郎欲行，樽前离怨一鸣筝。","燕姬纤手调新曲，不是西楼今夜声。"]},{"t":"远别曲","f":"七言绝句","c":["阿郎几载客三秦，好忆侬家汉水滨。","门外两株乌桕树，叮咛说向寄书人。"]},{"t":"捣衣曲","f":"七言绝句","c":["秦关昨寄一书归，百战郎从刘武威。","见说平安收涕泪，梧桐树下捣征衣。"]},{"t":"绣毬花","f":"七言绝句","c":["高枝带雨压雕栏，一蒂千花白玉团。","怪杀芳心春历乱，捲帘谁向月中看。"]},{"t":"采莲曲","f":"七言绝句","c":["湖上西风吹绮罗，靓妆越女照清波。","折将莲叶佯遮面，棹过前滩笑语多。"]},{"t":"秋怀","f":"七言绝句","c":["秋来客思渺烟波，湖上看山秋更多。","祇恐佳人怨秋色，晚风吹断采菱歌。"]},{"t":"春词 其二","f":"七言绝句","c":["城乌何意夜深啼，红杏梢头片月低。","香冷熏笼人不寐，春风吹过玉栏西。"]},{"t":"春闺","f":"七言绝句","c":["罗衣初试薄寒生，豆蔻花开感别情。","零落铅华君不见，画楼春雨燕双鸣。"]},{"t":"重九雨中怀弟","f":"七言绝句","c":["天空朔雁不成行，秋色年年似故乡。","门掩菊花人独卧，冷风疏雨过重阳。"]},{"t":"塞上曲寄少司马苏允吉 其二","f":"七言绝句","c":["白登城上早霜凄，黑水河边暮雁低。","还忆去秋明月下，胡笳吹过七陵西。"]},{"t":"即席赠薛之翰","f":"七言绝句","c":["园花樽酒日相期，共尔留连欲暮时。","醉倚山亭歌楚调，秋萤飞过石榴枝。"]},{"t":"愚公园春酌二首 其一","f":"七言绝句","c":["共醉春风且放情，白云无定若浮名。","好花开落寻常事，遮莫黄鹂不住声。"]},{"t":"愚公园春酌二首 其二","f":"七言绝句","c":["绛桃一簇映斜晖，白首寻芳几醉归。","更有多情双蛱蝶，春来还傍菜花飞。"]},{"t":"春怨","f":"七言绝句","c":["紫绡挥断泪阑干，窗下秦筝独自弹。","三月梨花风又雨，小楼燕子怯春寒。"]},{"t":"春宫词","f":"七言绝句","c":["御河桥畔是侬家，一入深宫虚岁华。","别院黄昏吹凤管，月钩斜照刺桐花。"]},{"t":"宫词 其一","f":"七言绝句","c":["自入长门空绣帷，玉颜非复镜中时。","梨花夜雨灯相对，燕子春寒君不知。"]},{"t":"宫词 其二","f":"七言绝句","c":["晓起慵妆眉黛残，玉阶芳草捲帘看。","花间漫扑双蝴蝶，宿露偏沾翠袖寒。"]},{"t":"明月山下逢武宾相克仁话旧","f":"七言绝句","c":["车马西来自泽州，思君不见十经秋。","相逢把袂成悲感，明月当前两白头。"]},{"t":"暮鸦有感","f":"七言绝句","c":["来时池草吐春芽，秋水惊心落藕花。","空记三秋故乡梦，夕阳衰柳看归鸦。"]},{"t":"金笳曲 其一","f":"七言绝句","c":["砂碛茫茫黑水流，胡儿六月换羊裘。","骆驼背上吹芦管，风散龙荒作冷秋。"]},{"t":"九日过王叔野无菊","f":"七言绝句","c":["陶潜懒慢闭柴关，九日餐英自解颜。","不种黄花君更懒，满城秋色几人闲。"]},{"t":"访葛徵君","f":"七言绝句","c":["西城閒访葛洪家，篱落秋馀白豆花。","高枕自知无俗梦，数椽茅屋在烟霞。"]},{"t":"寄武当山张隐君 其一","f":"七言绝句","c":["辞官身寄楚天涯，石屋烧丹别是家。","七十二峰春雪里，杖藜随意看梅花。"]},{"t":"晚登沁州城有感 其一","f":"七言绝句","c":["苍茫野色几沙滩，漳水东流倚堞看。","烟火满城天向夕，一雕飞过不知寒。"]},{"t":"塞下曲 其二","f":"七言绝句","c":["青海城边秋草稀，黄沙碛里夜云飞。","将军不寐听刁斗，月上辕门探马归。"]},{"t":"漠北词 其二","f":"七言绝句","c":["委羽山横塞北天，学飞雏雁夕阳边。","匈奴岁岁无争战，白马黄驼傍草眠。"]},{"t":"漠北词三首 其二","f":"七言绝句","c":["石头敲火炙黄羊，胡女低歌劝酪浆。","醉杀群胡不知夜，遥见岭下月如霜。"]},{"t":"漠北词 其四","f":"七言绝句","c":["晓开毡帐拥秋云，虏将挥鞭部落分。","牧马阴山莫南向，雁门今有李将军。"]},{"t":"少林感旧篇因示镇性禅子兼忆宗书上人","f":"五言古诗","c":["苍苍列峰峦，郁郁挺松柏。","少林当形胜，登攀几词客。","中有惠远流，旧识非凡格。","谓我犹疏旷，一讶头全白。","澹交偶尔忘，相对复畴昔。","人生若沙鸟，飞去不言迹。","因之忆汝祖，谈禅坐深夕。","山精出阴崖，天花没乱石。","两神有时会，冥漠自无隔。","重来失暄景，岁寒太萧索。","雨雪命巾车，相望洛城陌。"]},{"t":"哀老营堡","f":"五言古诗","c":["严冬塞马来，不意破高垒。","纵有飞将军，仓皇那可恃。","杀气与人烟，相侵惨如此。","树寒啼老鸱，月黑乱新鬼。","亲戚一闻变，竞走霜风里。","宁言积血腥，各认骸骨是。","群号振山颠，万泪迸湍水。","俯身不回顾，忽复黄尘起。","潜伏林谷中，狡黠殊无比。","部落入空壁，屠戮甚羊豕。","劫掳又北驱，哽咽苦千里。","男女不两存，去留见生死。","生者讵得归，死者长已矣。","嗟哉仗钺人，奋烈向朔鄙。"]},{"t":"得王希元书有感","f":"五言古诗","c":["客子寄书来，关山正雨雪。","恍如对面时，翻然几披阅。","冻笔挥亦难，言之意弥切。","驿树共萧条，而能念薄劣。","我今知尔心，可置管鲍列。","人生多交游，但恐久离别。","盛年拟会期，白首独愁绝。","有怀空自歌，月明谁击节。"]},{"t":"百花叹","f":"五言古诗","c":["胜游郭外园，簇簇多芳树。","花似去年花，春来又春暮。","先后总成尘，宁复论新故。","荣枯皆有时，非关风雨妒。","黄鸟亦可悲，浮生谁自悟。","抚景聊醉歌，百年一流寓。"]},{"t":"除夕过东林寺同晓公谈禅","f":"五言古诗","c":["林磬何悠悠，庭雪复灿灿。","冲寒过支公，相围地炉炭。","一谈得真蕴，贝叶徒满案。","学禅若栽松，老有万枝干。","谁能顿悟间，森然俱斩断。","见心是道侣，寂寂坐夜半。","慧灯无际光，照破几梦幻。","生死譬朝夕，岁尽岂嗟叹。","处世各有缘，焉得不聚散。","明春杖锡行，孤云渺天畔。"]},{"t":"忆五华观侯道士","f":"五言古诗","c":["岧峣五华山，玄都据其下。","秋草没行径，弥年绝车马。","我忆昔访真，抚景援毫写。","鹤雏步阶石，松子落屋瓦。","繁阴爱青萝，席地不知夏。","道侣话丹经，因之命玉斝。","宁学鍊九还，黄金亦土苴。","瑶草元无根，俯拾秀盈把。","留侯早辟谷，信哉汉恩寡。","藏用复何人，大隐任朝野。","嗟彼尘垢中，谁是无营者。"]},{"t":"忆金山寺兼示阇黎诸上人","f":"古风","c":["兹山自开辟，突作中流柱。","静居元气间，苍茫混太宇。","奇秀天所钟，迥立照万古。","根深接地轴，永依造物主。","石穴藏蛟龙，山灵势长俯。","绮霞几明灭，白涛任吞吐。","逦?乱渔蓑，霏微正烟雨。","清若顾凯画，阴晴皆可睹。","祇园绝尘氛，法界自风土。","天晓浮图出，梵声杂钟鼓。","老衲饲饥鼋，况复鸟雀聚。","慈悲西来心，吾亦本初祖。","顿悟能为诗，三昧超徐庾。","探胜尽南北，衰病何闭户。","壮心赋两都，乘流荡双橹。","佳人有所思，采芳新林浦。","还期蒋山兴，宁虚梦天姥。"]},{"t":"有感二首 其一","f":"五言古诗","c":["白云起西山，悠悠上无极。","鸿鹄从之飞，终朝殊不息。","浮云安可长，羽毛自珍惜。","倦来栖中林，回头顾矰弋。","谁能测忧心，孤鸣日将夕。"]},{"t":"有感二首 其二","f":"五言古诗","c":["西眺王屋山，日夕青峨峨。","上有冲漠人，开关对松萝。","偶来广成子，所交不贵多。","晨兴掬流泉，举首餐明霞。","灵鸟从空来，阶前啄松花。","鸟性会吾意，逍遥共山阿。","寄言寻真者，何必穷天涯。"]},{"t":"登楼望秋山","f":"五言古诗","c":["登楼望秋山，薄暮有佳色。","秀拔殊自然，重之烟霞饰。","众鸟各知归，行人早栖息。","劳生赋词间，客愁复何极。","高哉刘伯伦，独能颂酒德。","几时掩荆扉，养心在冲默。"]},{"t":"春雪有感","f":"五言古诗","c":["哲王能下士，栖栖此异县。","动欲感邹枚，曾披梁孝传。","懒病不可医，索居起常晏。","嗟哉古贤达，未能甘贫贱。","贳酒过比邻，春城正雪霰。","山川郁葱间，万形为之变。","窟深龙尚蛰，巢寒鸟自恋。","积阴无好怀，怅望无人见。"]},{"t":"夜集王元美宅赋得弄玉吹箫障子","f":"七言古诗","c":["垂老疏狂燕赵客，今宵雅集王郎宅。","堂开屏障出丹青，杂花抱石烟冥冥。","中有仙匹为谁子，云是秦娥及箫史。","秦王昔日起高楼，帘捲曲栏人并倚。","咸阳城头悬月明，玉箫吹作凤凰声。","忽令千树秋风生，又令百鸟翻然惊。","太空袅袅清不绝，声落万里丹山穴。","坐揽德辉下宫墙，并乘彩翼凌穹苍。","直上清都朝紫皇，俯视九州尘茫茫。","神游元气几千载，因之驱石填东海。","祖龙驾归多鲍鱼，浮云一散河山在。","二仙缥缈不可知，吴歌且复挥金卮。","他日功成鹤书至，拂衣莫负蓬莱期。"]},{"t":"题扬子云草玄图","f":"七言古诗","c":["蚕丛之国三秦西，千峰上与青天齐。","栈道悬空历万险，巨竹脩藤当昼迷。","瀑布砰訇响不绝，阴壑直下垂虹霓。","班虎咆哮黑熊啼，飒沓风舞双鹍鸡。","路出剑门沃野阔，锦江秋水明玻瓈。","蜀中文物古来盛，两汉名士特标题。","前有马卿后扬子，高才往往怀金闺。","火德中衰世板荡，谁能皓首甘幽栖。","枫树森森隐茅宇，荒凉门径无轮蹄。","草玄拟易坐朝夕，冥心自得穷端倪。","水有汀洲山有溪，居然此道在盐齑。","龙蛇知时蛰深窟，男儿志气何乖睽。","校书阁下独遗恨，首阳二子光蒿藜。"]},{"t":"醉歌行崔太傅席上作","f":"古风","c":["绿草何葳蕤，秋风吹复吹。","名园物色照罗绮，转眼萧条鶗鴂悲。","富贵可能长满意，就中忧喜多参差。","君不见平原待士重然诺，豪侠酬恩终是谁。","未必知人在仓卒，难将宝剑分雄雌。","故园还寻旧朋好，一丘半壑相游嬉。","路傍采菊花，林间指酒旗。","杖挂百钱随兴尽，瓦杯无谢黄金卮。","城头月出任归迟，醉和青莲居士诗。","山鬼亦久立，岭云亦低垂。","惊波荡平鹳鹤渚，大风吹断猢孙枝。","落落胸怀自天地，前身或是偷桃儿。","白首狂歌倒接䍦，接䍦与尔偏相知。","旦浥海霞之清气，夜沾松露之华滋。","轩冕几人老无恙，野谈宁结渔樵期。","万古圣愚一生死，山川不异开辟时。","我欲买田种黍剩酿酒，丹侣遮莫留茅茨。","阅世独醒太索寞，请看北邙高下冢累累。"]},{"t":"题香山禅院示玉峰上人","f":"七言古诗","c":["清秋策马湖西路，孤寺鸣钟山欲暮。","偶逢老衲是同乡，相对不言中有悟。","人生自抱摩尼珠，乾坤谁种菩提树。","何劳长检贝叶经，如来在心非在形。","蒲团坐久忘尔我，不知草虫喧户庭。","夜半无灯亦无月，檐前松柏何青青。"]},{"t":"狼儿涧歌","f":"古风","c":["狼儿涧东扶杖行，石工斧凿无停声。","太古栖身秪巢穴，轩皇之后多有营。","渐伤元气非今日，三代相因栋宇成。","石工死，石工生，天地不老青山平。"]},{"t":"吊古战场","f":"古风","c":["行行路何长，驱马来穷荒。","征伐几兴替，空馀古战场。","连天白草动寒色，拂地皂雕盘夕阳。","漠漠黄沙埋枯骨，终宵无定鬼火光。","四野征旗但云雾，千年杀气馀风霜。","裂土封侯殊有志，力平北敌更西羌。","将军失律万夫死，惜哉秪饱虎与狼。","生男胡为事戎行，爷娘不见增悲伤。","深闺恸哭罢刀尺，为谁灯下缝衣裳。","托心梦寐恍一见，安得招魂还故乡。","薄伐太原自中策，秦皇汉武开边疆。","至今烽燧尚多警，长城万里徒周防。","翻然挽辔独归去，浩歌倚剑天苍凉。"]},{"t":"七夕行饯别王安州","f":"七言古诗","c":["三春不见王子猷，隔林黄鸟声相求。","停云怅望心悠悠，讵期千里会燕州。","樽前罗绮多名讴，晚来新月低帘钩。","白榆花发银河秋，灵鹊架桥天女游。","鸾舆拂曙终难留，归时锦机鸣不休。","千丝万丝萦别愁，盈盈一水长西流。","离合定期惟女牛，人生相忆恒阻脩。","五马明朝易水头，我亦驱车还故丘。","年年今夕怀朋俦，坐转玉衡空倚楼。"]},{"t":"送杨员外子畏之江东","f":"七言古诗","c":["龙剑千里神相通，心知不在离合中。","都亭久别今一晤，美人又去长江东。","帆外水天渺无际，白波如练摇丹枫。","阊门樽酒复谁同，孤怀惨淡生秋风。","乱草已非伍胥宅，百花曾绕吴王宫。","霸业往事但明月，浩歌五湖惟钓翁。","虎丘凭高正慨古，飞鸟远没苍烟空。","莫忘词客疏幽意，老却春洲芳杜丛。"]},{"t":"登盘山绝顶谒黄龙祠","f":"七言古诗","c":["蓟北来游第一山，上连七十二禅关。","人行巨壑泉声里，马度层崖云气间。","石径萧萧松吹冷，万折千回临绝顶。","钟响时传下界遥，鸟飞不到诸天迥。","无劳汉使泛槎心，挥手银河能几寻。","历历边城纷蚁垤，明明沧海一牛涔。","老僧笑指烟霞外，此意沈冥谁与会。","风生平地本无因，云点太清犹是碍。","吊古踟蹰空石堂，黄龙西去杳茫茫。","珠林不见菩提影，宝塔长含舍利光。","壁尘拂去独留赋，下岭回看迷晓雾。","放浪人间那复来，月明梦绕盘山路。"]},{"t":"哀哉行 其二","f":"古风","c":["燕京小儿眉目青，出门嬉戏娘叮咛。","一蹙容颜问所欲，恨不上摘月与星。","岂意今秋值丧乱，兄妹散失身伶俜。","北去伤心涕泪零，风沙满面栖荒坰。","长成被发能跃马，阴山射猎无时停。","回首宁不念乡国，长城日落天冥冥。","哀哉行，谁堪听。"]},{"t":"哀哉行 其三","f":"古风","c":["燕京少妇殊可怜，自嫁北里无婵娟。","临镜装成数顾影，日换罗绮何新鲜。","正尔相欢鼓琴瑟，愿如并蒂池中莲。","中秋月好宁长圆，烽烟散落高梁川。","铦锋逼人动寒色，不忍阿夫死眼前。","一去龙沙断归路，吁嗟此身犹独全。","哀哉行，天胡然。"]},{"t":"王主簿乐三归自昌平志感","f":"古风","c":["嗟哉宁阳簿，东北惊鼙鼓。","一身乱后回，眼见苍生苦。","伏尸满地下乌鸢，谁复盖棺归黄土。","高秋鸡犬静千家，落日桑榆空万户。","万户荒凉谁复存，昌平道上易销魂。","有时空林一秣马，野风萧飒吹蓬根。","金城晏安不可恃，长星堕地兵戈繁。","烟尘歘起天改色，敌骑杂遝当人门。","杀气遥连碣石馆，愁云更失燕丹村。","村墟四顾豺虎乱，龙荒戍卒各星散。","羌童隔河霜月中，芦管横吹夜漫漫。","狐奴山下鬼火明，车箱渠上人烟断。","大旗风动亚夫营，天意冥冥终在汉。","送君东去勿复叹，对酒且歌白石烂。"]},{"t":"元夕同李员外于鳞登西北城楼望郭外人家时经兵后慨然有赋","f":"七言古诗","c":["仙郎邀我元夜游，联镳驰向都城陬。","凭高北望馀杀气，初春惨淡翻如秋。","银花无光火树死，月明空作金波流。","忆昔华灯乱星斗，天叫陆海通瀛洲。","美人盛服散香霭，侠少相随簇锦裘。","万家歌舞帝王州，广衢深巷连崇楼。","杨枝插门春不见，膏粥祠户今何由。","燕京女儿去朔漠，紫姑寥落亦含愁。","城中箫鼓太平象，城外风烟边戍头。","御宴黄柑存故事，浊醪不解骚人忧。","洞庭佳酿醉方休，来岁今宵复何处，客踪宦辙如云浮。"]},{"t":"送郜羽士归青城山","f":"七言古诗","c":["道人汗漫游人间，自云家住青城山。","清谈动有烟霞气，流年不凋松柏颜。","碧桃花开春正好，金银阙下违仙班。","悬壶卖药寄朝市，独乘黄鹤今西还。","九转垂成怀旧侣，剑阁彭门路脩阻。","时人不识仙骨殊，明月梦中闻杜宇。","七十二洞群真聚，天外吹笙来玉女。","彩云拂地飘异香，紫鸾解歌朱凤舞。","琼浆坐吸长自春，飞泉落响无今古。","海西高攀若木枝，才临玄圃复瑶池。","丹台坐读十洲记，俯视浮生能几时。","燕昭汉武俱冥漠，陵庙白杨空自悲。"]},{"t":"少女词","f":"七言古诗","c":["妾家住近都城下，今日何辜来朔野。","不随姊妹并乘龙，翻与健儿同跃马。","马上归心数向南，故园桑叶废春蚕。","长颦翠黛愁无那，暗落铅华瘦不堪。","不堪对月空凄切，屈指清光几圆缺。","道路空迷古塞云，衣裳犹带阴山雪。","雪后惊看鸿雁回，隔河羌笛使人哀。","龙沙三月无青草，莫向春风怨落梅。"]},{"t":"题山水图送包运司庸之赴芦台","f":"七言古诗","c":["披心清彻冰雪壶，挥毫妙绝江山图。","包生好古求真迹，名齐顾凯游京都。","四明画手不易得，秋水晴岚无多墨。","极天形胜随意生，半壁低横万里色。","蒹葭浦溆苍烟深，上有参差枫树林。","虚堂时时动风雨，波底恍若蛟龙吟。","一扫冰绡幽兴发，笔夺造物古人列。","吾将垂钓君宦游，扁舟独啸五湖月。","送君驿路别愁新，北望偏伤客子神。","鸣鞭岁晚长芦去，芳草相思春复春。"]},{"t":"宫词题画 其一 春","f":"七言古诗","c":["晓起下阶芳草绿，越罗昨夜裁春服。","试看海棠开几枝，流莺啼过黄金屋。","花落明年仍复新，玉颜对镜堪愁人。"]},{"t":"宫词题画 其二 夏","f":"七言古诗","c":["风静帘垂花竹里，银床冰簟净于水。","夕阳犹照长信宫，太液池东片云起。","禁门深锁夜如何，秪恐芭蕉风雨多。"]},{"t":"宫词题画 其三 秋","f":"七言古诗","c":["青桂花开秋已半，夜深绛阙低河汉。","起看月影落金盆，纤手掬之光历乱。","双玉跳脱近水寒，坐来长袖凭阑干。"]},{"t":"宫词题画 其四 冬","f":"七言古诗","c":["寒鸦暮集昭阳殿，疏雪因风上罗荐。","早梅寂寞几多花，春在深宫君不见。","好折一枝将献君，何人吹笛彻宫云。"]},{"t":"闺怨","f":"七言律诗","c":["别时梨树栽后园，结实垂枝秋正繁。","摘来堆盘甘可食，游子不归空叹息。","长叹临风疏叶下，青楼还系紫骝马。","夜深梦著难挽君，满天愁结湘江云。"]},{"t":"送周一之从大将军出塞","f":"七言古诗","c":["长剑斫山石可摧，劲弓射海波能开。","宿昔相逢重然诺，意气干霄不可回。","酒酣独上黄金台，吴歌忽断天风来。","曾笑要离空侠节，复轻郭隗非奇才。","二十馀年滞京国，俗尘总不关胸臆。","一朝长揖大将军，材官相顾无颜色。","丈夫颖脱自有时，百年遭际几相知。","陈琳倚马能成檄，王粲从军还赋诗。","昨夜秋风吹大旗，据鞍喜动幽并儿。","铁骑连营亘千里，馈饷日日无停期。","喧阗笳鼓长城路，沙拥潮河仍北渡。","杀气遥沈白马关，暮云横断黄花戍。","单于已遁尚屯兵，嫖姚看逐西山兔。","闺中月照流黄机，应念征人犯霜露。"]},{"t":"陶渊明图为杨考功虚卿题","f":"七言古诗","c":["异代知心不识面，年书甲子甘贫贱。","孤云横天高莫攀，白石在水清自见。","徵君殁后柴桑空，千古犹存五柳传。","彤庭九锡加寄奴，典午山河王气变。","南国从教麟凤归，中原不息龙蛇战。","彭泽县前江水流，当年心事同悠悠。","解印那堪白日晚，还家不负黄花秋。","吏人送酒方适意，惠远更教莲社醉。","中怀久矣齐死生，一卧茫然失天地。","醒来兴感岁欲残，金陵怅望空龙蟠。","独赋荆卿聊寄意，风吹落木江声寒。"]},{"t":"张令肖甫郊饯闻笛兼慰卢次楩","f":"古风","c":["严城西畔开离筵，郎官送客斜阳天。","有人吹笛正凄怆，晴云改色迷山川。","野风太急万柳折，倏忽波涛翻九渊。","骊龙惊起珠欲堕，乱鸟无声愁向我。","梅花一曲何断肠，萧瑟零霜肃满座。","卢子挥泪不胜哀，衔冤垂老谁怜才。","君不见祢衡傲岸成祸胎，鹦鹉洲上多莓苔。","骚人往来酬酒杯，黄祖于今安在哉。","当秋苦调莫三弄，听彻踌躇转悲恸。","张令知心不可忘，关河月照滑台梦。"]},{"t":"小姑谣","f":"七言古诗","c":["阿婆使妾舂稻粱，小姑又唤缝衣裳。","一时不应小姑怒，可堪颜色来风霜。","小姑打时只袖手，小姑骂时只闭口。","眼看小姑也嫁人，姑嫂不得长相守。","闻道比妾小姑多，小姑他日当如何。"]},{"t":"同李兵宪廷实刘计部伯柬宴集因谈五台山之胜遂赋长歌","f":"古风","c":["残冬游五台，几步一徘徊。","石罅松根出，云端山势来。","地接龙荒莽无际，疏林但见冰花开。","绝顶下连万丈雪，阴崖长积千年苔。","经过险巇有藜杖，天许诗人独放旷。","青山不断马头前，红日忽翻鸦背上。","我来转折无尽时，奇处复奇难形状。","焉得江南顾凯之，为予写成岩壑障。","五台山高齐插天，开辟有色同苍然。","平生想像劳梦寐，到时飘逸如登仙。","蹑屩越丹崖，挥手拂紫烟。","化城金界未深入，远公逝矣谁相延。","灵脉永存功德水，彷佛彻耳来飞泉。","令人心思净于洗，不根突出纷青莲。","指点烟岚动广席，何当鹫岭共攀缘。","二君壮图逢昭代，岂暇联辔游山川。","向予叹息且酌酒，日下圭峰重回首。"]},{"t":"拟裁衣行","f":"楚辞体","c":["天南越峤郁苍苍，苧葛结阴岩壑傍。","越女搴条共笑语，野风细吹脂粉香。","晓星出门落日返，一家姑嫂时相将。","千丝万丝手中过，要织纤缡如许长。","闺中咿?鸣机杼，几人力织才盈箱。","数匹较来一匹强，却为野老裁衣裳。","著身便有烟霞气，青山何处非吾乡。","步虚好追松乔辈，采芝更逐黄绮行。","葛衣之轻当炎暑，狐裘之重禦雪霜。","被服及时无轻重，人间万事多参商。","舞翻广袖发浩唱，不羡接舆为楚狂。","且挂薜萝坐倾酒，满园月露澄秋光。","每逢七夕仰河汉，天孙馀巧散下方。","我欲登楼酹椒觞，掷梭一女兮使人嗟叹空徜徉，使人嗟叹空徜徉。"]},{"t":"雨中同鲍叔愚邓廷献二明府卢岩寺观瀑布泉漫赋","f":"古风","c":["洛中金界通西域，叠嶂相连兴无极。","画图浓淡自天开，涧树岭云真水墨。","宦侣羁人随胜缘，颇同怀抱异筋力。","题名绝崖能定心，指顾泬寥临叵测。","为爱此泉今复来，遮莫阴晴皆有得。","素弦倒写半天声，白练长悬太古色。","松亭坐赏清吾神，衰年后游焉可频。","黄叶杂苔秋寂寞，樽前不遇桃花春。","来时风雨迎，去时风雨送。","山灵未必忌诗狂，何阻跻攀访仙洞。","老衲鸣钟车马归，人间几夜卢岩梦。"]},{"t":"梦瑶池篇寄上大冢宰吴汝乔大司徒刘体乾少冢宰林贞恒大理卿刘致卿中丞朱自充鸿胪卿史应之诸公","f":"古风","c":["往年披阅山海经，昆崙夜入梦中青。","瑶水虚涵月与星，琪花拥石烟冥冥。","金母相见授宝诀，紫霓长裾飘广庭。","醒来不见鸾鹤舞，仍依草莽间柴扃。","忆昔穆王何独幸，八骏交驰造仙境。","白云联谣传至今，自非仙骨徒引领。","神游可到万国西，无缘那得蹑丹梯。","江南揽胜犹未遂，却欲黄河源头还杖藜。","三晋淹留湖海士，偶逢吴客谈扬子。","面前空阔信无地，浩荡波声坐中起。","天落混茫如掌平，金焦双秀出烟水。","龙窟深浅问篙师，下窥明珠探复止。","千帆晚泊大江湾，丛苇乱蒲灯火间。","长干女儿唱新曲，买醉阿谁不解颜。","狂兴将阑曙色动，起看月落钟陵山。","钟陵山，在何处，建业城高势相据。","地连吴越雄东南，偏助六朝几词赋。","燕子矶笼翠柳烟，凤凰台压丹枫树。","老年怅望立中原，向平五岳复何言。","路无远近有难易，恨不生垂天羽翼任飞翻。","杜蘅又老沧江渚，索居守拙谁相与。","我愿圣代多贤臣，身閒堪作渔樵侣。","冢宰司徒抱经济，廷尉中丞悬大计。","正直更羡鸿胪卿，一朝俯念回先帝。","方喜戈船不动海戍清，稻田其奈又祲岁。","夜深共仰紫微垣，万里无云正秋霁。"]},{"t":"汾州以来分守参政如胡世甫葛与立马子懋程信夫彭克宪陈元卿李子高宋伯镇孙格卿张时芳纪恒甫诸公皆旧识也宋有禦敌之功不见知当道解官归越嗟哉","f":"七言律诗","c":["边尘连岁静于扫，塞马曾嘶汾上草。","落日偏增流水寒，白云不减青山好。","宦游此地故知多，半是閒门雀可罗。","伯镇守城功自见，农桑依旧满西河。"]},{"t":"赋得长歌答许左史殿卿兼伤李廉宪于鳞","f":"古风","c":["梁国仙才许长史，别来神会书千里。","书中泪渍尚盈纸，旧交为失沧溟子。","眼前勋业逐流水，百年行藏半日诔。","足踏天风超騄駬，山岗振裂叫虎兕。","要夺精华与骨髓，秋风细咀黄金蕊。","正色染心陶令是，石火铁铛煎凤嘴。","文辉灵液岂徒耳，海右茫茫联步屣。","终童请缨那可恃，伏生传经竟老死。","地胜时平磨崖纪，鹊湖清浅映芳芷。","丽人桂棹空自舣，伫立亭亭思靡靡。","不见马援南征载薏苡，存殁无言净秋水。","西署为郎谈义士，鲁连排难宁专美。","龙也楠也一梦里，欲达哀情托山鬼。","九泉有知长已矣，薄暮下帘独隐几，冥冥莫测造化理。"]},{"t":"离感篇远示元灿元煇诸儿","f":"古风","c":["移家邺城接建安，西来轗轲悬忧端。","异乡感怀殊不寐，剑闪七星灯下弹。","鲁缟齐纨价易买，越罗蜀锦人争看。","无计疗穷痴儿怨，糟糠老妻任艰难。","不见少陵几口走栈阁，赖有橡实时充餐。","白帝春归同寂寞，锦江月出两团圞。","中原兵戈阻旧国，黄尘杀气相迷漫。","我逢昭代幸无恙，晋俗留人惊岁残。","又不见要离何为火妻子，霸图直欲功名完。","身后梁鸿并蒿里，不如五噫行歌石可刊。","久雪敝衣惜奴婢，漫将诗草发长叹。","吕望八旬持钓竿，困龙且向积水蟠。","谁道颓年气傲岸，四海交游曾结欢。","公门了无一字干，秋潭照心无波澜。","小儒孟浪竟何益，睥睨宁知世路宽。","暗洒淤泥污巢由，箕山忽崩颍水乾。","神明在天笑魑魅，时复清风吹鹖冠。","俯视人间尽浩渺，独登万仞之峰峦。","吹笙爱听子晋曲，仙骨能胜鹤背寒。"]},{"t":"刘舜谟赵允书高德公三子晚过因谈诗法漫赋长歌兼述别意","f":"七言古诗","c":["峨冠野服非凡质，对榻论诗坐终日。","力搜东海宝珠来，法转西天龙象出。","楚猿乱聒夜冥冥，谁听湘妃鼓瑶瑟。","欲为古调高可跻，赋声好振太行西。","莫画少陵神自合，更深梦落浣花溪。","江通鱼腹山无隔，月照峨眉路不迷。","醒来归思候晨鸡，春草未生羸马嘶。","黄金筑台战国术，何必郭生志与齐。","凤城花时兴逾远，北岳有灵迎杖藜。","攀萝蹑屐殊萧散，笔扫层崖秃千管。","气横大漠雕不飞，响彻空林虎应断。","荷衣独立最高峰，老骨欲仙无寒煖。","洗兵焉得挽天河，阴山单于近纳款。","尚思朋辈共离樽，燕赵茫茫目力短。","壮怀奋激歘乘风，若木扶桑指顾中。","他年相见重把手，宁羡征南矍铄翁。"]},{"t":"终南仙人引走笔遣怀","f":"古风","c":["终南据形胜，隐沦共墟里。","中有千年不死之真人，鹤发垂垂过两耳。","门无徵车道长存，平生懒到咸阳市。","青山有主百灵护，竹杖通灵山鬼妒。","化作苍龙乘海云，巨鲸伏鬣洪涛驻。","惊回任公钓，触倒扶桑树。","力穷万里知所归，掉头西秦灵复聚。","老夫神变物相因，内蕴不关天地春。"]},{"t":"铜雀台吊古歌","f":"古风","c":["龙飞白水承火德，千里草青汉家厄。","曹瞒秉钺剪群雄，独据中原此尽力。","盖棺一缩九州心，西陵日暮愁云色。","地荒铜雀空莓苔，世变铜驼秪荆棘。","乱机相仍天有知，长风忽来正叹息。","歌舞尚多身后情，玉颜惨淡雕栏侧。","断肠雨泪洒衡漳，呜咽至今流不极。","流不极，悠悠复悠悠，那见翠华耽宴游。","胜景无穷乐有限，建安人去浮烟收。","讵知千载邺下客，不教寂寞河山秋。","却忆腾蛇乘雾翻自谓，松楸直上俨豪气。"]},{"t":"古怨","f":"七言古诗","c":["阿郎别家春草短，莲叶又欹清霜满。","朱栏拂云江上楼，玉娘纤手弄鹅管。","奇调能令烟水白，寂寞芙蓉失颜色。","老龙惊动脱明珠，遽走团光留不得。","宁思河北邯郸路，门前旧种垂杨树。","花飞恨不到天涯，倦鸟安栖共朝暮。"]},{"t":"赋得买丝绣作平原君寄山中故友","f":"七言古诗","c":["登台北瞻此何世，漫嗟寥落依松桂。","英雄有待岂徒老，泽龙神变随巨细。","黄金买丝秣陵市，好绣平原赵公子。","想像当年下士心，烟薰古色宛相似。","万丝无迹天巧成，吴姬亦知豪侠名。","身后宁复谈纵横，野云聚散犹秦兵。","异代重之独长吉，下帘焚香共一室。"]},{"t":"示秣陵王卜者长歌","f":"楚辞体","c":["杖藜来自建业城，何术遂有江湖名。","邺中共讶严君平，心悬日月照万里，西向玄圃东蓬瀛。","几言入微谁复精，历窥千山蚁穴殊分明，众流不混浊与清。","剖鱼得子信无数，能辨孰为龙兮孰为鲸。","龙施霖雨鲸翻海，世间灵异由天成。","忆昔梁园初识面，下帘对客谈贵贱。","一谈贵人文凤来，梧桐正花彩云见。","又谈穷苦水塞河，鹭鸶俛首冒霜霰。","野夫问命却不同，上指老鹤仍飞九霄遍。","谓我八十馀年可到否，讵学渭川垂钓叟。","圣代疏慵无所系，花下徵歌时进酒。","慎勿太洁且尘垢，高士传中何必有。","壮年排难不畏人，而今世路好缄口。","京西山水昔游处，昨宵梦掇湖中藕。","还拟蓟门走马摇丝鞭，紫氛碧霞浩相连。","山灵暗护鬼物遁，岸帻醉呼身似颠。","无限精华方寸贮，尔露天机何见许。","白头不死更探奇，望望安期空枣树。","传书道来竟不来，月出深松独延伫。","百岁凡骨草同枯，神追扬马越徐庾。","王生之言起予兴，说与香山旧禅侣。"]},{"t":"拟太白夜泊黄山闻殷十四吴吟坐对刘元善偶成","f":"七言古诗","c":["黄山夜泊芦花滩，北斗垂天篷底看。","有客吴吟促我兴，调高上彻浮云端。","蛟龙侧耳海波静，猿狖无声山月寒。","悠悠半空倏忽堕，金石交音满吾坐。","曲罢始闻新都钟，枫林烟岸闪渔火。","今夕佳会复何许，乘秋早发横江舵。"]},{"t":"法云篇送芜上人访吴楚真僧","f":"七言古诗","c":["法云不断随高踪，洗钵寒潭悟毒龙。","千岁枯藤四海杖，半山古寺五更钟。","野店馀斋饲饥鸟，参禅直上匡庐峰。","才尽三吴又经楚，衰草园陵不吊古。","暂寄人间未坏身，独入风林伏啸虎。","夜逢老衲说楞严，门掩篝灯正秋雨。"]},{"t":"江淮篇赠别董中丞叔化赴南都","f":"七言古诗","c":["龙飞淮西四海一，中丞秉钺才无匹。","洛下文名更武功，白昼霜威动萧瑟。","不闻村落啸群鸱，始信客行日自吉。","忆昔岛夷争陆梁，野塘岸坼鲸波溢。","采桑女儿变容颜，杀气乘春逼蚕室。","江甸云屯骠骑营，犒士黄金散千镒。","能用将才元老心，丙魏不言汉良弼。","渔樵生计任歌谣，耕织人家敞蓬荜。","鼋鼍闭窟净浮天，蛟蜃缩涛平荡日。","篙师舵叟宁复喧，水怪山精讵敢出。","十年两台今最劳，草疏先朝肃簪笔。","事关转饷忧非轻，早起披衣独盥栉。","神明暗护永安流，禦敌练兵仓廪实。","海门直北停万艘，吴舸楚帆鳞次密。","秣陵城上望燕京，长空无涯孤鸟失。","心悬丹扆侍鹓班，漳南苦吟正力疾。","坐披史传夜深灯，不见古人贵胶漆。"]},{"t":"赋得峨眉山长歌寄酬刘中丞维南","f":"古风","c":["峨眉两山横蜀土，五岳之外更奇睹。","千年积雪净含春，几道奔泉寒迸雨。","四十阴洞生肉芝，多少仙粮谁是主。","樵苏不到云霞深，莓苔堆径色自古。","脩藤密萝覆涧户，众隐忘形淡相聚。","真仙向之引凤鸾，老衲居然伏豺虎。","神工开辟出丹青，人间画师心何苦。","李白夜行见真景，千仞峰头月半吐。","中原有客殊自惜，栈阁衰年万里隔。","恍听杜宇枕畔啼，梦魂飞越剑门驿。","山灵不识邺下狂，欲往登危虚谢屐。","锦官城高锦江碧，残照疏林扬马宅。","两汉接迹钟神秀，不餐烟火超凡格。","六朝绮丽落后尘，大方雄浑浩无息。","谋猷大展际昌期，宪台防秋坐深夕。","君不见紫微光耀圣明世，阊阖森严百灵卫。","健儿牧马尚龙荒，未许终童请缨计。","今王宵旰劳宰臣，黄钺白旄任非细。","佳政威声幕南北，材官乘障气逾锐。","纥干冻雀向日飞，太宇茫茫绝纤翳。","又不见漳河流水向东逝，野夫支筇望天际。"]},{"t":"严阁下敏卿筑锦峰台赋寄","f":"七言古诗","c":["锦峰挥手接飞翼，元气无涯揽不得。","霖雨收功身自南，边庭纳款念仍北。","北极瞻依为筑台，奇观倚槛客迟回。","迸泉落涧微茫转，拂水翻空开辟来。","晚来星垂霄汉近，沧波直下伏蛟蜃。","海日浮光众岛分，湖天远色三吴尽。","吴越相连一棹通，流觞胜事永和同。","罚酒宁拘金谷数，题诗能振玉堂风。","风景触人忧乐系，稻田稼穑端居计。","万壑时寻丹洞仙，九嶷夜梦苍梧帝。","帝泽犹沾到子孙，梅花岁晚素心存。","积雪凝寒罢登眺，呼童煮茗莫开门。"]},{"t":"寄赠赵中丞良弼","f":"古风","c":["美人倏散不相聚，日暮停云低野树。","当朝柱石望全功，避世衡茅自安堵。","宪节翩翩下浙西，海氛未息苍生苦。","湖山风景惨淡秋，谁复兰舟载歌舞。","知君正气干层霄，栖霞岭头独吊古。","奸臣骨朽忠魂在，潮吼钱塘至今怒。","武昌城高昔登临，黄鹤飞来衔好音。","初加开府渔樵颂，先得荆州父老心。","丹枫叶凋鄂渚夕，含思坐落天际参。","君不见辽阳戍垒日萧森，转饷艰难忧更深。","三韩乘秋多警急，烽火夜照枯桑林。","圣主垂衣新御极，默俯公卿赐颜色。","将术奇正服单于，天教两戒限南北。","君秉旄钺宣威德，三楚无虞通万国。","驰神每向承明庐，大江东流浩不息。"]},{"t":"寄赠张中丞肖甫","f":"七言古诗","c":["家住铜梁巴蜀间，风尘不倦老容颜。","海内胜游无定辙，满囊行纪汉河山。","山青水碧秋更好，建业东连阊门道。","龙虎高城驻夕阳，麋鹿荒台没秋草。","共谁吊古扩怀抱，夹岸丹枫零落早。","未满商家傅说心，春来细雨泽枯槁。","槁木开花造物功，三农完税歌年丰。","犹恐苍生岁暮穷，繁霜两地忧思同，感时草际乱鸣虫。","不信试看江上月，老夫极目送征鸿，又起萧萧西北风。"]},{"t":"徐仪宾世鸣彤管纪贤题赠长歌","f":"古风","c":["宫花玉叶丽且鲜，广庭日煖横瑞烟。","琴瑟能调正声协，双鸾对舞何翩翩。","翠帘绣阁春相连，有女窈窕侍琼筵。","仙桃结子钟仙气，红芳萎落回风前。","朱弦变调入悽惨，漳水呜咽流溅溅。","郡君含悽心更悬，明珠掌中殊可怜。","朝亲盥栉出枣栗，眼看长大垂髫年。","恨不仰摘星辰助文字，青云悠悠上在天。","苞凤祥麟俱世网，徐卿国琛得永传，拟标彤管闺中贤。","自古佳人几愁绝，不妒蛾眉汉宫月。"]},{"t":"野父杂感","f":"七言古诗","c":["结庐不临车马道，交游须待商山老。","泉冲涧石声自清，霜染江枫色更好。","暗响泠泠常满耳，一朝野望净于扫。","驯雀下阶相对閒，钩帘独坐披素抱。","儿借佛书越松岭，归来短衣沾雪冷。","老禅为说梅初花，纸窗幽寂横瘦影。","杖藜不到诸天遥，卧听清钟彻凡境。"]},{"t":"送徐逸人归天台山","f":"七言古诗","c":["游子悲秋梦故里，马头一掉北风起。","浩波霜下伏蛟龙，绝岭林深藏虎兕。","中原闻说有狂才，驾舫高歌呼酒杯。","气横峭壁云根动，力截奔涛地脉开。","白首浪为岂幽事，欲行不行尚留意。","海腾日色晴堪游，天漏雨声暗有忌。","徐干仍孙见尔曹，我当千载继风骚。","三台基废漳流合，七子神游海月高。","东南形胜慕几载，吴越山灵久相待。","我赋寄将题建标，敢期终古倍霞彩。"]},{"t":"山中隐者","f":"七言古诗","c":["晚风吹云覆四野，有人晦迹萝岩下。","百年杖屦秪荒径，万里山河一草舍。","御寇至言顺造物，不知力命非达者。","何必空名束此身，比邻酒熟杯堪把。","蚁群列阵眼前兵，世事浮尘隙外马。","烟火隔林古兰若，石罅迸泉散地脉。","飞流倒向山厨泻，诸天在心半偈写。","白莲正花香满池，陶潜又醉远公社。","月转松西坐深夜，晓来俗客忽敲门，啄苔驯雀上屋瓦。"]},{"t":"渔樵叹","f":"七言古诗","c":["东岭上头多树木，猛虎藏威白昼伏。","西潭水深鱼鳖多，下有长蛟绝网罗。","渔郎樵夫各生计，相逢共嗟太平世。","两毒所恃期永年，山根地轴暗相连。","背罾腰斧每聚散，回首茅茨炊烟断。","妻子菜色饥尚可，户口办钱愁杀我。","问天不言空苍茫，四郊落叶正风霜。"]},{"t":"守拙吟因客谈及蟭蟟蜘蛛之巧赋此","f":"古风","c":["世人得意笑轗轲，多营寡营无不可。","一时争巧鸟与虫，百年守拙谁知我。","画里疑通五岳云，梦中恍驾三湘舸。","少有四方志，老诫垂堂坐。","君不见池面生沤石迸火，汨罗葬身首阳饿。","古今万事成浩叹，风雨西来木叶堕。","夜寒拥衾茅屋破，日出群动人高卧。","力疾正披老庄图，邻翁扣门送药裹。"]},{"t":"穷居吟寄胡秀才希颜","f":"七言律诗","c":["白头自守攻周易，家住荡阴烟树隔。","寒蛩在壁夜何悲，穷鬼连床暗有益。","心含寸天无蔽云，平生不羡送穷文。","眼中宦达几凋谢，垄树啼乌空落曛。"]},{"t":"示元宝禅师","f":"七言律诗","c":["短榻翻经坐朝暮，门前一转西方路。","月满人间各自心，天虚潭底谁能悟。","四十年来静掩扉，东林遥听夜钟微。","渐看禅子易衰老，松杪白云何处归。"]},{"t":"拟少陵忆昔行望王屋天坛二山作","f":"七言古诗","c":["秦岭路迷愁无那，凉夜疏林老夫坐。","蹇驴龁草人正饥，野翁敲石取新火。","须臾炊黍摘秋果，小有洞天曳杖过，仙境踟蹰岂敢唾。","山灵预知待客星，虎穴应教黑雾锁。","欲蹑玄踪不易到，峭壁攀萝壮襟抱。","轩皇驾龙无还期，精华长耀金光草。","少陵题后独啸傲，历揽瑰奇恣所好。","忆昔道傍贤主人，一饭至今尚思报。","别来音问若为通，三十几度梨叶红。","嗟彼枯骨蒿莱中，梦著已忘旧颜面，遥寄此情东北风。"]},{"t":"望临青故里感怀","f":"七言古诗","c":["故里民居夹轩盖，五十年来几度改。","当时儿曹今老大，垂髫旧识我独在。","人间醉眼莫见真，倏忽春光不相待。","东西两河归一流，岸拥蒹葭秋复秋。","忆昔扬帆坐舒啸，海门北转是燕州。"]},{"t":"乔木颂赠别郭隆夫暨乃侄惟显春试","f":"七言古诗","c":["凤文麟德明时出，延揽英豪网罗密。","佳气低连太液云，祥光高映长安日。","当朝二阮非晋俗，不谈玄虚重儒术。","九重四散御炉烟，对策彤庭挥巨笔。","更羡两疏真伟才，补衮齐心匡汉室。","乔木根深地脉滋，上参碧空千万枝。","广阴覆城去炎暑，动摇时复清风吹。","老龙潜海倦霖雨，天教群种待昌期。","古来史传宁无私，野夫作颂久相知。","短褐冲寒送别处，玉堂应忆衡漳湄。"]},{"t":"形问影","f":"古风","c":["我自无中生，尔自有中出。","日间相随动千里，灯下相依静一室。","贫贱自安尔何忧，祸福自当尔不愁。","百年世事各劳逸，忽睹镜中齐白头。","我养心神尔不悟，我还造化尔俱休。","问答入微乃见道，陶潜异代神同游。","彼此相忘但沈醉，卧榻焉知有天地。"]},{"t":"书客吴海归抚州为乃翁索题四山长歌","f":"古风","c":["闻说鄱阳湖，洪波荡流万亿顷。","白云秋色入混茫，欸乃纵横几渔艇。","洞穴浮光照终夕，神龙抱珠睡不醒。","中央突兀拥苍翠，别有天地一仙境。","两峰复两峰，倒插虚塘太古影。","下通坤轴深莫测，山根欲动石头冷。","鹤嫌鱼腥非真味，独餐元气巢其顶。","老翁自由脱世网，不检丹书心愈静。","时序长存松桂盟，烟霞偏助桑榆景。","安得良工写出水墨图，远隔吴楚见形胜。","高挂壁间旷我目，毫端能尽泽国迥。","要探奇绝须主人，昨梦登攀杖藜并。","游子寄声江雪寒，北风吹帆送归省。"]},{"t":"浩歌篇","f":"古风","c":["人间岁月机头梭，无药可青双鬓皤。","两病垂死加餐饭，眼中新墓栽松萝。","铭旌往往少年子，焉知商山万古郁嵯峨。","一丘半壑世堪避，短草疏花春渐多。","诸孙随我步晴景，白云片影落沧波。","隔岸相呼鸭与鹅，聊供笑乐复如何。"]},{"t":"武陵蒋明府子培过邺因谈桃源之胜南都杨茂才伯海曾绘斯图并长歌见寄勉成一篇用答两意云耳","f":"七言古诗","c":["武陵贤宰多爱民，若使逋逃犹避秦。","城头常悬岁时雨，洞口不隔天地春。","君探奇踪问渔父，鸡犬日閒似太古。","一涧如空石作桥，千家相接蓬为户。","辍棹问津沅水西，厚俗非关晋风土。","沙丘半路没祖龙，阿房那听咸阳钟。","荆南斜日莽迢递，目穷候雁徒支筇。","我欲胜游系怀抱，昨夜梦着巴陵道。","谁能写出桃源图，仙花长红春长好。","含毫搆思通神明，汉江髣髴东流声。","寄我半幅见两绝，兼之大篇殊纵横。","斗室豁然入浩渺，坐间波动烟霞生。","蒋王云仍岂凡骨，一脉来自建康城。","杨子相知念衰老，建安回首中原情。"]},{"t":"蝴蝶叹","f":"古风","c":["醉来万事无不掷，醒后多思那有益。","月当中天光渐昃，人逢盛时病相迫。","君不见花间蝴蝶草间飞，清霜满园何处归。"]},{"t":"闽中兵宪徐子与黔南学宪吴明卿自都下相别历二十年矣孟春癸夘夜予梦二君话旧既寤仍梦同渡漳河吊古因思社友存殁相半悲哉","f":"七言古诗","c":["文章搆患屈平始，凤凰不来桐树死。","老夫浩叹谁见心，眼中两人隔万里。","一宵连梦片月知，漳浦共吟铜雀妓，吴歌楚调悠扬起。","左手把袂右拍肩，恍看形容皆妙年。","勿阅丹经拘悟性，句法自神骨自仙。","地开灵脉通九渊，龙珠并出破暝烟，含光可重精华全。","旧交星散疏消息，人间是非在广识。","名家多自轗轲成，其奈江流不向北。","寄兴芙蓉各秋色，空采幽芳坐将夕。","当代风云渺南极，大海平铺闽越天，乱山横断罗施国。","建安遗迹那相忆，宦邸飞梦吾莫测。"]},{"t":"梦少司马总制刘子和赋寄","f":"七言古诗","c":["燕山形势帝王州，野夫北望生边愁。","密云城上风倒起，密云城下河翻流。","昔破乌丸万骨朽，曹瞒自恃孙吴谋。","战场色惨汉时月，军门气压胡天秋。","今代全才能镇静，豪侠那复谈封侯。","青草平连古北口，材官但逞射雕手。","单于归心未偃兵，龙荒独持扫尘帚。","旌旄内转始解颜，应待铙歌报捷后。","夜来念切梦何人，皓月馀光照疏牖。"]},{"t":"晚坐槐庭同王明府师古各赋短歌以志幽兴","f":"七言律诗","c":["繁阴坐久日将夕，孤鸟飞来此栖息。","雨滋苔径交苍痕，月出槐庭破暝色。","一官宁辞百事劳，琴弹白雪调弥高。","更期联榻澄心夜，天外松风万壑涛。"]},{"t":"江南李秀才过敝庐因言及诗法赋此长歌用答来意","f":"七言古诗","c":["草堂细雨茶烟迟，远来客子爱吟诗。","一朝变化悟是主，悟到无形偏有为。","天设织机夺众巧，扶桑茧缫五色丝。","金茎甘露浮清气，半空吸彻了仙味。","但爽词人藜藿肠，汉家仙基竟入魏。","太白少陵两诗豪，探奇不尽登临费。","暗谷顿使魑魅藏，阴崖宁无神明卫。","苦心须求格调工，寄兴莫与凡流同。","峨眉峰头弄片月，羊肠路口追长风。","平顺却难险巇易，含毫垂首沈思中。","圣代无媒自萧散，杖挂百钱步可缓。","出门游眺欲忘归，天际好山青不断。"]},{"t":"诵孙中丞山甫全集赋得长歌寄赠","f":"古风","c":["黔南词人吾旧识，吟成不下千金璧。","调如白雪郢中才，响如倚楼吹铁笛。","力如夸娥移二山，神如骤雨走霹雳。","势如昆崙周万里，气如战胜开边鄙。","老如篯铿三代仙，古如夏鼎出地底。","丽如丛桃蒸晓霞，清如片月蘸秋水。","奇如侠士慨谈兵，深如沧海没长鲸。","高如鸿鹄碧空尽，远如葱岭细烟横。","君家流风自孙绰，赋就天台掷地声。","忆昔琐闱夜直向北斗，先朝谏草不复有。","旌旄过邺访衡门，应记垂杨夹巷口。","磨崖独步太和颠，托彼山灵护悠久。"]},{"t":"寄赠祝使君质夫长歌行","f":"七言古诗","c":["住宅因人多秀丽，广陵南控三吴势。","淮流入海使君心，楚甸带山农父计。","绿上娑罗树叶春，李邕碑石独嶙峋。","书声静夜连诸巷，机响寒天共四邻。","今日讼庭閒鸟雀，群僚分理万家乐。","晚来月出太行颠，照见冰霜清满郭。"]},{"t":"赋得江南山水纪胜歌并寿毛友梅封君","f":"古风","c":["君不见吴山高起千万丈，上有烟岚变化出奇状。","影照江流湖水地镜分，下抱太空各垂文光密星象。","晓日波平如熨横素罗，幽鸟低飞閒来往。","岸芦石树小径斜，隔岭樵歌应渔唱。","山根湖脉下相通，福基寿域深且广。","武陵主人偏嗜黄精淡可食，子孙皆换仙骨格。","望云何由并称觞，时复驰神到乡国。","元气混沌含孝胚，圣人独知立兹德。","堂中高挂二仙图，木公金母若旧识。","两颜不衰百岁期，际天海色苍茫浩无极。"]},{"t":"长江之水歌送匡使君淑教谪大梁","f":"古风","c":["君不见长江滔滔发源来自西，坎德至清且洁彻底无浊泥。","浩荡遽使星河动，苍茫不教日月迷。","夏禹为疏凿，力与神功齐。","探胜讵言彭蠡泽，遇仙宁说武陵溪。","千转乎赤枫之岸，万折乎黄芦之堤。","地非关百馀里，波倒翻如许长。","朝横蜃楼气，夜闪骊珠光。","若开辟，无湾子，路易尽，止莽流，徒泱泱。","又不见汉代车生，一日九迁，恐造物忌之而有妨。","吾不知使君理郡何如也，父老欲挽不留遥相将。","放逐时人意，谁复此心忘。","历观史传贤愚善恶生性也，其奈蜉蝣撼绿杨，枝叶荣悴在风霜。","我亦徬徨，彼亦徬徨，夹道班马连嘶驻夕阳。","古来宦达有行藏，好驾轻帆无恙赴大梁。","访信陵，可话壮图，遮莫宝剑闭匣含星芒。"]},{"t":"秋夜雨中述感呈王殿元允仁时寓普照禅院兼示无瑕上人","f":"七言古诗","c":["禅窗夜雨不成寐，侧枕微吟聊自慰。","老僧破竹编疏篱，滋养菊花开也未。","葫芦架底乱寒声，薜荔墙间浮湿气。","安得九霄出月光，北照帝城分象魏。","豪门秉烛各丝簧，醉杀五侯拜七贵。","明朝老仆畏冲泥，却省探囊沽酒费。","欲过西林问寂寥，煮茶不尽淡中味。"]},{"t":"思归引","f":"古风","c":["有家归去来，旅颜何摧颓。","胡为戎马际，滞此燕昭台。","十日九寄书，不慰妻子怀。","秋风忽动思故园，山妻捣衣儿候门。","缺月半天霜满地，悄然孤馆销人魂。","不见嵩高之山青嵯峨，上有松柏下有河。","松柏可餐河可钓，老来幽事嗟无多。","离乱至今我独苦，梦中归路迷烟萝。","庞公旧隐须一访，白云惨淡终如何。"]},{"t":"赋得万山形胜歌赠胡明府子仁","f":"古风","c":["万山形胜，新安高据开城闉，江连三百六十滩头多绿蘋。","移根拔秀归何人，独收两间元气津。","梧桐正花雨露春，凤凰振翼文彩新。","海霞绮丽耀侵晨，影落巨波翻龙鳞。","片霞可握文可擅，左能万化右千变。","大将纵横谁不见，老成已识古人面。","岂学傍门色求茜，美人自是金闺彦。","壮图不凡且京县，北瞻斗极倚楼遍。","闻说蒲城古迹仲由堂，满地月浮寒光如素练。"]},{"t":"赠王别驾仲谐金陵浩歌篇","f":"七言古诗","c":["建业世居风俗古，盛年游好谁相与。","石头城影落晴波，扬子江声喧暮雨。","豪贵笙歌虚岁华，即今礼乐几名家。","日蔼低浮杜蘅色，春深半吐梧桐花。","凤凰台上青天近，文物好谈吴与晋。","北瞻形胜帝王州，王气茫茫殊不尽。"]},{"t":"读周谏议用馨诗集漫赋长歌行","f":"古风","c":["安陆城西，渔船夹岸灯明灭，晚集枫林，郢人巴人半优劣。","解佩亭前水尚流，仙蛾不见风景别。","欲访还丹妙术学延年，入悟何当问老禅。","宛如箭射昆崙直透出，声落星宿海波荡九天。","搥碎须弥为平地，下开混沌别创万国分山川。","寓言谁超庄列上，古来多少大宗匠。","太远莫令失归宿，至玄更得高气象。","气象非凡人所瞻，淡然细味水晶盐。","梅梢夜挂西楼月，沆瀣常餐不下帘。","隔帘冰雪清神思，阳春自歌写胸次。","深宵忽散珠玉光，为收诗草开箧笥。","楚客调同和者多，旋沽帝城腊酒宁辞醉。","紫微下与琐闼邻，圣代应知不负人。","人间风雨隔朝列，海中日月容波臣。","汉江东逝自不尽，蛟龙作伴待时振。","倒翻铁网拔出珊瑚根，丛根赤色长含润。","了此上乘何处谈，华岳峰头共坐烟岚千万仞。"]},{"t":"赋得山水图长歌赠潘太守瑞徵","f":"古风","c":["华岳上逼层霄，可窥星斗之真迹。","黄河来自西极，长送昆崙之正脉。","绮霞彩虹灿一色，枫林岂让柿叶赤。","光映石岩好登陟，眼中胜景谁尽得。","薄暮翠岚藏秀月又黑，姑射仙子夜游信能识。","天与元精豁胸臆，后园独种蟠桃核。","仙果熟时未敢食，欲献圣皇咀味跻寿域。","汾水朝宗流不息，上方龙剑到手除荆棘。","更刬长安路平通，万国直臣共佐唐虞德。","渔樵各生计，官吏不虚职，澶州正对燕京北。","欲命良工写此图，高挂不出乎半间之壁。","主人坐赏最珍惜，神游中宵乘彼苍凉片月白。"]},{"t":"柳川园亭宴集同孔老赋","f":"七言律诗","c":["郭北林园开洞府，王孙又是青山主。","一杯云影座中天，半壁泉声厨内雨。","掬水清心犹易醒，竹阴聊尔话丹经。","西河自有名家赋，龙在深潭见地灵。"]},{"t":"寓居东园兰轩主人索诗赋此以应","f":"七言古诗","c":["迩来城市厌纷扰，借居名园得幽讨。","有妾厨下事晨炊，门外苍苔閒自扫。","烟火恐妨松竹清，清风宜诗起常蚤。","脩竹赤霞映虚窗，不异图中小蓬岛。","凿池栽藕生红蕖，叠石成山发瑶草。","吾闻此地昔荒凉，始知胜景由人造。","王孙布置亦经纶，醉客飞扬倍词藻。","百花栏内秋转芳，昨宵风雨为花恼。","深沈曲折人忽迷，兹可还丹隐仙老。","前起高楼后筑台，徙倚披云天浩浩。","太行一发望中横，放浪乾坤此怀抱。","共怜满院丛桂香，应忆淮南著鸿宝。","坐来且检种树书，地阔根长树更好。","待君夜话浊醪杯，月白空庭再倾倒。"]},{"t":"蜀中行赠李仲白","f":"七言古诗","c":["蚕丛之国千山阻，漂泊西南尔何苦。","客子畏人浇俗间，孔融不见谁为主。","出门感慨非中原，黄叶几凋乌桕树。","玉垒悲歌万里云，锦江卧病三秋雨。","久罹患难何所营，物色萧条有环堵。","九口流离半死生，儿女遗骸寄兹土。","梦绕高都身未归，泪洒春风啼杜宇。","十年亡命聊定居，当道其如有豺虎。","浮云忽散青天回，灵剑方弹紫气吐。","去时三峡逐惊涛，直犯蛟龙荡双橹。","归时栈阁下知难，秦塞桑村闻社鼓。","田园第宅属他人，衰白相怜独邻父。","上书北阙心事明，莫恋西山旧茅宇。","话尽艰虞殊惨然，樽前促膝更千古。","古来豪贵何足论，名臣屈指对君数。"]},{"t":"岁杪行上德平镇康安庆三王","f":"七言古诗","c":["陶潜昔日居柴桑，诸儿嬉戏时相将。","吾生多累何感伤，况复离合殊无常。","烛儿长成亦自强，解念衰颓来异乡。","敝裘风雪能禁当，心事未了向平忙。","其如旅馆惟空囊，空囊出暴悬斜阳。","欲收元气通诗肠，山林胡为忌老狂。","倏忽云起天迷茫，似恐夺秀归东方。","凭高举手酬一觞，千峰万壑幽思长。","岂独杖藜经太行，更搜五岳成文章。","奚奴窃笑立我傍，谓予晚节比松篁。","却与片时閒商量，穷冬几促典衣裳。","只须拥衾不下床，梅花春信隔宫墙。","终朝岑寂对冰霜，汝曹好为扫中堂。","垂帘兀坐焚名香，神游四海同春光。","春光颜色不凄凉，于今好客多淮王。"]},{"t":"春雪柬左溪子","f":"七言律诗","c":["王孙每招重词赋，坐对山川秋欲暮。","鸦背斜阳醉后天，马头凉雨归时路。","我去三关一寄情，今春又客太原城。","积雪满庭人不到，卧看说苑忆更生。"]},{"t":"登太原城楼送李郡丞叔东移任平阳","f":"古风","c":["会晤何迟别太早，白首相违感衰草。","郭南咫尺望飞旌，况复青山之外红尘道。","渡汾水，向平阳，一官两佐郡，突见君才长。","兵散潢池尽赤子，能使人家悲又喜。","是非定矣多荐书，萧艾何曾混兰芷。","河东城上垂杨秋，河东城下沧波流。","父老欢迎那更愁，仍是去年李霍州。","从今姑射洞前或有梦，心清得与仙人游。"]},{"t":"送杨玉伯归泾阳","f":"七言古诗","c":["凤凤城南杨柳丝，当春袅袅牵别离。","古人折赠意偶尔，至今千里传相思。","风吹柳花正西去，黄鹂唤春春不住。","落日关河怅远人，青丝白马归三秦。","壮年不叹功名薄，独将宝剑淹风尘。","有时大笑对樽酒，七雄能战不能守。","燕昭之策非远图，空使黄金高北斗。","君才落落谁见知，且向沧浪随钓叟。","秋来水上烟云重，慎勿濯足惊鱼龙。"]},{"t":"题陈中贵园亭","f":"七言律诗","c":["去秋亭馆曾招客，几处张筵到深夕。","花竹学成金谷园，池塘倒插锦川石。","昨经春雪复来游，古木閒云淡若秋。","尚忆歌童唱新调，醉来拍手见风流。"]},{"t":"雨雪曲酬戴锦衣伯常见赠","f":"七言古诗","c":["穷冬雨雪白浩浩，蓟门万木惊春早。","横笛谁吹出塞声，梅花乱落关山道。","海云不散寒悠悠，客怀无那空倚楼。","有人忽赠阳春曲，坐吟驱我羁旅愁。","风流云是楚望子，家在郢中四十里。","三十年来锦作衣，天颜咫尺多清辉。","金阙门中鸣佩入，玉河堤上摇鞭归。","归来对酒兴不尽，月明更奏飞龙引。"]},{"t":"送李侍御化甫巡边","f":"古风","c":["绝漠黄云浩莽莽，层冰大雪几千丈。","一夜压倒燕然山，白日不照北海上。","海色欲冻惨不流，鲸鲵僵卧天吴愁，朔风猎猎吹不休。","千山埋部落，万山失马牛，安得壮士弯弧策紫骝。","君王一怒静边尘，使者乘骢当北巡。","行看勋业上麒麟，倚长剑，苏烝民。"]},{"t":"中秋寄南都冯户部汝言去岁此夕会汝言潞阳时警兵变感旧赋此","f":"七言古诗","c":["小楼独坐悲秋光，美人阻绝天一方。","丛桂花开欲同醉，其如南北成参商。","燕塞干戈朔气动，秣陵风雨江涛长。","忆昔中秋潞水阳，相逢月下倾壶觞。","金波可爱不可掬，清宵宛在冰雪堂。","倚树高歌起乌鹊，星河欲落天苍茫。","离亭向晓初分手，歘见沙尘犯街柳。","驿路时时问捷书，都城夜夜听刁斗。","朝廷有意访贤才，将士于今严战守。","募兵千里屯京师，日散黄金无尽期。","海内诛求信不易，艰难早晚君王知。","谢安高卧欲何补，冯唐老来应自悲。","宦游旅食两不见，莽莽风烟各京甸。","昨闻宝剑赐嫖姚，五都侠儿争习战。","上林鶗鴂秋一鸣，北极浮云日千变。","三吴凋敝若为看，何当疏奏明光殿。"]},{"t":"冬夜徐子与宅同梁公实宗子相食黄精作","f":"七言古诗","c":["蓟门古木摧寒声，海月未高庭雪明。","主人掩户自幽寂，客来盘荐多黄精。","昨日盈筐走道侣，嚣尘难得山中情。","春苗满山被甘雨，正色独从灵土生。","斲来一烹倏变化，咀之入玄筋骨轻。","我亦狂歌避世者，何当辞家从向平。","名山大泽无不有，手把长镵行复行。","龙蛇深藏雪没径，时有白云相送迎。","青天茫茫发孤啸，悠然直与元化并。","海鹤传书约三子，共蹑九霞游赤城。"]},{"t":"朱楼曲","f":"楚辞体","c":["朱楼峨峨江之浦，中有美人弄机杼。","引领望之路脩阻，鶗鴂鸣兮凋芳杜。","我有所怀未敢语，吁嗟归来重延伫。","朱楼峨峨江之干，中有美人织素纨。","引领望之路险难，鶗鴂鸣兮凋芳荪。","我有所怀未敢言，吁嗟归来重汍澜。"]},{"t":"走笔效太白歌行寄上沈王殿下","f":"古风","c":["少游燕赵间，亦有燕赵气。","大德不易酬，俯仰在天地。","天地无言覆载我，两鬓全白齿半堕。","匣中宝剑蓄龙精，四海历游无不可。","时逢厚俗且为家，宁羡淮南丛桂花。","人生知遇非偶尔，枚马聚散殊堪嗟。","君不见太行天设中原春，颠崖直上几千尺。","愿作峰头一片云，飞向宫城朝复夕。","西风若肯徐徐吹，风云长会无尽期。"]},{"t":"再寄沈参政敬叔","f":"古风","c":["一骑飞去南阳城，乱山不断云纵横。","奔流触石聚风雨，七十二湾河水声。","水声清彻何人耳，隐侯楼上正徙倚。","迩来宦游梁楚间，丰年祲岁关忧喜。","问君草疏当时心，俨对神明琐闱里。","回瞻北极紫微垣，落月鸣钟宿鸦起。","欹枕遐思谁复同，四海苍生不寐中。","洛城有客自神会，古今胜事归豪雄。","不见诸葛旧庐没秋草，谁卧烟霞空自老。"]},{"t":"伤刘羽泉总制","f":"七言律诗","c":["频年楚越徵兵路，能使秋阳破海雾。","旌钺威中春万家，歌谣声里霜千树。","当朝将才多壮图，或战或守清江湖。","吴地干将气犹盛，接天愁色满新都。"]},{"t":"送吴山人子充游云中","f":"古风","c":["春寒揽貂裘，蹀躞驱紫骝。","问君去何许，云是塞门游。","丈夫安肯栖故丘，北向龙沙天尽头。","苏武城头积雪满，李陵台上孤云愁。","二子杳然不可见，神交千古心悠悠。","眼前陈迹增感慨，弹铗悲歌回素秋。","燕然之山忽改色，金河之水翻倒流。","风吹大荒落日惨，胡雁惊飞不复留。","此时踟蹰多隐忧，百年意气怀朋俦。","独自磨崖题赋罢，还来共醉长安楼。"]},{"t":"暮雨送春","f":"古风","c":["花盛春将归，岂待百花飞。","有人独先见，感叹当斜晖。","霍家豪贵从头数，金谷繁华无定主。","客边杯酒且酣歌，向夕闭门风又雨。"]},{"t":"登城歌","f":"楚辞体","c":["古贤哲兮择交游。","世无漆兮胶莫投。","彼何人兮非俗流。","大德在心兮不可酬。","直言数兮生衅尤。","枳棘当路兮我孔忧。","登高楼兮望九州。","孰为友生兮嗟未休。"]},{"t":"雨雹有感呈宋大参","f":"古风","c":["客窗午睡晚来起，帘外明明一庭水。","云是雨工碎却阴山冰，雷电相驱寒色里。","击瓦骤破群雀惊，迸阶倒回众儿喜。","痴儿不解老夫忧，指点门前说未休。","苍生所望在禾黍，更欲馈饷供边头。","于今宋玉夜无寐，岂待落木方悲秋。"]},{"t":"瞻远楼为宋大参伯镇赋","f":"古风","c":["古姚州，郭西别业开林丘。","花石夹阶小玄圃，极天形胜当高楼。","况复三台之峰最秀拔，岚光直向空中浮。","画栋雕甍耀日月，倒写丹碧澄溪流。","窗含沧海越东雨，檐接明河天上秋。","啼乌一声重悲嘅，凄风忽起蒹葭洲。","君不见混茫万古鱼龙国，下通地轴深叵测。","倏荡烟霞旷望间，四时元气浩无极。","众岛波翻几点青，日初隐见扶桑色。","阴晴变幻入挥毫，不到冥搜未易得。","神会动千里，岂独穷目力。","逝水与孝思，悠悠两不息。","更堪岁晚对冰霜，主人怀抱复谁识。"]},{"t":"晚登洛阳城西望灵宝寄怀许太守令夫","f":"七言律诗","c":["薄暮高城独延伫，望中飞鸟没烟树。","岘山何异楚天云，盘涧更连秦甸雨。","二十年来春草长，儿童牧马向斜阳。","广州人睹磨崖赋，北指中原说大方。"]},{"t":"寄金广文","f":"七言律诗","c":["汉廷谁复怜才子，谪去长沙几千里。","三楚寒云过雁声，九疑秋色摇江水。","骚人自古悲秋风，黄陵庙前斑竹丛。","惆怅湘灵杳何处，试听瑶瑟月明中。"]},{"t":"寄谢车国医元吉","f":"古风","c":["西来苦诗思，力疾自河汾。","访尔园亭共幽事，疏篱拥菊当斜曛。","能为膏肓驱二竖，更谈命脉经宵分。","天应不忌徐陈辈，使我得遇长桑君。","拟渡三江弄明月，漫游五岳披高云。","山川留得放歌叟，杖头百钱且沽酒。","有药可扶垂老身，检方已见回生手。","相逢两幸无重轻，诗与尔名同不朽。","奚童驱马一函书，人在高都几翘首。","所怀况值冰雪晨，去年倾盖知予真。","黄鸟鸣时好乘兴，遥认门前杨柳新。","恐君采药山中去，怅望桃花各自春。"]},{"t":"雪中偶过李鸿胪东明宅留酌因怀卢太史浚卿刘少参才甫王侍御子梁张户曹聚甫","f":"七言古诗","c":["前雪未消今雪来，寒侵宫殿朝不开。","昆池冻合石鲸卧，玉笛唤春催落梅。","白日远迷涿鹿野，黄云低暗轩辕台。","铁甲如冰战士苦，城头饥乌啼正哀。","北风吹人僵欲死，驱马不动空徘徊。","道傍官舍何幽寂，我亦山阴乘兴客。","入门自拂谢庄衣，开樽为我破寒色。","中怀倾倒醉不辞，春灯吐花向深夕。","同乡朋旧各天涯，绿鬓忧时谁易白。","宦情客计成睽违，海雁江鱼断消息。","重来清夜益相思，月明偏照燕京陌。"]},{"t":"马上赠罗山甫","f":"七言律诗","c":["有客翩翩时并马，壮游气激风霜下。","边笳声断卢龙天，塞草寒深涿鹿野。","皂雕飞从西北来，弯弓欲射空徘徊。","圣代虚名莫轻取，朔云低暗黄金台。"]},{"t":"秋夜云峰书斋饯别赋得秋字","f":"古风","c":["丈夫平生何所求，百年与世同沈浮。","枕上一思动万里，黄金容易齐山丘。","君家父子继刘向，时振藻思多冥搜。","著书堆案未满意，眼前岂暇观蜉蝣。","君不见五龙山上千松稠，松枯石烂名应休。","况今乐善存古道，日无俗扰轩庭幽。","晚来有客自延款，呼童出典青绮裘。","高烛结花照几席，西风吹动湘帘钩。","共谈世务复文字，宾主相看俱白头。","笑我吟诗胡不饮，清时独抱三闾愁。","讵知醉客轻王侯，剑歌豪气不能收。","豪气混茫隘江海，弯弓欲向扶桑游。","巨涛歘腾在跬步，翻空不定风飕飕。","万蜂衔珠夺明月，鳌鱼背上信宿留。","仙侣相将踏紫雾，才穷三岛仍十洲。","肯学书生拘细论，寓言聊尔从庄周。","人生大小各有志，岂徒衰老工雕锼。","龙蛇已藏地窟夜，鹰隼争击天关秋。","君还闭扉我行路，扬鞭西北指并州。","故人相逢说旷达，空囊去住能自由。","托乘山川随处赋，姑射洞开石髓流。","山灵为喜标形胜，禁彼众鸟无啁啾。","翠华杳然吊汉武，白云汾水空悠悠。","英雄不遇生太晚，何时且遂田园谋。","漳河之源自发鸠，因忆邺中走马经长楸。","徐陈零落罢欢宴，不闻广殿弹箜篌。","惊心两堕井梧叶，嗟哉太行何阻脩。","上党有待几朋俦，黄花正开酒新篘。","定约登高醉九重，满天秋色当西楼。"]},{"t":"丽情曲","f":"五言律诗","c":["昔会春江曲，美人知我心。","朝遗白玉佩，夕赠紫璚琴。","梦入楚天远，愁连湘水深。","刺桐花又落，黄鹄断佳音。"]},{"t":"清凉山秋夜听儿元灿弹琴","f":"五言律诗","c":["吾儿解幽事，露坐一弹琴。","声落石崖迥，兴当秋夜深。","潭龙乘月色，山鬼傍松阴。","飒飒天风起，清商满翠岑。"]},{"t":"侠客行","f":"五言律诗","c":["家住渭桥边，追随侠少年。","斗鸡输宝剑，逐兔落金鞭。","日下长楸陌，霜高太白天。","新从霍骠骑，裘马独翩翩。"]},{"t":"秋野","f":"五言律诗","c":["地阔清霜满，林寒赤叶稀。","野云秋澹澹，山日晚辉辉。","杀气三河动，边声一骑飞。","中原多猛士，谁解晋阳围。"]},{"t":"暮秋即事","f":"五言律诗","c":["十见黄花发，孤樽思不胜。","关河秋后雁，风雨夜深灯。","留滞悲王粲，交游忆李膺。","相随少年子，走马猎韩陵。"]},{"t":"同宋子纯杜约夫晚渡漳河访李淑东","f":"古风","c":["幽期何惮远，秋色满山川。","月出平林外，人行落雁边。","水村时下马，沙岸夜呼船。","正有东篱菊，相?醉里眠。"]},{"t":"宿淇门驿感怀","f":"五言律诗","c":["驻马淇门夕，空堂暑气徂。","暝烟官树合，寒雨驿灯孤。","浊酒聊幽兴，悲歌亦壮图。","相违旧朋好，三径日荒芜。"]},{"t":"毛侍御仁甫幽居","f":"五言律诗","c":["早年归别业，高枕远浮名。","树杪孤云度，门前一水横。","黄花留晚计，白鸟识幽情。","为爱嵇中散，疏慵是养生。"]},{"t":"登天坛山","f":"五言律诗","c":["直上断岸悬，崎岖一径缘。","白云秋满壑，红树老参天。","神护轩皇鼎，灵通太乙泉。","何由结丹侣，共此学长年。"]},{"t":"南园秋暮","f":"五言律诗","c":["地僻青山近，庭空白露漙。","鸣蝉秋共老，落木夜多寒。","惆怅乡书滞，疏慵世路难。","遥思篱下菊，儿女不同看。"]},{"t":"隆庆道中有感","f":"五言律诗","c":["马度黄云塞，雕飞白草原。","兵戈连岁动，霜霰入秋繁。","农业千家废，人烟几处存。","中途有行子，伫目亦销魂。"]},{"t":"榆林道中言怀","f":"五言律诗","c":["秋风吹短褐，长啸过居庸。","羸马有归思，枯蓬无定踪。","山横边色断，日没野阴重。","旅鬓成衰飒，谁知阮嗣宗。"]},{"t":"初冬夜同李伯承过碧云寺","f":"五言律诗","c":["并马寻名寺，登高藉短筇。","飞泉鸣古涧，落月在寒松。","石路经千转，云岩复几重。","人间多梦寐，谁听上方钟。"]},{"t":"送史德龙下第归江都","f":"五言律诗","c":["送送芜城客，南归暂索居。","沙云鸥鸟畔，江雨稻花初。","白发愁看镜，青山坐读书。","汉庭知己在，早晚荐相如。"]},{"t":"暮春晦夜同冯汝强汝言昆季饯别章行人景南使上党得光字","f":"五言律诗","c":["官舍延星使，灯前数举觞。","何当添夜漏，聊复驻春光。","鸿雁北来尽，关山西去长。","赠君有芳草，岁晏莫相忘。"]},{"t":"夏夜集王元美宅同朱伯邻冯汝言吴峻伯徐汝思李于鳞得丝字","f":"五言律诗","c":["献赋长为客，风尘鬓易丝。","投珠还自惜，倚玉几相知。","庭旷生秋早，城高度月迟。","聊同河朔宴，定拟竹林期。"]},{"t":"禅林寺赠本无上人","f":"五言律诗","c":["步屧来金界，鸣钟落翠微。","松阴回古殿，山气入秋衣。","身向诸天老，心从初地归。","后期薜萝月，宁遣梦中违。"]},{"t":"盘山最高峰迟应瑞伯不至","f":"五言律诗","c":["仄径高盘壁，孤峰半插天。","人行飞鸟上，袖拂落霞边。","涧水寒逾咽，山花晚自妍。","一樽迟俦侣，松月向谁圆。"]},{"t":"夜集有客忆江南梅花","f":"五言律诗","c":["坐有三吴客，天寒重所思。","梅花何处发，春信隔江迟。","雪月摇疏影，山村出几枝。","罗浮遥入梦，邻笛不须吹。"]},{"t":"重过张氏园林二首 其一","f":"五言律诗","c":["驻马深林下，名园两度游。","独寻花里径，更上竹西楼。","池鸟閒相语，山云澹不流。","却思离乱日，松菊负高秋。"]},{"t":"夜自西湖循瓮山同玉峰上人步归兰若","f":"五言律诗","c":["湖色冷春衣，沙禽夜尚飞。","路随山下转，僧伴月中归。","祗树藏金界，禅灯出翠微。","他年谢灵运，结社愿无违。"]},{"t":"秋夜柬李通政子渐","f":"五言律诗","c":["燕地逢君晚，秋来樽酒期。","桂花相对夜，烽火共忧时。","月隐长安树，云低太液池。","谁能上封事，独有纳言知。"]},{"t":"秋夜柬张给事仲安","f":"五言律诗","c":["青琐邻丹禁，天阶逼斗枢。","宫云兼树冷，海月傍帘孤。","谏草劳深思，年华感易徂。","相逢北来使，几为问边隅。"]},{"t":"赵王枕易见寄","f":"五言律诗","c":["江海通元气，风云入浩歌。","行人犹未返，芳草欲如何。","沙晚閒凫雁，山春秀薜萝。","淮南赋招隐，悽恻感情多。"]},{"t":"留别郭学士质夫","f":"五言律诗","c":["学士同樽酒，相知老去深。","青云司马赋，白日董狐心。","春气浮东阁，晴光动上林。","应怜多病客，归卧薜萝阴。"]},{"t":"元夕道院同公实子与于鳞元美子相五君得家字","f":"五言律诗","c":["长空月正满，游骑隘京华。","夜火分千树，春星落万家。","乘閒来紫府，垂老问丹砂。","笙鹤归何处，依稀见彩霞。"]},{"t":"忆王屋山","f":"五言律诗","c":["昔探王屋胜，犹忆杖藜初。","野老窥丹洞，山灵护宝书。","云生苔壁暗，松响石坛虚。","欲访烟萝子，茫茫失旧庐。"]},{"t":"还邺二首 其一","f":"五言律诗","c":["客路多芳草，还家春服成。","交游嗟献赋，妻子问谋生。","自得山林计，深知猿鸟情。","一樽吟薄暮，风雨闭柴荆。"]},{"t":"还邺二首 其二","f":"五言律诗","c":["迢遥囊橐轻，词客本无营。","久别儿孙大，初归鸡犬惊。","几年违旧业，多事感浮生。","坐倚中庭树，春风可寄情。"]},{"t":"登泰山","f":"五言律诗","c":["登攀绝顶处，封禅断碑文。","古洞寻丹液，秋衣拂紫氛。","下飞关塞雁，东接海天云。","惆怅秦松在，寒涛空自闻。"]},{"t":"春同陈郎中汝忠登邺城兼寄于鳞子与","f":"五言律诗","c":["有客停骖日，重城共一登。","晴烟开北渚，春色上西陵。","中论怀徐干，高风识李膺。","蓟门芳草路，千里兴堪乘。"]},{"t":"暮秋东园饯别邹子序","f":"五言律诗","c":["老大交弥重，穷愁赋可传。","对君犹故国，嗟我异当年。","砌冷蛩边草，霞明雁外天。","菊花留醉客，秋色满离筵。"]},{"t":"暮秋大伾山禅院同孟得之卢次梗醉赋","f":"五言律诗","c":["胜游随故侣，幽兴在禅林。","石上晴云起，松间晚磬沉。","青山无久客，黄菊有归心。","我亦悲秋者，樽前学楚吟。"]},{"t":"寄吴总戎子阳","f":"五言律诗","c":["黄须邺下子，威振北征年。","万里能筹国，三秋长在边。","草枯驰马地，霜冷射雕天。","燕赵多豪士，论功谁更先。"]},{"t":"寄李殿元子实","f":"五言律诗","c":["暂假淮南去，长吟桂树秋。","自知班史在，还结楚骚流。","山色朝侵榻，江声夜满楼。","应怀金马诏，春水送仙舟。"]},{"t":"野兴","f":"五言律诗","c":["独眺西山色，苍然风物繁。","渔樵秋草路，鸡犬夕阳村。","积水明荒泽，閒云度广原。","阮宣今已矣，沽酒共谁论。"]},{"t":"高枕","f":"五言律诗","c":["垂老惟高枕，经秋不到城。","孤吟来鸟雀，万事掩柴荆。","野旷浮云色，庭虚落叶声。","秪应邻叟过，共话薜萝情。"]},{"t":"岁暮宴李太守于鳞宅 其一","f":"五言律诗","c":["别来吾叟老，蓟北尚征尘。","词赋偏忧国，声名实在人。","风驱平野雾，地转浊河春。","侠气空成叹，荆卿旧入秦。"]},{"t":"岁暮宴李太守于鳞宅 其二","f":"五言律诗","c":["为郎殊客礼，领郡重予招。","积雪留孤馆，飞觞动几宵。","有家何处定，多难此身遥。","国士淹今日，应悲豫让桥。"]},{"t":"送别杨中贵使武当","f":"五言律诗","c":["登览君何处，云霞满太和。","身轻鸟外转，心定虎边过。","紫极飘钟磬，丹梯上薜萝。","采芝献帝子，灵秀得来多。"]},{"t":"春日大风集马云从园亭有感","f":"五言律诗","c":["春风何太急，野水忽波澜。","天远孤鸿落，亭虚万竹寒。","田园殊爱静，稼穑久知难。","百感逢今日，萧条醉里看。"]},{"t":"送邺宰石中美转永州别驾","f":"五言律诗","c":["策马零陵道，关山渺万重。","霜明三楚树，云乱九疑峰。","宦迹惊秋草，忧心坐晓钟。","佩刀应不负，几为问边烽。"]},{"t":"初春侯兵宪举舜宅同潘别驾时乘赋得明字","f":"五言律诗","c":["共酌宪台晚，挥觞催赋成。","旅怀春惨澹，吾鬓雪分明。","倚竹三湘梦，披云五岳情。","有人正吹笛，风散落梅声。"]},{"t":"登楼晚眺达轩子同赋","f":"五言律诗","c":["客子聊乘兴，王孙共倚楼。","风烟平野夕，砧杵异乡秋。","半醉还成赋，同怀岂倦游。","望中有漳水，解傍邺台流。"]},{"t":"秋夜宿东林寺","f":"五言律诗","c":["笼中一灯尽，笼外几蛾回。","夜久僧同话，霜明门半开。","寒声虚竹院，秋色净莲台。","还拟东林约，孤筇踏月来。"]},{"t":"除夕西岩君见过同酌","f":"五言律诗","c":["春光在何许，客里只灯花。","分却梅窗兴，来寻草舍家。","夜寒馀巷雪，暝色聚城鸦。","明日谁同醉，应思旧岁华。"]},{"t":"春日书怀","f":"五言律诗","c":["远道驰乡梦，归期隔岁华。","山川醉里赋，鸡犬客中家。","巷僻馀春雪，城高驻晚霞。","邻翁讶疏懒，相见问生涯。"]},{"t":"送徐生归临清","f":"五言律诗","c":["婚嫁了心事，翻多千里情。","关山渺行色，风雨缓归程。","旧业浮云尽，新愁芳草生。","故园春又老，黄鸟断肠声。"]},{"t":"夜过昭觉禅院因忆懒上人同南泉西岩西池诸丈赋得嗟字","f":"五言律诗","c":["重到谈经处，萧条人共嗟。","禅心馀贝叶，老眼讶天花。","孤磬风犹袅，双松月自斜。","太虚渺无际，知是远公家。"]},{"t":"昭觉禅院同南泉西岩二君赋得天字","f":"五言律诗","c":["相约多幽事，频来有静缘。","法云高捧月，祗树暗藏天。","垂老堪投社，无心自会禅。","谁为息机者，默坐奕棋边。"]},{"t":"寄孔方伯汝锡","f":"五言律诗","c":["事有关天地，谁当著述名。","山林一身重，钟鼎几人轻。","芳树杯中色，流泉枕畔声。","应怜玉堂月，游宦老方城。"]},{"t":"次张汝任圆通阁饯别韵","f":"五言律诗","c":["倚阁怜分袂，祗园夜尚游。","松深孤磬落，杯满数星浮。","别浦蒹葭暗，他乡蟋蟀秋。","谁知独醒者，平子不同愁。"]},{"t":"云川书斋同云洲诸丈留别赋得多字","f":"五言律诗","c":["六月期幽赏，银塘有芰荷。","诗从年老健，情到别时多。","夜湿草间露，秋横天上河。","王孙共今夕，郢调付云和。"]},{"t":"七夕敬诚二君饯别得秋字","f":"五言律诗","c":["北斗挂城头，明河迥不流。","人间清露夜，天上白榆秋。","聚散多岐路，悲欢自女牛。","谁知老来拙，回首故乡楼。"]},{"t":"积雨感怀","f":"五言律诗","c":["积阴无晓夜，云气压城头。","雀共疏檐雨，人同老树秋。","晋山何惨色，汾水亦横流。","此俗非荆楚，乡心重倚楼。"]},{"t":"暮雨","f":"五言律诗","c":["坐听萧萧急，无风池亦波。","庭花秋几许，窗雨夜偏多。","老矣乡关梦，悲哉燕赵歌。","不须临晓镜，空自叹蹉跎。"]},{"t":"秋日自遣","f":"五言律诗","c":["甘向清时隐，无令素愿乖。","存虚饶气色，拨累缓形骸。","叶响风前树，苔青雨后阶。","何须学宋玉，登眺苦秋怀。"]},{"t":"中秋有感","f":"五言律诗","c":["客边无节序，吟啸往时同。","故里苔三径，名园桂几丛。","琴樽孤夜月，朋旧各秋风。","坐对青山好，苍茫灏气中。"]},{"t":"秋怀","f":"五言律诗","c":["东望太行路，巉岩几断崖。","易归千里梦，难遣九秋怀。","夜色霜明树，寒声叶满阶。","著书思赵邸，静掩旧茅斋。"]},{"t":"无营","f":"五言律诗","c":["无营诗亦苦，谩说有营劳。","鸟宿三更转，松凉孤月高。","客情疏晚计，人事重秋毫。","我欲栖林壑，忘言醉浊醪。"]},{"t":"倚楼","f":"五言律诗","c":["应接妨诗兴，淹留倍旅情。","别家仍有累，浮世岂须名。","山远暮霞色，林疏秋雨声。","此楼非我室，愁思度阴晴。"]},{"t":"送儿元炳东还","f":"五言律诗","c":["吾儿同入邺，今日汝先归。","留滞乡音改，飘零旧业违。","关河通古道，风雨暗春衣。","寄我思亲泪，西原洒落晖。"]},{"t":"十四夜无月","f":"五言律诗","c":["皓魄将圆夜，张灯坐草堂。","孤城低雨色，万户失秋光。","笛里关山暝，楼前烟雾苍。","金波若满地，随处有壶觞。"]},{"t":"三台","f":"五言律诗","c":["歌舞千年计，鸾舆去不回。","豪华空四野，霸业有三台。","水阔云仍度，沙寒鸟独来。","黄花风露里，寂寞为谁开。"]},{"t":"夜宿齐岭口","f":"五言律诗","c":["空林烟火夜，茅宇暂幽栖。","缺月低松杪，流星堕岭西。","浩歌当绿酒，逸兴在丹梯。","不见功名客，飘然独杖藜。"]},{"t":"夜登瑶台","f":"五言律诗","c":["瑶台当绝顶，乘月一跻攀。","河岳凭阑外，星辰拂袖间。","身轻云自度，心远鹤俱閒。","几欲招仙子，天风听佩环。"]},{"t":"山晚","f":"五言律诗","c":["日落川原迥，商歌独放情。","千峰连暮色，万木乱秋声。","流水相回合，间云自送迎。","人家隔烟浦，灯火望中明。"]},{"t":"同孟怀之钱子青酌白云洞","f":"五言律诗","c":["古树敞岩扉，相携傍翠微。","兴高松鹤下，坐久洞云飞。","天地浮生老，山林胜会稀。","不知蝉冕客，白发几人归。"]},{"t":"春归有感","f":"五言律诗","c":["雨歇上林静，春归东阁虚。","欲烦青鸟使，遥寄美人书。","柳出宫云外，鸦鸣海日初。","只今弹铗者，不为食无鱼。"]},{"t":"送吴子游泰岳","f":"五言律诗","c":["送尔西江客，探奇东岳峰。","断文馀汉石，古色有秦松。","倚杖海天近，听泉云壑重。","金箱閟丹诀，谁共访仙踪。"]},{"t":"送周藩王广文归钱塘","f":"五言律诗","c":["长安芳草歇，多病赏心违。","落日三江满，秋风一棹归。","雨来寒雁失，潮上夜钟微。","梁孝怀词客，无劳访钓矶。"]},{"t":"八月十三夜谭鸿胪子羽第同李太史子寔张给事巽卿莫膳部子良赋得秋字","f":"五言律诗","c":["当樽月欲满，良夜故同游。","宫阙散清雾，星河悬素秋。","病多还授简，客久数登楼。","喜结淮南侣，非关桂树留。"]},{"t":"苗仲材告别登楼晚聎得天字","f":"五言律诗","c":["青山出半天，一带迥苍然。","乱树馀秋色，寒城更暮烟。","交游多惜老，离合几经年。","共有登楼赋，谁为王仲宣。"]},{"t":"送王端甫归浦坂","f":"五言律诗","c":["惜别京华道，秋风送马啼。","日斜孤雁外，家远万峰西。","归计聊樽酒，行歌且杖藜。","何时首阳下，共尔吊夷齐。"]},{"t":"送陆秀才归华亭","f":"五言律诗","c":["九月清霜下，三江白舫归。","芙蓉寒始发，鸿雁暮还飞。","自许同张翰，谁怜滞陆机。","读书沧海上，灯火映林扉。"]},{"t":"周子才惠菊并酒","f":"五言律诗","c":["分我名园种，迎霜花正开。","故山有篱落，秋色此亭台。","坐赏成孤酌，吟看信几回。","因君兴不浅，昨遣白衣来。"]},{"t":"登榆林城","f":"五言律诗","c":["凭高望不极，天外一鸿过。","万岭夕阳尽，孤城寒色多。","芦笳满亭堠，羽檄度关河。","遥忆龙庭士，严霜正荷戈。"]},{"t":"落花有感","f":"五言律诗","c":["花开惊节序，花落转堪悲。","物色殊无意，春风暗有期。","蝶回芳草径，莺度夕阳枝。","独有豪华子，青楼醉不知。"]},{"t":"望西山","f":"五言律诗","c":["西山久不到，花鸟向何人。","风散石崖雪，天开湖水春。","老僧虚白社，骚客负青蘋。","底事燕京陌，黄尘满角巾。"]},{"t":"赠平乡赵隐君","f":"五言律诗","c":["风霾起薄暮，有客叹归欤。","白首犹怀刺，青山且著书。","故乡春树外，别馆夜钟馀。","不见磻溪叟，终然载后车。"]},{"t":"野望","f":"五言律诗","c":["西北消烽火，边关罢檄书。","寒声惟鸟雀，野色但村墟。","石秃烧山后，崖明带雪初。","谁为筹国者，云物渺愁予。"]},{"t":"闻岢岚被兵","f":"五言律诗","c":["三冬几烽火，诸将亦豪雄。","月冷胡笳断，云低汉垒空。","勋名身后别，边议眼前同。","枯木惟啼鸟，凄其向晚风。"]},{"t":"客居即事","f":"五言律诗","c":["客居何懒慢，过午尚科头。","老得医书喜，閒增诗债愁。","春寒风偃树，天晚雪明楼。","莫谓常漂泊，西来是壮游。"]},{"t":"游水竹园孔丈同赋","f":"五言律诗","c":["移得南山竹，冰霜见苦根。","春流触自响，清影羃何繁。","色蘸杯中绿，凉沾雨后痕。","邹枚此同赋，胜事即梁园。"]},{"t":"次宋伯镇游王文父西园韵","f":"五言律诗","c":["郭西车马路，尘外薜萝园。","楼迥晴云合，庭閒秋草繁。","素心犹白鸟，幽事且芳樽。","地胜人多赋，青山谁并存。"]},{"t":"李子田有事代州闻敌犯羊防口憣然归县赋此寄怀","f":"五言律诗","c":["迁客复行役，翩翩向代州。","尘飞随宦辙，云暝结边愁。","归鸟异乡树，悲笳何处楼。","黄花老山县，相待几枝秋。"]},{"t":"东林寺夜集不与次西岩君韵","f":"五言律诗","c":["庐山在咫尺，钟磬落诸天。","不到真如地，遥看香积烟。","轮蹄双树下，语默一灯前。","欲问无生法，衰颓独慨然。"]},{"t":"雨后送刘孝夫东归","f":"五言律诗","c":["相见凄凉色，孤怀风雨天。","黄金交易薄，清镜老堪怜。","马出燕南路，家临济北田。","送君一长啸，高鸟没苍烟。"]},{"t":"京师大雨","f":"五言律诗","c":["夜来雨何急，睡起问儿曹。","秋响门前水，寒生树里涛。","素居邻市井，老计托风骚。","好为冲泥去，新丰贳浊醪。"]},{"t":"中秋夜南园同故人酌","f":"五言律诗","c":["不谒金张第，相期松桂边。","人须今夜酒，月朗故乡天。","归思逢秋色，狂歌度老年。","阴晴如可定，早上玉峰颠。"]},{"t":"送王给事佐之潞州封王","f":"五言律诗","c":["路出西山远，城依上党高。","白云何处望，赤日此行劳。","帝子周封建，天臣汉节旄。","昼游还洛下，气色满宫袍。"]},{"t":"薄暮赵户部良弼官署西园同郑山人中伯醉赋四首 其一","f":"五言律诗","c":["薄暮偶乘兴，开樽非预期。","野夫偏坐久，庭雀故飞迟。","地拔群松劲，天成片石奇。","种蔬甘此味，还使后人知。"]},{"t":"薄暮赵户部良弼官署西园同郑山人中伯醉赋四首 其二","f":"五言律诗","c":["要识为农苦，官园半亩禾。","有才知计远，无事阅书多。","童子琴樽待，山人杖屡过。","长吟见幽意，独鸟下庭柯。"]},{"t":"薄暮赵户部良弼官署西园同郑山人中伯醉赋四首 其三","f":"五言律诗","c":["园中有亭沼，宦邸得幽栖。","曲折由人胜，深沉使客迷。","竹枝风外袅，莲叶雨中低。","我欲尽奇绝，明朝还杖藜。"]},{"t":"薄暮赵户部良弼官署西园同郑山人中伯醉赋四首 其四","f":"五言律诗","c":["骚雅成幽赏，相依古树丛。","未论金谷胜，真与漆园同。","宦迹风云转，王程关塞通。","随君秋夜梦，乘月过辽东。"]},{"t":"暮秋集小山王孙第分得新字","f":"五言律诗","c":["悲秋仍兔苑，华发几茎新。","黄菊频催老，青山久待人。","交情且樽俎，世事各风尘。","醉别王孙去，天涯草自春。"]},{"t":"送范中丞尧卿镇赣州 其一","f":"五言律诗","c":["朔雁催行色，江天入望遥。","旌飞秋草岸，船压夕阳潮。","有赋思梁宴，虚心听楚谣。","霜威及岭外，千里瘴烟消。"]},{"t":"送范中丞尧卿镇赣州 其二","f":"五言律诗","c":["九月虔州去，天南宿雾开。","扬帆生远思，秉钺见雄才。","地转三吴尽，山连百粤回。","夜深瞻北斗，独上郁孤台。"]},{"t":"题山水图 其一","f":"五言律诗","c":["川原人不到，尽日草亭閒。","秋晚树摇落，天高云往还。","沙边多白鸟，湖上一青山。","榜子复何处，暝投红蓼湾。"]},{"t":"题山水图 其二","f":"五言律诗","c":["石树重阴合，郊亭远色分。","泉飞半空雨，江落数峰云。","幽兴自深坐，长歌谁更闻。","申生今白首，无意待玄纁。"]},{"t":"寄南都毛明府正之","f":"五言律诗","c":["久宰南都邑，乌台空荐书。","讵知人事巧，翻使宦情疏。","梅雪清相映，山云澹自如。","大江春水发，应有北来鱼。"]},{"t":"洛阳怀古","f":"五言律诗","c":["百战龙蛇定，中原旧帝居。","邙山谁酹酒，落日自停车。","汉室浮云过，周京乱草馀。","即今苏季子，秪合老田庐。"]},{"t":"宿少林寺同莫陈二秀才","f":"五言律诗","c":["萝径通深处，苍然峭壁重。","吟成太室雨，坐久少林钟。","习静聊今夜，探奇复几峰。","还期共禅榻，莫负岁寒松。"]},{"t":"达摩洞","f":"五言律诗","c":["长江折芦后，面壁此高岑。","祗树抱岩古，法云垂洞深。","石存一片影，天印万年心。","徒使登攀客，松风听梵音。"]},{"t":"张德徵汴中见访仆已过杞两不相值","f":"五言律诗","c":["相寻非预期，乘兴我何迟。","两地琴樽夜，同怀风雨时。","苦吟灯自对，良晤梦先知。","好共碧筒饮，荷花杳满池。"]},{"t":"答沈禹文见寄","f":"五言律诗","c":["未息吴中战，宁闻燕市歌。","一官身事重，长夜国忧多。","古道淹骐骥，秋山老薜萝。","趋朝成百感，风色动鸣珂。"]},{"t":"送吴逸人汝震归甬东","f":"五言律诗","c":["有客叹无鱼，河亭送别初。","马归梁园路，兵阻越乡书。","野岸沧波转，霜天赤叶疏。","世情堪一醉，还定海门居。"]},{"t":"静公园借居","f":"五言律诗","c":["欲览匡庐胜，衰年惜未能。","栖迟无俗侣，幽寂共邻僧。","禅定阶前石，心空夜半灯。","浮图著灵异，昨上最高层。"]},{"t":"维扬兵后寄张佥宪士直","f":"五言律诗","c":["羽书飞不绝，东望海天遥。","旗杂广陵树，兵喧扬子潮。","材官曾几战，壮士莫轻招。","独立多悲感，江城飒晚飙。"]},{"t":"寄豫章周子乾","f":"五言律诗","c":["解官君独早，南北募兵年。","烽火端㞐外，云霞高枕边。","放歌行野寺，垂钓坐江船。","剩有閒园地，开池种白莲。"]},{"t":"寄陆太守子部","f":"五言律诗","c":["目极九江水，谁传双鲤鱼。","城当吴楚地，天逼斗牛区。","怀古云西驻，求贤榻左虚。","郡齐梅正发，岁晚意何如。"]},{"t":"送黄隐君南归","f":"五言律诗","c":["黄生久不见，一见即言归。","落叶世情薄，浮云生事微。","潮声随晚棹，江色照寒衣。","还醉莆中酒，春风自掩扉。"]},{"t":"哀江南八首 其一","f":"五言律诗","c":["为说江南胜，豪华异往年。","波涛扬子夕，风雨秣陵天。","岁苦兵间赋，春荒战后田。","都门迟飞挽，何处泊吴船。"]},{"t":"哀江南八首 其二","f":"五言律诗","c":["昆明未习战，南伐转忧深。","兵气连瓜步，人烟断柘林。","吴姬穷海泪，燕将故关心。","何日铙歌转，苍生望捷音。"]},{"t":"哀江南八首 其三","f":"五言律诗","c":["战马嘶江上，寒生枫树村。","新兵五都尽，旧业几家存。","共倚中朝盛，谁将上策论。","梁鸿避世者，宁复老吴门。"]},{"t":"哀江南八首 其四","f":"五言律诗","c":["召募今南讨，中原羽檄过。","几年纡策定，一战赏功多。","雾变青山色，天横沧海波。","飘零国士老，长望一悲歌。"]},{"t":"哀江南八首 其五","f":"五言律诗","c":["华亭未奏捷，烽火更西湖。","海舰贼来去，天兵功有无。","人心多为汉，国计竟全吴。","野哭徵求尽，苍茫寒月孤。"]},{"t":"哀江南八首 其六","f":"五言律诗","c":["古来兵不到，湖里洞庭山。","日惨干戈际，云愁猿鸟间。","少年应习武，幽士且栖閒。","纵熟黄柑酒，谁能长醉颜。"]},{"t":"哀江南八首 其七","f":"五言律诗","c":["江山天设险，满目战图秋。","东海兵停棹，西风客倚楼。","朝廷存大体，斧钺系深忧。","不信征南将，功成早白头。"]},{"t":"哀江南八首 其八","f":"五言律诗","c":["氛祲频年动，东南尽处看。","海摇千舰出，兵犯七闽寒。","杀伐宁无定，凭陵信有端。","遥闻日本使，犹自贡长安。"]},{"t":"过清源故居有感 其一","f":"五言律诗","c":["旧业成暌远，亲朋久失群。","百年生长地，一片往来云。","独立空流水，长吟但落曛。","结茅何日定，西陇事耕耘。"]},{"t":"过清源故居有感 其二","f":"五言律诗","c":["飘零三十春，下马问比邻。","相见弟兄老，堪嗟门巷新。","行踪犹泛梗，世故一浮尘。","王谢豪华地，殊非旧主人。"]},{"t":"赠别史郎中应之还张秋 其一","f":"五言律诗","c":["一见遽言别，其如南北情。","君今何水部，吾岂谢宣城。","帆影树中出，河流天际平。","谁无感怀赋，两地共秋声。"]},{"t":"赠别史郎中应之还张秋 其二","f":"五言律诗","c":["安平南去道，官署在河浔。","一水风烟色，三秋鱼鸟心。","才高君柱石，计拙我山林。","应念离居者，虫鸣蔓草深。"]},{"t":"谢刘监察质卿见寄","f":"五言律诗","c":["清霜肃海岱，春到野夫边。","骢马劳今日，苍生望有年。","旧交仍杖屦，遐思各云天。","为问齐中俗，何人似鲁连。"]},{"t":"九日方晦叔同登北城楼兼示真上人二首 其一","f":"五言律诗","c":["相期赋九日，倚堞兴何饶。","天若来风雨，人应感寂寥。","长河明远色，寒柳净疏条。","更爱东林胜，谈禅坐此宵。"]},{"t":"九日方晦叔同登北城楼兼示真上人二首 其二","f":"五言律诗","c":["登高有惠远，揽胜即庐山。","幽事知谁重，浮生得此间。","乾坤惟旧侣，霜露各衰颜。","莫待黄花老，明朝更一攀。"]},{"t":"重九夜吴希实隐君馆陪饯君搢诗人 其一","f":"五言律诗","c":["开樽当节序，归思莫匆匆。","秋色犹南菊，寒声自北鸿。","几人心迹定，万事古今同。","旷达真吾辈，何如栗里翁。"]},{"t":"重九夜吴希实隐君馆陪饯君搢诗人 其二","f":"古风","c":["茱萸共把玩，聚散复何愁。","秉烛重阳过，移樽片月留。","我?同调侣，君醉异乡秋。","别后多诗兴，还登何处楼。"]},{"t":"酬翁子书见示新作","f":"五言律诗","c":["病馀秋思动，对月几吴吟。","江上多莼菜，山中有橘林。","感因为客久，情岂在交深。","安得共耕凿，相期松柏心。"]},{"t":"暮秋柬徐别驾载卿","f":"五言律诗","c":["南征秋转剧，不寐夜漫漫。","白发艰虞尽，沧洲去住难。","旌旗连夜暗，兵甲照江寒。","选将须臾事，谁能议筑坛。"]},{"t":"寄塞上路监察子中","f":"五言律诗","c":["沙漠动霜威，巡行久未归。","眼中求将略，意外得边机。","日落马南顾，天寒雕北飞。","莫令诸侠少，争猎向金微。"]},{"t":"暮秋闻倭寇稍平寄上南都大宗伯孙公兼怀太史文和二首 其一","f":"五言律诗","c":["才罢江南战，凭高动越吟。","涛声翻日暮，兵气结秋阴。","听履青天远，含香紫雾深。","世传修汉史，谁识二班心。"]},{"t":"暮秋闻倭寇稍平寄上南都大宗伯孙公兼怀太史文和二首 其二","f":"五言律诗","c":["省中霜叶下，百感向斜晖。","北饷多留滞，南征几是非。","寸丹经国远，尺素到家稀。","共拟孙弘阁，无劳说布衣。"]},{"t":"老怀","f":"五言律诗","c":["残年百事过，阅世复何言。","多病仍春草，全家岂故园。","游丝风不定，乱雀日相喧。","我欲从丹侣，青山静掩门。"]},{"t":"送许殿卿守建宁","f":"五言律诗","c":["移官君独远，惆怅撤离筵。","山转荆南路，江浮蜀外天。","自能归异俗，几为问荒田。","到日梅花发，春生五马前。"]},{"t":"赠卢次楩 其一","f":"五言律诗","c":["五年君一到，未是曳裾频。","晓发黎阳骑，宵探漳浦春。","交游魏公子，怀抱楚骚人。","好觅沧洲侣，相将采绿蘋。"]},{"t":"赠卢次楩 其二","f":"五言律诗","c":["谁识丰城剑，天空紫气高。","老来悲道路，醉后益风骚。","物议冰霜过，才名岁月劳。","一寒今范叔，谁复赠绨袍。"]},{"t":"赠卢次楩 其三","f":"五言律诗","c":["五十君多感，艰危不可忘。","自知兄弟少，宁为鹡鸰伤。","汉党无文字，燕歌独醉狂。","莫违湖海兴，徒自老黎阳。"]},{"t":"哭弟松 其一","f":"五言律诗","c":["多病吾仍在，沉酣尔遽休。","相依堪共老，永别杳难求。","伏腊还新酒，风烟岂故丘。","漳河暮转急，呜咽正东流。"]},{"t":"哭弟松 其二","f":"五言律诗","c":["吾弟忽长往，孤魂应向东。","在家忧患过，为客去留同。","白日身何懒，清樽老不空。","至今城北路，陇树起悲风。"]},{"t":"寄怀徐以言","f":"五言律诗","c":["罢官还旧业，应起著书楼。","海鹤当庭下，溪云拂槛流。","独醒风雨后，高卧甲兵秋。","况有东山胜，堪追谢傅游。"]},{"t":"寄李佥宪师孟","f":"五言律诗","c":["楚客限王程，春风游宦情。","山连吴地阔，天与浙中平。","烽燧劳东望，干戈甚北征。","莫教终孺子，独为请长缨。"]},{"t":"刘侍御叔清擢守扶风赋此寄赠","f":"五言律诗","c":["旌节发河阳，君行西路长。","心悬陇上月，威带日南霜。","入郡春随马，谈兵秋满堂。","于今汲长孺，易使鬓毛苍。"]},{"t":"王元美镇青山赋此寄怀","f":"五言律诗","c":["当年客燕市，官舍每经过。","促膝寒灯尽，论心夜雨多。","别来成老病，愁里问干戈。","北海开樽日，何人共醉歌。"]},{"t":"秋日柬方晦叔两江","f":"五言律诗","c":["端居何思远，名士亦心劳。","巨笔凌班史，秋怀得楚骚。","窗虚清桂露，庭迥急松涛。","诗草人争写，三齐纸价高。"]},{"t":"寓居禅院申明府幼川携酒过夜","f":"五言律诗","c":["禅扉夜尚开，何意冒寒来。","好客无馀俸，为官不尽才。","冰花明古树，烛影动春杯。","落尽孤城月，乘酣车马回。"]},{"t":"吴人郑速季入邺省兄中伯每谈倭寇之乱久而思归赋此以赠三首 其一","f":"五言律诗","c":["驱马来河朔，云愁故国赊。","干戈身是赘，道路酒为家。","海戍多归雁，江城几落花。","白头弟兄在，急难复何嗟。"]},{"t":"吴人郑速季入邺省兄中伯每谈倭寇之乱久而思归赋此以赠三首 其二","f":"五言律诗","c":["江南兵未息，朝野共忧端。","战伐疲吴税，功名老汉官。","天空山雾惨，地坼海涛寒。","妻子书难达，华亭梦里看。"]},{"t":"吴人郑速季入邺省兄中伯每谈倭寇之乱久而思归赋此以赠三首 其三","f":"五言律诗","c":["我惜吴门客，言归动是哀。","形容愁里变，离乱死中来。","家远身犹滞，田荒赋几催。","时清渡江去，长啸虎丘台。"]},{"t":"涌金亭同冀定甫马伯龄醉赋","f":"五言律诗","c":["百泉声不断，风雨乱沧波。","地接烟岚迥，天开灵秀多。","古人馀胜事，今代有狂歌。","为爱苏门好，携樽共一过。"]},{"t":"寓晁太史湖亭王乐三见过同酌","f":"五言律诗","c":["子猷吾旧好，乘兴过林扉。","席外沧波近，歌边白鸟归。","浦烟开霁色，松日转春辉。","学士呼新酒，宁教幽事迟。"]},{"t":"赠别","f":"五言律诗","c":["北上千秋箓，西归万里桥。","黄花空有约，绿酒不同宵。","树拥秦云断，山悬蜀栈遥。","艰难杜老在，莫谩简书招。"]},{"t":"楼居秋夜","f":"五言律诗","c":["短筇不到地，老子爱楼居。","徙绮常科发，疏慵肯著书。","窗高生月早，檐迥接天虚。","万户灯明灭，秋光澹自如。"]},{"t":"寄李员外秀夫","f":"五言律诗","c":["久别谁先老，西风两地心。","海天来朔雁，关月起秋砧。","性懒交游少，才高感慨深。","遥怜松桂色，寂寞华山阴。"]},{"t":"卧病张肖甫枉顾时奉使还蜀","f":"五言律诗","c":["蜀客来千里，相看慰病颜。","心驰消息后，义重死生间。","飞梦通秦塞，缄书度汉关。","登高不同赋，秋色满河山。"]},{"t":"枕上病怀赠陆道函兼谢枉驾","f":"五言律诗","c":["卧病劳相问，茫然意答迟。","科头何气色，拊背独心知。","地湿霜凝草，庭喧雀满枝。","君看燕赵俗，豪士岂长悲。"]},{"t":"秋夜奇上人禅房独坐","f":"五言律诗","c":["久寄青莲宇，因之问上乘。","自知閒有味，不愧老无能。","响彻秋风树，寒生夜雨灯。","匡床坐幽寂，身似定中僧。"]},{"t":"送吴君搢归新安二首 其一","f":"五言律诗","c":["燕赵久为客，乘秋鸣棹还。","独吟霜月晓，几转荻芦湾。","朔雁惊心后，江城屈指间。","奇峰三十六，天际识黄山。"]},{"t":"送吴君搢归新安二首 其二","f":"五言律诗","c":["故国多形胜，青山拥万重。","溪南岁暮雪，石上古时松。","留客呼新酒，敲棋度暝钟。","春来觅诗处，谁系野云踪。"]},{"t":"有怀","f":"五言律诗","c":["秋风起邺城，重我故园情。","林壑居难定，渔樵计未成。","野云随浪迹，村酒脱浮名。","欲赋多忧思，何如阮步兵。"]},{"t":"寄怀王子梁镇鄜州","f":"五言律诗","c":["君乘旧骢马，西望渺黄河。","春色关中满，霜威塞上多。","宦情逢羽檄，世事起商歌。","独夜耿无寐，星光摇太阿。"]},{"t":"中秋无月","f":"五言律诗","c":["连宵雨太急，仙桂失清芬。","四野明秋水，孤城乱暮云。","阴晴何处定，悲乐此时分。","不见山河影，笙歌空自闻。"]},{"t":"冬夜范宪伯尧卿宅同许宪副子春得天字","f":"五言律诗","c":["宦情与客思，岁暮共悠然。","云暗春前树，山明雪后天。","浮沉惟短褐，聚散几芳筵。","莫惜今宵醉，相期动隔年。"]},{"t":"谢子明别业对酌","f":"五言律诗","c":["背郭茅亭子，联镳薄暮来。","田夫扫径罢，庭雀出墙回。","地僻隐狐兔，园荒迷草莱。","主人久不到，黄菊向谁开。"]},{"t":"可叹","f":"五言律诗","c":["世事底相迫，人间谁独醒。","行歌仍白石，把阅且黄庭。","山迥云时出，天高霜夜零。","菉葹无久色，松柏向人青。"]},{"t":"久客","f":"五言律诗","c":["为客不知久，同怀相见频。","河山偏入赋，风俗更留人。","镜里双愁鬓，灯前一病身。","菊花零露满，秋色几枝新。"]},{"t":"过故居留别王南村先生","f":"五言律诗","c":["尔居吾旧业，吾弟久相依。","往事今谁好，浮生会自稀。","河亭聊别酒，桑梓共斜晖。","百感愿常健，终心殊不违。"]},{"t":"苦雨后感怀","f":"五言律诗","c":["苦雨万家愁，宁言客滞留。","蛙鸣池水夕，蝶恋菜花秋。","天地惟孤馆，寒暄一敝裘。","须臾古今事，何必叹蜉蝣。"]},{"t":"嘉靖癸卯岁曾寓道院屡登玉清阁以发吟兴于今二十七年矣衰颓且病竟不获一登漫成小诗以志感叹云尔","f":"五言律诗","c":["几欲登仙阁，年来筋力衰。","山青不在眼，云白更依谁。","碧海三山梦，瑶台万里期。","老夫仍世累，且报木公知。"]},{"t":"孟县道中 其一","f":"五言律诗","c":["村家农事毕，积雨漫成河。","白聚野凫净，红垂秋柿多。","年衰仍浪迹，转调是劳歌。","一诵鹪鹩赋，归欤向薜萝。"]},{"t":"孟县道中 其二","f":"五言律诗","c":["去去已言倦，秋天菊正花。","阴晴客在路，南北雁为家。","薄俗身难定，浮生鬓易华。","仙人不可见，何处问丹砂。"]},{"t":"夜雨徐明府子研枉驾旅寓","f":"五言律诗","c":["冒雨一乘兴，仆夫应畏难。","交从今夕定，情自故乡看。","城迥钟相隔，槐疏鸟共寒。","携樽慰旅况，冯铗不须弹。"]},{"t":"暮秋夜集刘兵宪子礼宅赋得秋多二字 其一","f":"五言律诗","c":["离合半生梦，招呼三径游。","邺中惟病客，洛下几名流。","石润苔含雨，庭閒菊占秋。","还怜竹西月，移席整觥筹。"]},{"t":"暮秋夜集刘兵宪子礼宅赋得秋多二字 其二","f":"五言律诗","c":["堂上琴樽设，门前杖屦过。","垒山成地秀，种菊得秋多。","佳会偏倾倒，馀生几啸歌。","相期共幽事，城市有烟萝。"]},{"t":"暮秋夜雨同温纯甫方敏之集吕子性书斋对菊","f":"五言律诗","c":["席畔幽芳合，相留客尽欢。","天将雨色暝，夜使菊花寒。","取醉飞觞促，题诗剪烛看。","晴明复何处，摇落感秋残。"]},{"t":"同鲍叔愚邓廷献二明府同观太乙泉流觞","f":"五言律诗","c":["灵源喷薄处，并驾远看来。","野鸟夕争下，山花寒自开。","流觞几曲水，倚杖半岩苔。","秋兴能同赋，谁齐潘岳才。"]},{"t":"山县久雨感怀","f":"五言律诗","c":["云惨失峰峦，林深鸟自安。","山城七日雨，客舍九秋寒。","绿酒愁边尽，黄花醉后看。","痴儿问行路，不道仆夫难。"]},{"t":"谢仲川雪中见过时予未起","f":"五言律诗","c":["高枕奚童报，知君冒雪来。","阴晴门外变，骚雅卧中裁。","寒色侵衣湿，冰花著树开。","于今谁有赋，方见谢家才。"]},{"t":"初秋同刘兵宪叔清游五龙山值雨得天字","f":"五言律诗","c":["飞旌向何许，深入万松烟。","草湿云边径，山昏雨外天。","兴高穷胜迹，政美见丰年。","谁识君侯意，临风一慨然。"]},{"t":"次沈王殿下秋夜小酌之韵","f":"五言律诗","c":["为爱云山色，凭高望几回。","孤吟方露下，百感复秋来。","夜爽风鸣树，天清月在杯。","共言今子建，八斗不凡才。"]},{"t":"过西池书斋赏菊","f":"五言律诗","c":["培养邻三径，移来殿万芳。","馀花自风景，幽意合柴桑。","绣幕驻秋色，金杯浮晚香。","主人益多珍，讵敢傲飞霜。"]},{"t":"敬轩诚轩携酒见过西岩西池同赋","f":"五言律诗","c":["日落寒城闭，天空倦鸟归。","高楼才暝色，新月亦清辉。","秋兴骚人赋，乡心客子衣。","王门岂无事，载酒过玄晖。"]},{"t":"冬夜过云洲翁留酌因赴西池君不果","f":"五言律诗","c":["眼前期不定，万事远期难。","酒熟山人过，诗成蜡炬残。","柝声连巷动，月色满城寒。","岁晚梅花发，谁同雪里看。"]},{"t":"同程太守子晋过昭觉禅院","f":"五言律诗","c":["使君重惠远，频往兴逾高。","共欲参禅妙，何心索句劳。","霜明分夜色，松响乱寒涛。","更话睢中事，忧端在二毛。"]},{"t":"十六夜同南庵翁游昭觉禅院醉笔漫书","f":"五言律诗","c":["客子来金界，王孙驻玉鞍。","春通九衢夕，风闪万灯寒。","改席钟声度，当杯月影团。","明年旷颜色，胜景忆同看。"]},{"t":"夜过达轩同仁轩分得清字","f":"五言律诗","c":["幽斋几剪烛，相与话深更。","户牖敞虚白，星河悬太清。","悲歌燕侠志，醒醉楚骚情。","当代能多赋，应齐勒鼎名。"]},{"t":"谢敏轩惠酒","f":"五言律诗","c":["太行三晋路，留滞几书还。","亭馆仍春雪，云霞岂故山。","客愁醒醉里，腊味有无间。","何限王门酒，能滋衰老颜。"]},{"t":"柬栗别驾道甫","f":"五言律诗","c":["曾赋南阳胜，登临诸葛庐。","宦情归旧业，老计著何书。","高枕浮云过，孤樽落月虚。","帝京多故侣，谁复问閒居。"]},{"t":"雨中过昭觉禅院同云洲丈敬诚二君赋得多字","f":"五言律诗","c":["不辞冒风雨，地胜此经过。","径滑人留迹，林寒鸟在柯。","疏狂缘醉甚，老病得閒多。","更欲寻禅侣，青山共薜萝。"]},{"t":"柬南泉君园居","f":"五言律诗","c":["几日违禅宇，遥闻钟磬音。","谁同赋诗兴，自定奕棋心。","雨歇亭台爽，烟含花竹深。","眼前幽意足，清旷亦山林。"]},{"t":"暮雨有感","f":"五言律诗","c":["西来一片雨，遽作万家秋。","寒逼今宵梦，声牵故国愁。","城高断钟响，野旷溢河流。","秉烛贵公子，仍耽金谷游。"]},{"t":"园亭月下观妓分得戡字","f":"五言律诗","c":["月白池台迥，徵歌客共酣。","名花出山右，春色似江南。","漏转仍呼酒，参横尚驻骖。","重来赏音处，感旧对何戡。"]},{"t":"过诚轩君赋得登楼对月得河字","f":"五言律诗","c":["楼高仍绮席，月朗亦金波。","垂老酒杯倦，先秋诗兴多。","柝声空巷陌，池影截天河。","今日频相接，宁忘最后过。"]},{"t":"骤雨柬西岩君","f":"五言律诗","c":["隔院共风雨，谁家秋意多。","檐前走霹雳，门外散江河。","留滞人扶杖，凄凉鸟在柯。","应思折简夜，乘月几经过。"]},{"t":"栗仁甫园亭饯别得天字","f":"五言律诗","c":["偶过设芳筵，相留花竹边。","离声楚词赋，行纪晋山川。","马识往来道，云通南北天。","忆君池上月，应负几回圆。"]},{"t":"寄李学宪于鳞","f":"五言律诗","c":["西尽三秦胜，拂衣归故林。","搜诗惨淡色，远世寂寥心。","坐想古人在，行看秋草深。","千年白雪调，谁和郢中音。"]},{"t":"寄王苏州","f":"五言律诗","c":["岳牧今逾重，忧端坐永宵。","岁侵疲郡邑，时议到渔樵。","云暗青山路，江喧白日潮。","伤心兵火后，几度望枫桥。"]},{"t":"武安除夕酌王抑之宅其子易从易知侍侧","f":"五言律诗","c":["旅况乘时切，年华隔夜新。","捧觞君二子，弹铗我孤身。","地得青山赋，天留白发人。","谁为岁寒侣，松老见龙鳞。"]},{"t":"送程子仁之楚","f":"五言律诗","c":["十日九弹铗，留君竟此行。","乡心急岁杪，客计缓平生。","雪暗梁园树，江空鄂渚城。","不闻王粲赋，愁绝滞南荆。"]},{"t":"寄上赵王枕易殿下","f":"五言律诗","c":["松桂兔园秋，谁从帝子游。","清风闻玉笛，夜月见琼楼。","旅雁复南下，官河长北流。","应怀谢庄赋，吾意老沧洲。"]},{"t":"寄崔岱屏都尉","f":"五言律诗","c":["望望三秋雁，谁传上国书。","气横龙剑外，天远凤箫馀。","岁月身还健，风云计自疏。","琼筵多胜事，词客复何如。"]},{"t":"关山月","f":"五言律诗","c":["皎皎长空月，星河半有无。","光连玉关静，寒傍雪山孤。","沙雁时悽断，林猿夜啸呼。","征人增百感，把剑立平芜。"]},{"t":"明妃词","f":"五言律诗","c":["凤阙虚归梦，龙城重远愁。","黄沙连塞起，黑水入荒流。","泪尽琵琶夜，魂消觱篥秋。","谁怜万里外，风雪满貂裘。"]},{"t":"白鼻騧","f":"五言律诗","c":["年少耽游侠，长乘白鼻騧。","连翩金勒响，婀娜玉鞭斜。","紫陌嘶芳草，青门踏落花。","鸣弓飞鸟堕，巧捷万人誇。"]},{"t":"春闺词","f":"五言律诗","c":["杨柳正啼莺，杨花飞满城。","春风天外去，落日海西明。","逸气摇金辔，豪华恋玉京。","不知游荡子，曾念百年情。"]},{"t":"晚过李子复饯别","f":"五言律诗","c":["携樽同此夕，云月有无间。","旷达骚人意，凄凉游子颜。","乱虫依草树，孤鸟度河山。","世路黄金尽，秋风一剑还。"]},{"t":"寄怀苏廷圭先生","f":"五言律诗","c":["勾漏辞官早，丹砂不易成。","门閒二水合，天远一鸿轻。","为客幽期过，悲秋白发生。","菊花谁共采，风雨独含情。"]},{"t":"同朱道士通上人夜谈因送予归赋此","f":"五言律诗","c":["二高多道气，乘夜访幽栖。","瑶草元无种，青莲不染泥。","鹤閒丹鼎外，月在法云西。","相送还成笑，分明过虎溪。"]},{"t":"清明过王郎中学甫时园桃始花留酌","f":"五言律诗","c":["欲访桃源去，先看独树春。","无言当令节，有色净风尘。","不取倾壶醉，其如满眼新。","仙郎能下榻，华月复留人。"]},{"t":"送唐仪部还琼州","f":"五言律诗","c":["多病言归去，孤舟秪素琴。","海天南尽处，燕阙北来心。","秋老下榕叶，沙寒鸣翠禽。","赋成应有寄，惆怅岭云深。"]},{"t":"浪游","f":"五言律诗","c":["百岁形骸役，吾生何浪游。","寒蛩知静夜，老菊见高秋。","海上白茅屋，云边青石丘。","还从物外侣，灵药好相求。"]},{"t":"送张太仆熙伯视马畿内","f":"五言律诗","c":["司驭巡畿甸，飞旌指戍楼。","共传天马异，宁复大宛求。","月照昆吾冷，风生苜蓿秋。","张衡有词赋，独系汉家忧。"]},{"t":"秋夜柬仲元仁","f":"五言律诗","c":["永夜愁欹枕，天涯一病夫。","候虫当砌乱，秋月傍楼孤。","采菊还三径，扬帆更五湖。","相将好归去，莫叹岁华徂。"]},{"t":"李行人元树宅同谢张二内翰话洞庭湖 其一","f":"五言律诗","c":["词客家何处，西南是岳州。","地连湘树阔，湖共楚天浮。","极目风烟夕，惊心鸿雁秋。","君山更奇绝，应待子长游。"]},{"t":"李行人元树宅同谢张二内翰话洞庭湖 其二","f":"五言律诗","c":["南望岳阳郡，苍茫吴楚分。","帆回孤岛树，楼出九江云。","落日浪中没，秋风天外闻。","何时采蘋藻，湖上吊湘君。"]},{"t":"送朱邦宪还上海","f":"五言律诗","c":["送君不可住，霜露满幽襟。","醉后登楼赋，天涯抱玉心。","江门开晓色，海树带秋阴。","归去鹤亭上，遥听吴会吟。"]},{"t":"居庸关二首 其一","f":"五言律诗","c":["遥遥度关塞，策马正西风。","驿路泉声里，人家岚气中。","霜馀涧草歇，日上石林空。","多少长征客，高秋感塞鸿。"]},{"t":"春夜过王侍御子梁宅时将按河南得韵二首 其一","f":"五言律诗","c":["乌栖官舍静，步屧偶经过。","宿雾浮金阙，春星动玉河。","交情别后重，逸气醉来多。","好去梁园道，因风寄薜萝。"]},{"t":"春夜过王侍御子梁宅时将按河南得韵二首 其二","f":"五言律诗","c":["送君向河岳，归思渺难堪。","回首鸿初北，当歌月正南。","宫云飘祖席，御柳驻征骖。","去后听黄鸟，芳菲谁共探。"]},{"t":"春日","f":"五言律诗","c":["共道芳春好，其如老病侵。","谁同一樽酒，时醉百花阴。","应接非吾事，疏狂见客心。","因思故山侣，怅望白云深。"]},{"t":"送赵元哲下第归东阿","f":"五言律诗","c":["久客山中梦，孤怀月下歌。","青云期赋就，华发感时过。","龙剑閒星斗，鱼山静薜萝。","东归访黄石，吾道欲如何。"]},{"t":"陈驾部钖卿来自钱塘舟次临清适有汀州之命贻书见怀用答 其一","f":"五言律诗","c":["海门春水发，吴舫到何迟。","芳草行吟处，孤鸿入望时。","沧江成远别，白首见相知。","欲赋三山胜，茫茫不可期。"]},{"t":"陈驾部钖卿来自钱塘舟次临清适有汀州之命贻书见怀用答 其二","f":"五言律诗","c":["往年君别处，梧叶正秋彫。","犹忆琴樽约，曾同风雨宵。","寒空鸣雁急，烟浦去帆遥。","犹有天南梦，相随度海潮。"]},{"t":"陈驾部钖卿来自钱塘舟次临清适有汀州之命贻书见怀用答 其三","f":"五言律诗","c":["使君遥领部，相对复何年。","海树晓行外，江蓠秋思边。","城临百越地，帆尽七闽天。","见说春风早，梅花可更传。"]},{"t":"陈驾部钖卿来自钱塘舟次临清适有汀州之命贻书见怀用答 其四","f":"五言律诗","c":["春酒不同醉，春花空复开。","美人临卫水，客子滞燕台。","近得铜章报，翻令锦缆回。","天知有黄霸，早遣渡江来。"]},{"t":"端午集吴郎中峻伯宅得山字","f":"五言律诗","c":["令节方牢落，招携慰旅颜。","綵丝忆儿女，蒲酒话乡关。","楚俗千年后，燕歌一醉间。","坐看新月色，犹自傍西山。"]},{"t":"夏夜集孙员外文揆宅得天字","f":"五言律诗","c":["深夜移官烛，清风敞客筵。","钟沉汉苑树，月度蓟门天。","我愧谢庄赋，人称孙楚贤。","何当碧筒饮，醉向北窗眠。"]},{"t":"送赵少尹文甫之华阴","f":"五言律诗","c":["燕市离歌动，殊非故国闻。","清樽聊共我，黄发更怜君。","县隐潼关树，堂流华岳云。","不知松月下，谁与坐宵分。"]},{"t":"夜坐","f":"五言律诗","c":["兵气动严关，才闻漠骑还。","边愁醒醉里，身事去留间。","乱响更深柝，空明雪后山。","苦吟时倚杖，不使客心閒。"]},{"t":"东桥为胡太仆赋","f":"五言律诗","c":["西来倚杖处，下有白鸥群。","偶尔乘秋兴，翻然向夕曛。","溪光自清彻，野色两平分。","不定中流影，相知有片云。"]},{"t":"将登五台夜宿圭峰禅房","f":"五言律诗","c":["驱车林壑晚，不觉路萦回。","钟响禅扉近，僧迎山火来。","登攀惟一径，开辟自多台。","上有古松柏，当年谁为栽。"]},{"t":"圭峰晚望","f":"五言律诗","c":["圭峰冠形胜，幽事且禅林。","石阁参云兴，山桥俯涧心。","万松皆古色，孤磬自清音。","更觅最奇处，宁辞冰雪深。"]},{"t":"山行有感","f":"五言律诗","c":["地僻逢人少，同行自有群。","几多山脊雪，一片马头云。","古木参天出，寒鸦薄暮闻。","可怜春草发，谁为采幽芬。"]},{"t":"偶成","f":"五言律诗","c":["乡园尚隔越，寒暑又经过。","晚计身无补，新交事转多。","閒时自天地，静处即烟萝。","白鸟忽飞去，悠然一浩歌。"]},{"t":"留别陈大参粹中二首 其一","f":"五言律诗","c":["征骖闻早发，客自塞门归。","天暝乌栖树，城寒雪拥扉。","美人仍两地，春梦不相违。","独赋关山月，茫茫共素辉。"]},{"t":"留别陈大参粹中二首 其二","f":"五言律诗","c":["别后缄书少，天骄数往还。","正忧烽火急，翻羡草茅閒。","积雪犹平涧，残阳半在山。","相逢春尚浅，杨柳未堪攀。"]},{"t":"寄太和山何隐君二首 其一","f":"五言律诗","c":["弃官依白岳，岁月此栖迟。","道侣频相过，丹经久自知。","心閒虎啸处，步缓鹤随时。","倚杖看晴色，前峰又采芝。"]},{"t":"寄太和山何隐君二首 其二","f":"五言律诗","c":["太乙坛前客，桃花十度红。","幽栖片石定，元气四时通。","古树邻苍壑，閒云澹碧空。","能谈非静者，真意几人同。"]},{"t":"雨后立夏","f":"五言律诗","c":["园中绿已暗，寂寞问花神。","兴托清樽酒，愁欺白发人。","山城初雨过，天地尚馀春。","又与东风别，堪嗟羁族身。"]},{"t":"送薛逸人归荆南","f":"五言律诗","c":["河汾春色过，此别路三千。","旅梦关山月，乡心风雨天。","马归湘竹外，城对楚江边。","去住何须叹，荆王自下贤。"]},{"t":"寄徐水部有和","f":"五言律诗","c":["粉署当形胜，虚怀谁似君。","树凉沙市雨，江白渚宫云。","鹳鹤翩翩下，帆樯历历分。","楚童能艳曲，不使水曹闻。"]},{"t":"北园同孔老赋得风字","f":"五言律诗","c":["悠然云在空，此意许谁同。","身出勋名外，心归恬澹中。","高楼偏夕照，深竹自凉风。","试问今秋兴，还添菊几丛。"]},{"t":"夜雨","f":"五言律诗","c":["夜来殊不寐，百感古今情。","道在楚骚重，年衰燕侠轻。","轩庭回爽气，风雨失残更。","多少人欹枕，中心别有营。"]},{"t":"宋伯镇招饮署中赋得长字","f":"五言律诗","c":["绿草夹阶长，凭轩共晚凉。","鸟声投暝树，霞影蘸清觞。","兴剧三秋赋，年衰几日狂。","今宵话离合，风露满衣裳。"]},{"t":"雨后早起","f":"五言律诗","c":["积雨空阶满，开轩幽兴深。","半窗低晓月，几处苦秋阴。","已倦人间路，能閒诗外心。","还憎多此癖，习静老山林。"]},{"t":"积雨感怀","f":"五言律诗","c":["十月天多雨，霏霏日夜寒。","西山改气色，北斗失阑干。","生计门常掩，悲歌灯又残。","可怜黄菊老，几向病中看。"]},{"t":"初冬十五夜云洲丈招游东林得僧字","f":"五言律诗","c":["皎皎东林月，初看法镜升。","殿沉中夜磬，松隐上方灯。","兴剧催银斝，诗成转玉绳。","地非庐霍胜，天许著名僧。"]},{"t":"李园暮雪同镇康安庆二王偶成","f":"五言律诗","c":["带雪几归鸟，萧然集旧柯。","树明春意早，庭敞暮寒多。","绿醑同梁苑，清才并郢歌。","还期看山色，天外玉嵯峨。"]},{"t":"冬夜昭觉禅院示万灯上人","f":"五言律诗","c":["旧衲灯前补，天寒霜满庭。","不眠中夜偈，早起半函经。","慧力刬诸障，禅心通百灵。","腊同祗树老，春雨又青青。"]},{"t":"寄怀顾近湖比部","f":"五言律诗","c":["莫测文园志，龙光薄海天。","遥知变化日，稀见老成年。","客路西淹晋，神州北壮燕。","白云楼上赋，秋色满高筵。"]},{"t":"寄顾彭山别驾","f":"五言律诗","c":["建业元佳丽，风流况有君。","妖童隔花唱，醉客倚楼闻。","清忆铜台雪，春怜金谷云。","于今非宦邸，犹试宝刀纹。"]},{"t":"赠田深父","f":"五言律诗","c":["气夺三都赋，声驱六代诗。","春云流碧落，秋月照琼枝。","独览中原胜，还收太华奇。","东山有狂客，千里愧相知。"]},{"t":"西亭中尉雅集","f":"五言律诗","c":["骚侣夜同酌，酣歌风月斜。","古人自风调，今代几名家。","客久鬓将雪，天寒梅正花。","谁知献赋意，对尔一长嗟。"]},{"t":"吹台吊三贤","f":"五言律诗","c":["异代怀三老，风骚尚可亲。","高名相照耀，片石自嶙峋。","野旷青云暮，台空碧草春。","至今遗响在，神鬼泣何人。"]},{"t":"中秋夜潞阳旅馆同冯员外言别得分字","f":"五言律诗","c":["客亭逢此夕，樽酒况同君。","月向中秋满，人从上国分。","绛河斜度影，白雁远呼群。","回首淮阳路，相思隔海云。"]},{"t":"秋日即事五首 其一","f":"五言律诗","c":["八月边烽起，燕关入引弓。","檄飞三辅道，气激五都雄。","戍角寒云外，城乌夜色中。","不知枕戈者，愁绝竟谁功。"]},{"t":"秋日即事五首 其二","f":"五言律诗","c":["燕赵多愁日，兵戈未定时。","交游疏旧社，僮仆问归期。","驿路当秋断，胡笳带月悲。","晓来惊旅鬓，更益镜中丝。"]},{"t":"秋日即事五首 其三","f":"五言律诗","c":["何时偃甲兵，多难滞燕城。","寒馆下桐叶，秋风吹雨声。","贾生今日泪，宋玉昔年情。","共有龙庭策，谁高麟阁名。"]},{"t":"秋日即事五首 其四","f":"五言律诗","c":["旅怀方索寞，秋气重萧森。","兵甲南归梦，妻孥北望心。","闭城山日在，倚剑野云深。","独有长安客，时时问捷音。"]},{"t":"秋日即事五首 其五","f":"五言律诗","c":["叠嶂云仍惨，孤村鸟亦稀。","共嗟经铁马，谁复守柴扉。","战地生寒色，征旗乱夕晖。","还思汉飞将，逐北过金微。"]},{"t":"送吴驾部子有奔丧洛中 其一","f":"五言律诗","c":["漠南惊候火，洛下报哀音。","去去思亲泪，迟迟忧国心。","暮云中岳断，秋雨大河深。","犹忆老莱服，空瞻松柏林。"]},{"t":"送吴驾部子有奔丧洛中 其二","f":"五言律诗","c":["数有趋庭梦，秋来益苦颜。","高原黄叶下，落日素车还。","发变兵戈后，心摧霜露间。","啼乌转凄切，泪尽北邙山。"]},{"t":"对菊","f":"五言律诗","c":["东篱何寂寞，不似去年秋。","菊带凄凉色，人经离乱愁。","风庭寒影动，霜院晚香流。","客里重阳过，悲歌独未休。"]},{"t":"马子端王鼎臣见过因怀崔都尉","f":"五言律诗","c":["兵去人心定，相逢话此生。","乱离俱是客，去住各含情。","沁水沉鸾影，秦台断凤声。","眼中惟二子，且复醉燕城。"]},{"t":"秋夜","f":"五言律诗","c":["不见同怀侣，悠然独夜思。","风凄闻角处，月落倚楼时。","计拙陶潜酒，心忧阮籍诗。","千山芳蕙歇，策杖复何之。"]},{"t":"芳树","f":"五言律诗","c":["芳树花争发，嫣然故向人。","相看终日媚，一摘暂时新。","影落金塘水，香飘玉砌尘。","伤心有琴瑟，寂寞汉宫春。"]},{"t":"邺下秋怀","f":"五言律诗","c":["风尘劳客计，词赋寄乡愁。","雁避燕山雪，人经邺地秋。","几年多放浪，万古自沉浮。","抱膝成孤啸，苍凉月近楼。"]},{"t":"奉和崔后渠祭酒见赠","f":"五言律诗","c":["碧山留大老，客子几番来。","砧杵鸣秋郭，风尘上晚台。","孤怀惟短剑，万事且深杯。","东阁多贤士，宁遗作赋才。"]},{"t":"寄靳太守子鲁","f":"五言律诗","c":["花发上林时，君行我在兹。","三春不相见，千里自同思。","白发留燕市，青蘋寄楚词。","郡楼应独眺，未拟北来期。"]},{"t":"题萧鸿胪文萃园亭","f":"五言律诗","c":["京国论交久，知君道气存。","买书无积俸，好客有閒园。","月近池边榻，云低花下樽。","偶来堪避俗，何必问桃源。"]},{"t":"寄赵总戎公僎","f":"五言律诗","c":["闻道干城将，频年未解颜。","身危征战后，名定是非间。","海月窥龙剑，沙云接雁山。","谁怜赵充国，白首卧榆关。"]},{"t":"夜集孙郎中文揆宅赋得月字","f":"五言律诗","c":["关山不见月，玉笛未须吹。","水暗鱼龙窟，云深乌鹊枝。","开樽成露坐，作赋待秋期。","还拟梁园夜，邹枚况在兹。"]},{"t":"秋夜同应驾部瑞伯宿三河驿得宵字","f":"五言律诗","c":["荒村回远火，古驿驻征轺。","蓬鬓人间老，萍踪蓟北遥。","繁星耿秋汉，鸣柝乱寒宵。","忽忆山中桂，清霜叶又凋。"]},{"t":"赴石门峡","f":"五言律诗","c":["石门西去道，烟色树冥冥。","秋草地全白，夕阳山更青。","闻虫惊节序，立马问边庭。","潦倒还词赋，徒惭两鬓星。"]},{"t":"石门秋夜有怀","f":"五言律诗","c":["歇马空山夕，劳歌塞上归。","野霜明古剑，峡月冷秋衣。","坐里蛩螀乱，愁边乌鹊飞。","酒杯时在手，不与故人挥。"]},{"t":"春雨感怀","f":"五言律诗","c":["漠漠春天雨，冥冥晚树花。","山云迷客路，海燕落人家。","浊酒聊生计，狂歌任岁华。","异时怀杜甫，老病滞三巴。"]},{"t":"夏日同武元康刘复之杜约夫万金渠流觞","f":"五言律诗","c":["城西六月暮，笛里万山秋。","野水天光净，沙汀日色浮。","清觞聊泛泛，白鸟任悠悠。","逸少今千载，何人复胜游。"]},{"t":"送吕试官宗夔入蜀","f":"五言律诗","c":["西蜀有扬马，君才当此行。","几年怀胜迹，今日慰平生。","地入黄牛峡，江连白帝城。","停骖勒铭处，独见古人情。"]},{"t":"独步","f":"五言律诗","c":["野田聊独步，风物漫幽思。","地迥秋山出，天空暮雨垂。","石梁閒鹳鹤，水国静蛟螭。","旷士成衰谢，宁无狗监知。"]},{"t":"暮秋同冯直卿秦廷献李士美游黄花山 其一","f":"五言律诗","c":["太行秋色老，步屧一探奇。","草白高欢殿，山空王母祠。","飞泉堪倚杖，落日尚挥卮。","松外浮云去，幽人意独迟。"]},{"t":"暮秋同冯直卿秦廷献李士美游黄花山 其二","f":"五言律诗","c":["高崖翻槲叶，白日雨声寒。","共爱秋山好，其如芳蕙残。","乱云藏怪石，空壑下清湍。","底事林间鹤，栖栖刷羽翰。"]},{"t":"暮秋同冯直卿秦廷献李士美游黄花山 其三","f":"五言律诗","c":["深入黄花谷，高临玉女台。","迎人千嶂出，随意一樽开。","寒露垂瑶草，秋风扫石苔。","子长耽胜绝，猿鸟莫相猜。"]},{"t":"宿黄花寺","f":"五言律诗","c":["横野千重壁，飞空百丈泉。","松门临巨壑，石阁架长烟。","月下惟清梵，林中有静缘。","此心元不染，秋水照青莲。"]},{"t":"春日游清凉山柬孟德用","f":"五言律诗","c":["沙暖青蒲出，山晴碧树分。","琴樽閒傍水，杖屦独披云。","旷野流春气，高峰驻夕曛。","芳时不可负，寄语孟参军。"]},{"t":"北园同刘国藩夜酌","f":"五言律诗","c":["花时招酒伴，几度北林游。","改席依芳树，鸣琴对碧流。","天高微月出，沙迥断烟浮。","明日还乘兴，垂竿杜若洲。"]},{"t":"寄郭太史质夫","f":"五言律诗","c":["直北京华地，仙郎足胜游。","云低金阙暮，月动玉堂秋。","草诏传天语，题诗见国忧。","茫茫湖海上，有客寄渔舟。"]},{"t":"题背面美人图","f":"五言律诗","c":["无那琵琶曲，重弹调转凄。","自伤倾国色，故作背人啼。","太液秋光冷，长门夜月低。","流莺何意思，飞过掖庭西。"]},{"t":"怀仙吟","f":"五言律诗","c":["海上安期子，飘然与世违。","三丘来采药，万里蹑云归。","山鬼窥丹灶，鲛人识羽衣。","相从渺何许，秋月见馀辉。"]},{"t":"侠客行","f":"五言律诗","c":["五陵豪侠士，意气欲横天。","出入长耽酒，交游不惜钱。","斗鸡输宝剑，逐兔落金鞭。","动说成功易，如今又几年。"]},{"t":"塞上曲","f":"五言律诗","c":["百战多枯骨，秋高白草深。","飞雕盘大漠，嘶马振长林。","柔远君王德，封侯壮士心。","华夷自有限，边徼莫相侵。"]},{"t":"丁香","f":"五言律诗","c":["紫花何太媚，静女若为看。","影动帘栊晓，香沉烟雨寒。","芳菲心有托，零落思无端。","一采归金屋，春深莫倚阑。"]},{"t":"寒食","f":"五言律诗","c":["族次惊寒食，流年鬓有华。","春风吹燕子，初日照梨花。","丘垄天边泪，江湖梦里家。","古来词赋客，拓落但长嗟。"]},{"t":"南巡歌二首 其一","f":"五言律诗","c":["大道军容肃，中天王气高。","风云随凤辇，日月动龙袍。","绿野开三殿，黄河集万艘。","竟陵恐迟暮，原庙荐樱桃。"]},{"t":"南巡歌二首 其二","f":"五言律诗","c":["南楚旌旗合，黄尘走百官。","天王重巡幸，民物识艰难。","驰道春风动，行宫夜月寒。","万年垂拱意，歌颂入长安。"]},{"t":"同冯汝隆万泉山","f":"五言律诗","c":["林壑最幽处，乱泉风雨来。","云中山路转，树里石门开。","高兴题苍壁，长歌坐碧苔。","好为猿鹤主，閒醉百年杯。"]},{"t":"题何柏斋侍郎山居","f":"五言律诗","c":["茅宇依泉石，游心自太空。","檐垂松叶露，门掩稻花风。","世故端居外，天真独卧中。","平生爱疏广，今古几人同。"]},{"t":"酬五岳山人黄勉之见寄","f":"五言律诗","c":["人壮三吴地，天开五岳图。","神交江月迥，目极海云孤。","老凤鸣琪树，秋花照玉壶。","洞庭骚雅会，知尔说狂夫。"]},{"t":"秋兴四首 其一","f":"五言律诗","c":["寥落天涯客，谁堪秋气深。","风烟凄大野，霜日净空林。","对镜嗟衰白，衔杯任陆沉。","子云多著述，百代有知音。"]},{"t":"秋兴四首 其二","f":"五言律诗","c":["山昏云到地，江白雨连天。","鸿雁寒无赖，芙蓉秋可怜。","旅怀须痛饮，世事且高眠。","京国迷茫外，空歌美女篇。"]},{"t":"秋兴四首 其三","f":"五言律诗","c":["啸歌谁会意，风色动严城。","天夕孤鸿过，山秋万树鸣。","故人湖海梦，游子岁时情。","坐惜瑶芳歇，空除又月明。"]},{"t":"秋兴四首 其四","f":"五言律诗","c":["地旷糜芜老，庭空蟋蟀寒。","山河秋瑟瑟，风露夜漫漫。","白首谁同醉，黄花祗自看。","吾生真浪迹，沧海一渔竿。"]},{"t":"晚秋呈崔后渠侍郎","f":"五言律诗","c":["野旷烟岚重，山深杖屦迟。","菊花留晚色，松树挺寒枝。","霜下百虫伏，风前孤鸟悲。","苍生忧悴日，独有老臣知。"]},{"t":"北塞","f":"五言律诗","c":["朔漠名王遁，长城候骑还。","丁男空郡国，甲士壮边关。","玉剑横霜冷，雕弓抱月閒。","于今多上将，谈笑定天山。"]},{"t":"秋怀柬卫子涵","f":"五言律诗","c":["细雨秋山净，寒烟暮野空。","龙蟠无浊水，凤宿有孤桐。","世业兵戈后，年光客旅中。","云林千古意，寂寞几英雄。"]},{"t":"春日都下言怀","f":"五言律诗","c":["煮药花朝过，中宵坐黯然。","楼空万井月，树合九门烟。","多病还词赋，孤怀且岁年。","沧江有白鸟，来往钓矶边。"]},{"t":"酬马子端","f":"五言律诗","c":["若木横西极，鲲鱼鼓北溟。","壮图双鬓黑，不寐一灯青。","曙月低花苑，春烟澹石屏。","上公开阁日，暂尔谢山灵。"]},{"t":"崔太傅北园同张光禄友衡陈礼部子发闻人礼部元科吴大理希明得诗字","f":"五言律诗","c":["胜地成高会，云和度曲时。","百花明院落，一鸟下台池。","待月仍呼酒，看山共赋诗。","凤城春色暮，莫负牡丹期。"]},{"t":"同内阁张友衡张文光二公饮崔京山园亭","f":"五言律诗","c":["锦石高于屋，名香霭若云。","笙镛间清响，花草杂幽芬。","人醉瑶京酒，天成紫阁文。","广除多皓月，改席坐宵分。"]},{"t":"夏日崔西峨宅同张水部德杨醉赋","f":"五言律诗","c":["日暮重门寂，风凉独树斜。","一樽元亮宅，万卷子云家。","白石垂兰叶，清池出藕花。","水曹同取醉，庭宇落残霞。"]},{"t":"宿淇门驿怀孙方伯性甫王宪副廷瞻江少参伯阳","f":"五言律诗","c":["驻马淇门夕，堂空暑气徂。","乱云关树暝，寒雨驿灯孤。","身计聊时序，乡心复道途。","何当报知己，秋雁满江湖。"]},{"t":"表兄周平基书至","f":"五言律诗","c":["兄弟成脩阻，霜空一雁过。","桑麻怀故国，烟月梦西河。","短杖徘徊意，孤樽慷慨歌。","相思秋又暮，白发竟谁多。"]},{"t":"寄王东畬","f":"五言律诗","c":["我游京国去，君向邺城来。","自拂灯前剑，谁传花下杯。","停云虚夜馆，落月旷秋台。","鸿雁飞何处，相思赋七哀。"]},{"t":"元日","f":"五言律诗","c":["异乡今日酒，无那客愁新。","风落千林雪，天回万谷春。","儿童催老大，物候感沉沦。","何限长堤柳，青青又向人。"]},{"t":"古意","f":"五言律诗","c":["南国动幽思，春洲搴绿芳。","九嶷云物夕，帝女怨潇湘。","华月照瑶瑟，灵风吹绮裳。","那知苦调罢，楚客立苍茫。"]},{"t":"同李汝锡马伯龄游苏门山柬王明府","f":"五言律诗","c":["好山同一赏，行坐有莓苔。","潭上幽花照，樽前白鸟来。","放歌风振木，起舞月临台。","欲刻苏门石，惭非谢朓才。"]},{"t":"雨后柬张宗昭","f":"五言律诗","c":["雨后小园净，豆花寒更开。","客中秋序过，灯下雁声来。","懒慢催诗句，疏狂但酒杯。","故人期不至，凉月满高台。"]},{"t":"过山叟","f":"五言律诗","c":["栗里堪同隐，濠梁复一过。","衡门开绿野，石壁带青萝。","偶共山人醉，閒随牧子歌。","还怜夜色好，星月湛沧波。"]},{"t":"秋夜柬张崇德","f":"五言律诗","c":["满天风摵摵，木叶下山城。","夜静群虫响，秋高片月清。","多方身计拙，无病旅愁轻。","仲蔚深知己，悠悠江汉情。"]},{"t":"过仪封呈大司马王浚川","f":"五言律诗","c":["行客度河甸，空林寒日初。","风高脆蒲苇，水落困龙鱼。","民物诛求际，边陲战伐馀。","济时须大老，莫恋草玄庐。"]},{"t":"古怨 其一","f":"五言律诗","c":["高楼俯江树，楼上有蛾眉。","旧约空成叹，新愁可诉谁。","春閒翡翠幕，月冷杜鹃枝。","荡子复何处，杨花无定时。"]},{"t":"古怨 其二","f":"五言律诗","c":["杨花日飘荡，能复几何春。","远道宁知妾，流年不待人。","片云横上国，独鸟下西秦。","无奈怀君意，清江采绿蘋。"]},{"t":"古怨 其三","f":"五言律诗","c":["绿蘋时复采，独立转深愁。","忆昔郎船去，极天江水流。","玉环应自佩，金谷谩长游。","可惜铅华落，西风入画楼。"]},{"t":"春日同双泉清泉涌泉西泉四将军园酌","f":"五言律诗","c":["南园鸣布谷，烟雨万家春。","庭草乱依榻，山云低傍人。","当歌惟胜地，快意几芳辰。","醉杀高阳客，花前倒葛巾。"]},{"t":"登城有感奉寄江宁王怀易","f":"五言律诗","c":["野风吹客袂，感慨一登城。","孤鸟日边没，大河天外倾。","年华悲杜甫，世故老虞卿。","龙剑应相合，云霄无限情。"]},{"t":"渡黄河","f":"五言律诗","c":["路出大梁城，关河开晓晴。","日翻龙窟动，风扫雁沙平。","倚剑嗟身事，张帆快旅情。","茫茫不知处，空外棹歌声。"]},{"t":"集孟得之园亭","f":"五言律诗","c":["万竹生秋意，林园六月初。","骚人宜物色，樽酒坐庭除。","落日横孤嶂，清风满太虚。","兴高归去晚，池上采芙蕖。"]},{"t":"秋日洹上书怀","f":"五言律诗","c":["水边沙草合，林外石桥横。","云漫三秋色，河流万古声。","野花欺老鬓，林酒胜浮名。","我爱桐江叟，渔竿不世情。"]},{"t":"同李元博携酒访岐南道人","f":"五言律诗","c":["共向东园酌，葫芦秋正花。","千畦散流水，万木带飞霞。","碧海仙人岛，玄都道士家。","未应骑鹤去，聊此话丹砂。"]},{"t":"怀玉清阁","f":"五言律诗","c":["紫阁登临处，秋光入品题。","窗吞河岳尽，檐压斗牛低。","客路孤城外，仙坛万岭西。","浮丘分袂后，望断白云梯。"]},{"t":"怀香山寺","f":"五言律诗","c":["曾识京西路，名山梵帝家。","殿高千岭树，地落半天霞。","空外钟声彻，云边塔影斜。","老禅相对处，笑指白莲花。"]},{"t":"送朱君归都下","f":"五言律诗","c":["君来邺城雪，君去蓟门秋。","生计疏乡信，归期减客愁。","光阴多道路，慷慨几交游。","谁识燕歌处，孤云傍酒楼。"]},{"t":"送刘佥宪才甫北伐","f":"五言律诗","c":["七月边烽动，三河兵气扬。","乘秋发猛士，计日缚名王。","剑倚云霄迥，旗连海雾长。","燕然一片石，终古有馀光。"]},{"t":"送杜敬夫有事显陵","f":"五言律诗","c":["匹马飞千里，孤帆截九河。","天南郢州道，月下楚人歌。","陵庙楸梧冷，江城云雾多。","万年帝灵在，神鬼护山河。"]},{"t":"怀碧云寺","f":"五言律诗","c":["群山开宝地，忆昔杖藜过。","石洞馀冰雪，岩泉净薜萝。","虚空尘虑尽，疏散胜缘多。","欲结东林社，相依老洞阿。"]},{"t":"同邹汝邻张伊梁李元博饮申幼川北园登台醉赋","f":"五言律诗","c":["朋好多风雅，园林复此游。","天边数峰出，台下一河流。","浦树笼苍霭，霜花照素秋。","骚人嗅芳意，莫讶为时忧。"]},{"t":"同陈石卿夜酌善应山","f":"五言律诗","c":["骚客同今夕，当杯意思閒。","天风入古树，海月到空山。","胜赏双林外，高歌万壑间。","人生竟多事，此地几登攀。"]},{"t":"送王中书嘉宾归海陵","f":"五言律诗","c":["华发紫薇郎，鸣鞭下帝乡。","莼鲈新味美，丘垄故思长。","海国连秋气，江皋带晚芳。","兴来一鼓枻，谁与咏沧浪。"]},{"t":"秋夜寄郭黄州","f":"五言律诗","c":["久别多遐思，惊心夜半鸿。","霜飞邺台冷，月照楚江空。","感慨三秋过，徵求万邑同。","细侯深有意，聊尔托长风。"]},{"t":"有怀","f":"五言律诗","c":["南国美人别，长怀相见初。","不传万里信，閒杀九江鱼。","白发增长叹，黄花伴索居。","夜深风露下，犹自立前除。"]},{"t":"寄孙尧峰把总","f":"五言律诗","c":["同衰不相见，忆昔蓟门逢。","送别吴帆远，含思燕树重。","湖光閒鹳鹤，秋色净芙蓉。","月下长安梦，枫桥夜半钟。"]},{"t":"吴下洞庭两山诗客每从予游四十年来凋敝尽矣率成短律用志悲感","f":"五言律诗","c":["胜地阖闾国，沧波范蠡船。","山通转折路，湖抱混茫天。","丝管春风里，松楸晚照边。","人家几歌哭，谁尽白头年。"]},{"t":"张二守鸣远携酒夜过禅房率尔赋赠","f":"五言律诗","c":["携酒出偶尔，随意是端居。","垂老诗犹进，能狂礼不疏。","兴高云影外，心悟磬声馀。","每过论三昧，无令禅榻虚。"]},{"t":"寄杨中丞伯谦","f":"五言律诗","c":["晋俗犹秦俗，君来化自同。","多忧关大计，两镇得全功。","雪尽西山迥，云閒朔漠空。","樵苏幸无事，四野共春风。"]},{"t":"和王侍御沁阳再逢除夕","f":"五言律诗","c":["复此岁将尽，乌啼霜满城。","孤灯千里客，夜半两年情。","北望边愁剧，西来鬓发更。","乘春发骢马，犹自问苍生。"]},{"t":"送钦水部子辰之沛中","f":"五言律诗","c":["清标怜水部，南去意何穷。","树色分淮甸，河流见禹功。","乱帆春草外，古堞暮云中。","感慨登台处，萧萧起大风。"]},{"t":"送王行人维藩使汝南","f":"五言律诗","c":["仙郎宠命新，向晓发征轮。","去路梁园雪，归期燕谷春。","王孙瞻绛节，候吏走黄尘。","想过仲宣宅，还怜作赋人。"]},{"t":"寄北海冯汝强","f":"五言律诗","c":["旷矣青云路，凄其白发年。","病多还自遣，赋就几人怜。","三径迷秋草，孤鸿断雪天。","相期九节杖，定访十洲仙。"]},{"t":"送徐比部汝思使蜀中 其一","f":"五言律诗","c":["何处看春色，江城花鸟繁。","射洪一樽罢，骚雅几人存。","日下铜山静，云连赤岸昏。","更怜陈正字，零落狱中魂。"]},{"t":"送徐比部汝思使蜀中 其二","f":"五言律诗","c":["春草遍三川，征轺入蜀年。","栈通星使路，岭断夜郎天。","关塞双旌转，风霜一剑悬。","劳歌对明月，江上几回圆。"]},{"t":"春日同李于鳞王元美比部集韦氏水亭得韵二首 其一","f":"五言律诗","c":["都门联辔出，此地访烟萝。","共酌清樽酒，还成白苧歌。","春云花外度，幽鸟水边多。","更拟池亭上，相将采芰荷。"]},{"t":"春日同李于鳞王元美比部集韦氏水亭得韵二首 其二","f":"五言律诗","c":["我来凭水槛，坐久夕阳斜。","聊复祛尘事，相将揽物华。","河山百战地，桑柘几人家。","纵有明春约，还看何处花。"]},{"t":"春游","f":"五言律诗","c":["古道一鸣鞭，苍茫雨后天。","湖明春草外，寺隐暮云边。","野浦还垂钓，山房欲问禅。","客中幽事少，独愧白头年。"]},{"t":"和王比部元美喜浚人卢楠冤雪之作","f":"五言律诗","c":["春从邹律动，近得破愁颜。","心事孤灯下，年光万死间。","赋成馀白发，身在有青山。","共尔烟霞约，飘然去不还。"]},{"t":"送蒋判官子重之泰安","f":"五言律诗","c":["策马齐中道，行当佐郡忧。","城连岱云起，地接海天浮。","赋税徵兵日，星霜报国秋。","有怀时北望，寒雁下河洲。"]},{"t":"朱郎中伯邻养疴道院雨中见召赋此答之","f":"五言律诗","c":["习静依山侣，同怀复见招。","三花烟雨隔，一鹤洞天遥。","寒逼青霞馆，泥深白石桥。","月明应不负，樽酒听吹箫。"]},{"t":"送苏子冲之云中","f":"五言律诗","c":["翩翩苏季子，征马独嘶风。","路转河声近，星摇剑气雄。","旌旗閒塞上，笳鼓静云中。","试看和戎后，谁收不战功。"]},{"t":"季夏夜过郭学士质夫馆得流字","f":"五言律诗","c":["客居度烦暑，仙馆得清秋。","华露凉浮动，明河夜转流。","思乡还自赋，秉烛且同游。","潦倒谁招隐，淮南桂树幽。"]},{"t":"同沈禹文周君可二参军集章子吉参军宅时章景南行人至自上党即席赋此","f":"五言律诗","c":["使星昨夜转，车骑入长安。","共喜传觞好，犹言行路难。","蝉声风外断，槐色雨中寒。","起舞苍龙剑，光芒几度看。"]},{"t":"登楼北望怀郭学士质夫李吏部一元","f":"五言律诗","c":["李郭风骚匹，登楼独怅然。","黄花秋满地，白雁夕横天。","玉阙云霄外，金门日月边。","疏狂燕赵客，早晚赋甘泉。"]},{"t":"夏夜邹参政君哲宅陪饯皇甫别驾得才字","f":"五言律诗","c":["磊落闽中彦，沉沦吴下才。","相看成别赋，一笑且深杯。","庭暗流萤过，楼明缺月来。","新丰能几醉，骑马故迟回。"]},{"t":"夏日大雨","f":"五言律诗","c":["小楼动秋意，风雨忽来时。","暗失黄尘陌，平开绿草池。","朝閒成久卧，气爽得新诗。","车马访幽独，冲泥竟有谁。"]},{"t":"遣怀","f":"五言律诗","c":["天地此生浮，贪名岂道流。","何为儿女计，徒遣岁时忧。","取醉江花日，行歌岭树秋。","向平元有约，南尽白云游。"]},{"t":"立秋夜有感","f":"五言律诗","c":["秋生一叶初，摇落重愁予。","宋玉悲何晚，嵇康计亦疏。","星明孤剑动，月白小楼虚。","为忆同心者，天涯未报书。"]},{"t":"秋夜石户曹君采宅留别得云字","f":"五言律诗","c":["无那天涯别，寒蛩可更闻。","烛花还对我，尊酒暂同君。","夜驻西山月，秋生北塞云。","他时重相忆，惆怅几宵分。"]},{"t":"张少参子明见过","f":"五言律诗","c":["病客掩扉卧，时闻车马临。","几来燕市里，能识鲁生心。","独树秋先老，浮云昼欲阴。","况逢忧国际，谁为访山林。"]},{"t":"章景南署中对竹","f":"五言律诗","c":["谁种此亭竹，当樽一问君。","相看成野意，自觉远尘氛。","幽色霜前见，秋声月下闻。","醉来堪隐几，清梦入湘云。"]},{"t":"秋夜雪后同王给事以宁集胡进士文澄宅予病先归","f":"五言律诗","c":["客醉黄花月，堂开白雪天。","重城辉夜色，老树夺春妍。","已负金樽酒，那成宝剑篇。","病来扶上马，归向小楼眠。"]},{"t":"高比部伯宗宅夜集得清字","f":"五言律诗","c":["铜漏夜初涩，冰壶韵转清。","月澄天汉影，风落禁钟声。","病里疏身计，天涯得友生。","后期无定所，江海共含情。"]},{"t":"冬夜同徐比部子与吴舍人明可听张肖甫鼓琴得声字","f":"五言律诗","c":["夜过成都客，风流羡长卿。","壶觞移烛影，山水入琴声。","庭敞风初断，天寒月更明。","他时轩冕会，应记薜萝情。"]},{"t":"送刘推官子礼之平阳","f":"五言律诗","c":["人怜燕市别，才羡洛阳奇。","春色迎骖动，民情到郡知。","天低姑射岭，云抱帝尧祠。","几为看汾水，东流寄所思。"]},{"t":"送卢司业浚卿再赴南都 其一","f":"五言律诗","c":["相忆江湖远，相逢京国初。","羽觞春欲动，宫漏夜何如。","客久惭怀刺，年衰可著书。","君仍金马诏，吾竟白云居。"]},{"t":"送卢司业浚卿再赴南都 其二","f":"五言律诗","c":["阳城复南去，岁晚上吴船。","寒尽秣陵雪，春浮扬子天。","一官心自远，六代赋同传。","何异碧山下，萧条著述年。"]},{"t":"吴舍人明可徙居同徐子与刘子成二比部夜集得书字","f":"五言律诗","c":["仙郎近卜居，几乘载图书。","邻里通名后，墙头过酒初。","漏沉丹禁远，烛动碧窗虚。","补衮才无暇，明朝向石渠。"]},{"t":"送许中丞伯诚镇辽阳","f":"七言律诗","c":["雄才当代拟登坛，东度榆关岁欲残。","燕峤暮云天外起，辽河春水雪中寒。","艰虞自谓匡时晚，战伐谁知得士难。","谩说请缨平百越，行看仗策静三韩。"]},{"t":"送陈太守仲声还任金华","f":"七言律诗","c":["双旌带雪下长安，晓色催人马上寒。","不惮风尘驰驿道，应知父老伫江干。","金华云隔三千里，碧草春生五百滩。","遥想元龙乘暇处，高楼明月共谁看。"]},{"t":"留别程侍御信夫宋比部汝化","f":"七言律诗","c":["孤琴瘦马临长陌，执手那堪惆怅色。","雪中疏柳动啼鸦，林外斜阳催去客。","二子正当经济时，我向江湖任所之。","故乡意气且杯酒，天外浮云安可期。"]},{"t":"冬夜宗考功子相宅同张比部士直钱进士惟重饯别方行人仲安使阙里便道还蜀","f":"七言律诗","c":["虚堂秉烛共开樽，岁晚梅花发禁园。","南北交情今夜醉，江湖别思几时论。","天边候雁逢燕使，雪后春泥过鲁门。","家在涪川暂归去，万峰回首隔中原。"]},{"t":"酬王侍御子梁见寄","f":"七言律诗","c":["台畔乌啼夜独醒，忧时不寐向中庭。","几看燕峤秋云白，三度梁园春草青。","梦断关河惊过雁，书传南北感浮萍。","君才况值艰虞日，骢马归来鬓欲星。"]},{"t":"春日洹上閒居","f":"七言律诗","c":["芳草洲边春水生，苍茫霁色动柴荆。","风吹杨柳幽人卧，日上梨花独鸟鸣。","泉石自能忘俗事，壶觞聊复寄閒情。","千年好忆东方朔，金马能兼大隐名。"]},{"t":"公子行","f":"七言律诗","c":["少年公子美容光，共羡豪华倾大梁。","花柳旅开驰马路，金珠乱掷斗鸡场。","青楼对舞春无歇，白纻娇歌夜未央。","独有侯生空老大，夷门风雨自悲凉。"]},{"t":"送张别驾赴秦中","f":"七言律诗","c":["晓别孤城鸦乱啼，函关迢递正春泥。","马经三辅雪霜后，路出五陵松柏西。","烽火独愁秦塞迥，郡楼长望陇云低。","宝刀灵气君堪佩，晋代功名定与齐。"]},{"t":"送沈克昌东归","f":"七言律诗","c":["孤琴漂泊气难平，老傍天涯复邺城。","四海知音须我辈，一朝倾盖识君情。","官桥疏柳高秋色，旅馆寒螀独夜声。","太石潭边好归去，渔竿不负野鸥盟。"]},{"t":"送谢武选少安犒师固原因还蜀会兄葬","f":"七言律诗","c":["天书早下促星轺，二月关河冻欲消。","白首应怜班定远，黄金先赐霍嫖姚。","秦云晓度三川水，蜀道春通万里桥。","一对郫筒肠欲断，鹡鸰原上草萧萧。"]},{"t":"送章行人景南使闽中","f":"七言律诗","c":["春尽天涯感别离，沧波极目去帆迟。","江南到处搴芳杜，海上先秋荐荔枝。","明月每劳燕市梦，白云遥寄越乡思。","山灵暂尔留旌节，独立西风赋武夷。"]},{"t":"送宋行人进之使太原潼关诸郡","f":"七言律诗","c":["高城拂曙乱鸦啼，别酒临风征马嘶。","使节天边云渺渺，王程春暮草萋萋。","黄河南去晋山断，紫塞西连秦树低。","宋玉三秋还有赋，谁同华岳一攀跻。"]},{"t":"夜饯周时隆表兄东归","f":"七言律诗","c":["弟兄此别重伤神，况复淹留一病身。","白发相看偏堕泪，清樽才罢转愁人。","江鸿北转燕山夜，河柳东连鲁甸春。","若到乡关逢故老，为言游子倦风尘。"]},{"t":"送何进士振卿谪乐平少尹","f":"七言律诗","c":["都亭同醉采芳菲，别后关山梦不违。","平野北看燕树断，大江西去楚帆飞。","百花洲上还闻雁，五老峰头独振衣。","胜地且留何逊赋，春风应见贾生归。"]},{"t":"送白户曹贞甫之三河","f":"七言律诗","c":["御河春草才倾盖，驿道炎风复送君。","候骑迟留今日醉，美人消息几时闻。","孤城北向天门近，三水东流地脉分。","渐老江州白司马，建章回首隔重云。"]},{"t":"秋夜过吴职方子有宅","f":"七言律诗","c":["凤城西畔独寻君，无奈寒蛩坐里闻。","灯下旅愁惊老至，天涯秋兴醉宵分。","禁钟隐隐来深院，海月微微出断云。","绿酒黄花知有约，不辞风雨更论文。"]},{"t":"秋夜陈内翰子结第同孟得之对月有赋","f":"七言律诗","c":["陈遵投辖罄交欢，池上酣吟并倚栏。","月到玉堂秋转静，天回瑶阙夜偏寒。","坐听客子穿云笛，恍见仙人承露盘。","金马明晨还待诏，清光应忆此时看。"]},{"t":"秋集道院因同徐库部子明醉赋","f":"七言律诗","c":["寄迹京华胜赏稀，偶来仙院静尘机。","明河倒影夜低户，凉露无声秋满衣。","铜漏滴残人共醉，玉笙吹断鹤孤飞。","空庭改席多幽兴，月落长安并马归。"]},{"t":"中秋无月同李子朱王元美李于鳞比部赋得城字","f":"七言律诗","c":["四野苍茫云雾生，月华暗度凤凰城。","樽前不辨银河影，楼外空传玉笛声。","鸿雁清秋游子意，梧桐白露故园情。","谢庄欲赋还惆怅，今夜关山何处明。"]},{"t":"寄洞庭山邹子序","f":"七言律诗","c":["雁书寄意三秋过，龙剑藏灵两地分。","旧日交游思共醉，他乡风物感离群。","笛中夜落关山月，楼外天连海峤云。","老去相逢定悲怆，吴歌对酒不堪闻。"]},{"t":"重阳夜感怀","f":"七言律诗","c":["月冷燕城断旅魂，广庭风露坐来繁。","老将浊酒酬今夕，秋到黄花忆故园。","多病淹留孤剑在，当年游好几人存。","狂歌重此登高意，满眼浮云不可论。"]},{"t":"送顾汝修归上海","f":"七言律诗","c":["千里飞霜叶下初，知君回首忆鲈鱼。","潮生瓜步移孤棹，路转吴淞是旧庐。","海上白云秋不断，天南明月夜何如。","梅花岁暮应攀折，驿使相逢有报书。"]},{"t":"宿榆林驿","f":"七言律诗","c":["寒夜榆林门独开，愁看霜露满苍苔。","驿灯孤照征人梦，边月高悬落雁哀。","冒顿几窥青海戍，烽烟又上白登台。","当年李广空遗恨，萧飒天风正北来。"]},{"t":"望云中塞","f":"七言律诗","c":["几年欲向塞门游，北渡桑乾重旅愁。","画角悲凉孤馆夜，黄榆摇落九边秋。","壮心未掷班生笔，浪迹堪怜季子裘。","回首江湖任鸥鸟，谩嗟华发滞燕州。"]},{"t":"送李郎中子朱出守东昌","f":"七言律诗","c":["丹凤城南祖席开，使君行色晓星催。","蓟门旌旆乘空下，海岱风云入郡来。","退食还披龚遂传，振衣应上鲁连台。","东方彫弊非当日，独为苍生赋七哀。"]},{"t":"冯郡丞汝言入计暂还海口吴郎中峻伯沈参军子刚出饯同赋得山字","f":"七言律诗","c":["岁暮长安送客还，驿亭疏柳不堪攀。","星轺欲发仍呼酒，春草相期一解颜。","陌上清霜迎剑舄，笛中明月动关山。","海门冻合三吴舫，此日冯唐鬓易班。"]},{"t":"立春日与周一之文德承李时明马怀玉集李伯承馆时还宰新喻得天字","f":"七言律诗","c":["禁苑高楼动霁烟，玉盘生菜感流年。","吴歌晚聚江南客，邹律春回冀北天。","久别共嗟饶素发，相逢能醉几芳筵。","柳条渐长应攀折，又向官河送楚船。"]},{"t":"送符主簿之蜀","f":"七言律诗","c":["陌上离歌仍把袂，樽前芳草惜离群。","逶迤独马乘春去，断续清猿入夜闻。","锦水东摇三峡月，蜀天西尽万山云。","宦游莫惜梅花信，岁暮长安定忆君。"]},{"t":"和人金陵春日感兴","f":"七言律诗","c":["吴客风流似季鹰，钟山佳丽兴堪乘。","高台凤去还临眺，胜地龙蟠几废兴。","九陌晴云通玉阙，三江春水抱金陵。","莫愁何处歌杨柳，独听黄鹂思不胜。"]},{"t":"送朱明府仲开谪平乐教授","f":"七言律诗","c":["黄鸟鸣时别禁园，宦情南去复谁论。","郑虔此日聊诗句，陶令何年共酒樽。","秋到百蛮思北雁，云迷三楚望中原。","沧江寂寞芙蓉老，官舍长歌独闭门。"]},{"t":"天宁寺同章景南李于鳞王元美饯别李伯承还宰新喻得春字","f":"七言律诗","c":["野寺门前杨柳新，一樽同此驻征轮。","西山物候仍馀雪，南国芳菲更有春。","楚棹正逢归塞雁，淮云遥送渡江人。","他时陶令应相忆，不待秋霜下绿蘋。"]},{"t":"寒食夜感怀","f":"七言律诗","c":["帝里年华重旅愁，几回清梦到沧洲。","看花多病虚寒食，秉烛何人共夜游。","乡思转添春过雁，剑歌初断月当楼。","梁园旧侣今零落，天际黄河空自流。"]},{"t":"送栗道夫下第归上党","f":"七言律诗","c":["早岁名成庾信流，春风走马向燕州。","壮心对酒惟长剑，华发论文一敝裘。","落日寒生杨柳陌，乱云晴绕凤凰楼。","圣朝何事淹才子，归卧青山复几秋。"]},{"t":"送许克之下第归历城","f":"七言律诗","c":["独马迟迟春尚寒，晓冲疏雨出长安。","白云又伴山中卧，芳草谁同湖上看。","不负才名须狗监，岂容生事老渔竿。","壮游共拟磨崖赋，海岱秋高木叶丹。"]},{"t":"送鸟鼠山人胡世甫西归","f":"七言律诗","c":["愁中忽过蓟门春，归骑萧条复向秦。","白首全生逢圣主，青山何意见骚人。","陇云朝度乡关近，渭水晴分草树新。","自是扬雄多著述，百年宁负旧纶巾。"]},{"t":"寄陈潮州","f":"七言律诗","c":["不见元龙重倚楼，遥看天畔碧云流。","东方紫马嘶何处，南服苍生系此忧。","海气郁蒸长似夏，蛮烟苍莽独宜秋。","凤凰山下相思树，攀折还能寄旧游。"]},{"t":"又得寒字","f":"七言律诗","c":["出郭乘时父老欢，频年稼穑问艰难。","边烽自不虚龙剑，客礼谁能重鹖冠。","地合千松山更秀，天垂片雨日多寒。","秋来逸兴今朝醉，老去新诗异代看。"]},{"t":"秋夜同李明府子充登圆通阁兼示懒上人","f":"七言律诗","c":["清秋风物兴堪乘，杰阁凌云共此登。","自谓官轻随旷达，不令人妒见才能。","披襟气爽中宵露，俯槛星摇下界灯。","何处招提可游眺，万山形胜几诗僧。"]},{"t":"寄怀李藩相子成","f":"七言律诗","c":["早岁飘然别楚关，知君古道宦游间。","能求马首计何远，不妒蛾眉心自閒。","河朔晓霜明一剑，邺西秋色老千山。","徐陈彫丧应多感，独摘黄花解醉颜。"]},{"t":"园亭秋雨李之茂惠酒","f":"七言律诗","c":["圣代逍遥一角巾，西来况尔识予真。","园扉半掩琴书静，庭树相依鸟雀驯。","荒径自怜苔色古，白衣宁待菊花晨。","天涯风雨聊成醉，坐惜冲泥送酒人。"]},{"t":"梦吴人张德良同泛扬子江偶得一联黄芦港外群峰出青石滩头独鹤鸣醒而足之","f":"七言律诗","c":["不见词人忆旧盟，清秋梦到阖闾城。","黄芦港外群峰出，青石滩头独鹤鸣。","共傍江湖存逸气，自怜萍梗寄浮生。","一樽忽罢仍南北，落月空梁无限情。"]},{"t":"九日齐明府思钦见过","f":"七言律诗","c":["天涯节序酒樽空，扶杖登高索寞中。","旅雁一声辞朔塞，寒砧几处乱西风。","今嗟白首亲朋隔，旧采黄花儿女同。","慰我羁怀有陶令，非关秋色过篱东。"]},{"t":"次潘国主对菊韵用述鄙怀","f":"七言律诗","c":["长铗无声食有鱼，门前倚杖雁来初。","身违故国频劳梦，力到哀年尚著书。","客子欲倾天上酒，园丁还摘雨中蔬。","因思寄傲陶彭泽，坐对秋花白露馀。"]},{"t":"答宋鸿胪仁甫寄书","f":"七言律诗","c":["登高曾约帝京楼，九日黄花各自秋。","明月相关今夜梦，白云同寄故园愁。","征夫塞上功何晚，代马霜前嘶未休。","官舍寂寥应抚剑，更将尺素问淹留。"]},{"t":"雪中感怀 其一","f":"七言律诗","c":["客怀无定几晴阴，晋俗那知半古今。","孤馆劲风翻积雪，千松寒色隐危岑。","镜垂鹤发嗟年老，剑养龙精动夜深。","昨向庭前驱斗雀，解纷还似鲁连心。"]},{"t":"雪中感怀 其二","f":"七言律诗","c":["天教强健老年身，自觉诗成调转新。","三晋关河无旅雁，万家风雪几愁人。","樽中醴酒堪怀古，笛里梅花未是春。","形胜肯淹青玉杖，乾坤何愧白纶巾。"]},{"t":"季冬十五夜蚀集云阶云涧书斋","f":"七言律诗","c":["骚雅于今伯仲知，坐谈深夜缓清卮。","雪凝苔砌光逾净，水冻莲壶漏转迟。","聚散老怀聊共醉，浮沉世事总难期。","眼前皓魄翻多感，一诵卢仝月蚀诗。"]},{"t":"初春夜过西池书斋留酌赋得钟字","f":"七言律诗","c":["燕台故事老年踪，楚调狂歌圣代容。","乘兴西来秋草遍，凭高北望暮云重。","自疏客计閒长铗，几向王门驻短筇。","春酒淹留何限意，满城华月夜深钟。"]},{"t":"得周学宪子才书并石刻诗以志谢","f":"七言律诗","c":["辛甲封疆探胜还，云萝犹忆共跻攀。","坐怜同调繁声外，老愧齐名片石间。","鹤发乡愁惟绿酒，马头春色几青山。","太原有约堪乘兴，莫使东风花鸟閒。"]},{"t":"同敏轩昆季赋得登城楼望五龙山","f":"七言律诗","c":["松杪龙山纵目时，龙精长寄万松枝。","烟岚忽动遥堪挹，风雨频来暗有期。","半世客怀聊此醉，千年帝力岂予知。","高城倚仗空幽兴，安得岩栖日赋诗。"]},{"t":"西池园赏芍药","f":"七言律诗","c":["王门设宴款应徐，红药相鲜映广除。","地簇晚芳群蝶下，天留春色万花馀。","愿将绣幕通宵护，讵使清樽半日虚。","共醉琼楼重吟赏，莫言玄圃是仙居。"]},{"t":"栗道甫夜过送别","f":"七言律诗","c":["茅屋茶烟待客时，山中别驾暮相期。","共逢昭代耽佳句，自笑残年费苦思。","入夜星河林鸟定，先秋风露草虫知。","坐谈渐转南楼月，不尽离怀归去迟。"]},{"t":"送张明府召和之边","f":"七言律诗","c":["苍茫野色度旌旗，平子乘骖西去时。","荒草乍经多事地，高秋更赋几愁诗。","黄尘风静周畿甸，紫塞云屯汉虎貔。","不信赏功贫郡邑，封章拟报圣王知。"]},{"t":"漳河秋涨候渡因忆李通政仲西","f":"七言律诗","c":["万折漳河过邺城，洪涛动地几时平。","沙边鹳鹤仍求饱，霜后鱼龙始见清。","遥忆君家临古渡，更堪旅思听寒声。","杖藜自惜徘徊影，不逐东流寄此情。"]},{"t":"寄上沈王殿下","f":"七言律诗","c":["遥忆池台丛桂芬，岂堪风俗寄河汾。","路通万树偏秋色，城隔千山更暮云。","明月每驰天外梦，寒砧不比邺中闻。","西来知遇嗟衰老，别馆孤灯坐夜分。"]},{"t":"忆茅山兼寄黄淳夫逸人","f":"七言律诗","c":["秣陵佳气日氤氲，句曲逍遥鸾鹤群。","诸洞藏真开石髓，三峰拔秀出江云。","松间月挂清秋影，天上星罗太古文。","早晚黄生换仙骨，相期南去访茅君。"]},{"t":"过朱道甫留酌分得秋字","f":"七言律诗","c":["为爱君才王勃流，樽前相对赋高秋。","关山回首偏多路，风雨惊心各一楼。","老去自知能放达，古来谁不重交游。","匣中宝剑藏灵异，莫使龙光天外浮。"]},{"t":"送王大参明甫之秦中兼寄张方伯子文","f":"七言律诗","c":["岛夷能禦待论功，歌起渔樵吴会同。","兵甲威名悬海上，旌旄行色入关中。","金城远抱山河地，宝气犹存秦汉宫。","君见张衡正秋兴，三峰欲赋两争雄。"]},{"t":"送别张佥宪肖甫之颍州兼忆徐太守子与","f":"七言律诗","c":["浮云蓟北叹相违，旧社词人各是非。","谪后两迁心事定，醉中多赋宦情微。","黄花含笑孤秋色，白雁离群几夕晖。","颍上有怀徐干远，建安风调迩来稀。"]}]};